// Visitor-analytics daily rollup. Summarises the raw `Visit` log into one
// `VisitorDaily` row per UTC day so the admin audience dashboard's trend series
// and long-range history stay cheap as the visit log grows. Best-effort: one bad
// day never aborts the sweep, and nothing here writes to Visit.
import { db } from "../lib/db";
import { computeVisitorDay } from "../lib/analytics";

/** How many trailing UTC days to (re)roll each sweep. A small window so late
 *  close-beacons (dwell time) and just-past-midnight hits still land in the
 *  right day without rescanning all of history every pass. */
const ROLL_DAYS = 3;

function utcDayStart(offsetDays: number): Date {
  const now = new Date();
  const d = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()));
  d.setUTCDate(d.getUTCDate() - offsetDays);
  return d;
}

/**
 * Roll the last few UTC days into VisitorDaily. Each day also counts signups
 * (accounts created that day) and how many of those accounts deployed a real
 * server, so the funnel has durable per-day history too.
 */
export async function visitorRollupSweep(): Promise<void> {
  for (let i = 0; i < ROLL_DAYS; i++) {
    const dayStart = utcDayStart(i);
    const dayEnd = new Date(dayStart.getTime() + 86_400_000 - 1);
    try {
      const m = await computeVisitorDay(dayStart, dayEnd);

      // Per-day funnel: signups that day + how many deployed a server.
      const signupUsers = await db.user.findMany({
        where: { createdAt: { gte: dayStart, lte: dayEnd } },
        select: { id: true },
        take: 20_000,
      });
      const signupIds = signupUsers.map((u) => u.id);
      let deployed = 0;
      if (signupIds.length > 0) {
        const rows = await db.server.findMany({
          where: {
            userId: { in: signupIds },
            status: { in: ["RUNNING", "STOPPED", "SUSPENDED", "REINSTALLING", "DELETING"] },
          },
          distinct: ["userId"],
          select: { userId: true },
        });
        deployed = rows.length;
      }

      // Recover total session dwell for the day (computeVisitorDay returns the
      // average; multiply back so the stored total stays authoritative).
      const totalSessionMs = BigInt(m.avgSessionMs) * BigInt(m.sessions);

      const data = {
        pageviews: m.pageviews,
        sessions: m.sessions,
        uniqueVisitors: m.uniqueVisitors,
        newVisitors: m.newVisitors,
        returningVisitors: m.returningVisitors,
        // Sessions with exactly one pageview that day. Computed in
        // computeVisitorDay from the same ipEx-filtered session set as
        // `sessions`, so bounces <= sessions and the stored bounce rate
        // (bounces / sessions) is consistent with the live dashboard figure.
        bounces: m.bounces,
        totalSessionMs,
        signups: signupIds.length,
        deployed,
      };

      await db.visitorDaily.upsert({
        where: { date: dayStart },
        create: { date: dayStart, ...data },
        update: data,
      });
    } catch (e) {
      console.error("[analytics] visitor rollup error", dayStart.toISOString().slice(0, 10), e);
    }
  }
}
// Ads conversion tracking — Meta Pixel + Google Ads/GA4, browser + server-side.
//
// IDs live in Settings (admin-editable, no redeploy). The browser side is injected
// by components/marketing/ConversionTags.tsx; the SERVER side is the Meta
// Conversions API (CAPI) below, which recovers the conversions iOS/ad-blockers hide
// from the pixel. Everything is inert until the IDs/token are set — no config,
// nothing fires, nothing leaks.
import { createHash, randomUUID } from "node:crypto";
import { getSetting } from "@/lib/settings";
import { decryptSecret } from "@/lib/crypto-box";

/**
 * Per-funnel Google Ads conversion labels. Each maps a funnel event to the label an
 * operator pastes from Google Ads; an empty label keeps that conversion INERT (the
 * paired Meta standard event still fires). `purchase` mirrors `googleAdsPurchaseLabel`
 * so every conversion — including the existing paid-order Purchase — is addressed the
 * same way.
 */
export type GoogleAdsLabels = {
  signup: string;
  vps: string;
  hosting: string;
  game: string;
  email: string;
  card: string;
  purchase: string;
};

export type TrackingConfig = {
  metaPixelId: string;
  ga4Id: string;
  googleAdsId: string; // AW-XXXXXXXXX
  googleAdsPurchaseLabel: string; // conversion label for a purchase
  /** Per-funnel Google Ads conversion labels (see GoogleAdsLabels). */
  googleAdsLabels: GoogleAdsLabels;
  // Server-only (never sent to the browser):
  metaCapiToken: string;
  metaTestEventCode: string;
};

/** Public (browser-safe) subset — safe to serialize into the page. */
export type PublicTrackingConfig = Pick<
  TrackingConfig,
  "metaPixelId" | "ga4Id" | "googleAdsId" | "googleAdsPurchaseLabel" | "googleAdsLabels"
>;

export async function loadTrackingConfig(): Promise<TrackingConfig> {
  const [
    metaPixelId,
    ga4Id,
    googleAdsId,
    googleAdsPurchaseLabel,
    signupLabel,
    vpsLabel,
    hostingLabel,
    gameLabel,
    emailLabel,
    cardLabel,
    metaCapiToken,
    metaTestEventCode,
  ] = await Promise.all([
    getSetting("meta_pixel_id", ""),
    getSetting("ga4_measurement_id", ""),
    getSetting("google_ads_id", ""),
    getSetting("google_ads_purchase_label", ""),
    getSetting("google_ads_signup_label", ""),
    getSetting("google_ads_vps_label", ""),
    getSetting("google_ads_hosting_label", ""),
    getSetting("google_ads_game_label", ""),
    getSetting("google_ads_email_label", ""),
    getSetting("google_ads_card_label", ""),
    getSetting("meta_capi_token", ""),
    getSetting("meta_test_event_code", ""),
  ]);
  // The CAPI token is stored encrypted (a `secret` field); decrypt for use.
  const decToken = metaCapiToken ? (decryptSecret(metaCapiToken) ?? metaCapiToken) : "";
  const purchaseLabel = googleAdsPurchaseLabel.trim();
  return {
    metaPixelId: metaPixelId.trim(),
    ga4Id: ga4Id.trim(),
    googleAdsId: googleAdsId.trim(),
    googleAdsPurchaseLabel: purchaseLabel,
    googleAdsLabels: {
      signup: signupLabel.trim(),
      vps: vpsLabel.trim(),
      hosting: hostingLabel.trim(),
      game: gameLabel.trim(),
      email: emailLabel.trim(),
      card: cardLabel.trim(),
      purchase: purchaseLabel,
    },
    metaCapiToken: decToken.trim(),
    metaTestEventCode: metaTestEventCode.trim(),
  };
}

export function toPublicConfig(c: TrackingConfig): PublicTrackingConfig {
  return {
    metaPixelId: c.metaPixelId,
    ga4Id: c.ga4Id,
    googleAdsId: c.googleAdsId,
    googleAdsPurchaseLabel: c.googleAdsPurchaseLabel,
    googleAdsLabels: c.googleAdsLabels,
  };
}

function sha256Lower(s: string): string {
  return createHash("sha256").update(s.trim().toLowerCase()).digest("hex");
}

export type CapiEvent = {
  eventName: "Purchase" | "Lead" | "CompleteRegistration" | "Subscribe";
  /** Stable id so the browser pixel + this server event dedupe to ONE conversion. */
  eventId?: string;
  email?: string;
  value?: number;
  currency?: string;
  /** The page the conversion happened on (for event_source_url). */
  sourceUrl?: string;
  clientIp?: string;
  userAgent?: string;
  /** Meta click-id cookie (_fbc) — sent RAW (not hashed) per Meta spec. */
  fbc?: string;
  /** Meta browser-id cookie (_fbp) — sent RAW (not hashed) per Meta spec. */
  fbp?: string;
  /** A stable id for the person (we use the user id, hashed) — big match boost. */
  externalId?: string;
};

/**
 * Fire a server-side Meta Conversions API event. Best-effort: never throws into
 * the caller (a tracking failure must never break an order). Returns the event_id
 * used so the caller can pass the SAME id to the browser pixel for dedup.
 */
export async function sendMetaConversion(ev: CapiEvent): Promise<{ ok: boolean; eventId: string }> {
  const eventId = ev.eventId ?? randomUUID();
  try {
    const cfg = await loadTrackingConfig();
    if (!cfg.metaPixelId || !cfg.metaCapiToken) return { ok: false, eventId };

    const userData: Record<string, unknown> = {};
    if (ev.email) userData.em = [sha256Lower(ev.email)];
    if (ev.clientIp) userData.client_ip_address = ev.clientIp;
    if (ev.userAgent) userData.client_user_agent = ev.userAgent;
    // fbc/fbp are sent RAW (Meta hashes nothing here); external_id IS hashed. All
    // three materially lift the event match rate when present.
    if (ev.fbc) userData.fbc = ev.fbc;
    if (ev.fbp) userData.fbp = ev.fbp;
    if (ev.externalId) userData.external_id = [sha256Lower(ev.externalId)];

    const body: Record<string, unknown> = {
      data: [
        {
          event_name: ev.eventName,
          event_time: Math.floor(Date.now() / 1000),
          action_source: "website",
          event_id: eventId,
          ...(ev.sourceUrl ? { event_source_url: ev.sourceUrl } : {}),
          user_data: userData,
          ...(ev.value != null
            ? { custom_data: { value: Number(ev.value.toFixed(2)), currency: ev.currency ?? "USD" } }
            : {}),
        },
      ],
      ...(cfg.metaTestEventCode ? { test_event_code: cfg.metaTestEventCode } : {}),
    };

    const url = `https://graph.facebook.com/v21.0/${encodeURIComponent(cfg.metaPixelId)}/events?access_token=${encodeURIComponent(cfg.metaCapiToken)}`;
    const res = await fetch(url, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(body),
      // Don't let a slow Meta endpoint hang a checkout.
      signal: AbortSignal.timeout(4000),
    });
    return { ok: res.ok, eventId };
  } catch {
    return { ok: false, eventId };
  }
}
import { UAParser } from "ua-parser-js";

/**
 * Parses a User-Agent string into the 3 fields shown in visitor analytics:
 * device type, OS, and browser. Plain, synchronous, local (no network) — safe
 * to call from a route handler on every request, or in bulk from a backfill
 * script.
 *
 * No `import "server-only"` here (unlike a typical Next-route-only lib):
 * this file is also imported by scripts/backfill-ua.ts, a plain `tsx`
 * process, and `server-only` has no valid entry point outside a bundler
 * (same class of bug that once broke lib/google-ads.ts under worker/index.ts).
 */
export type ParsedUa = {
  deviceType: string; // "Desktop" | "Mobile" | "Tablet" | "Smart TV" | "Console" | "Wearable" | "XR"
  os: string | null; // UAParser's own display name: "iOS", "Android", "Windows", "macOS", "Linux", …
  browser: string | null; // "Chrome", "Safari", "Mobile Safari", "Firefox", "Edge", …
};

const DEVICE_LABEL: Record<string, string> = {
  mobile: "Mobile",
  tablet: "Tablet",
  smarttv: "Smart TV",
  console: "Console",
  wearable: "Wearable",
  xr: "XR",
};

export function parseUserAgent(ua: string | null | undefined): ParsedUa {
  if (!ua) return { deviceType: "Desktop", os: null, browser: null };
  try {
    const r = UAParser(ua);
    // UAParser deliberately has no positive "desktop" signal (see its DeviceType
    // enum) — an undetected type (the common case: a regular laptop/desktop
    // browser) falls back to "Desktop" here, which is the correct default.
    const deviceType = (r.device.type && DEVICE_LABEL[r.device.type]) || "Desktop";
    return {
      deviceType,
      os: r.os.name?.trim() || null,
      browser: r.browser.name?.trim() || null,
    };
  } catch {
    // Malformed/unusual UA strings must never break the request they came with.
    return { deviceType: "Desktop", os: null, browser: null };
  }
}

