103	/** Top external referrer hosts over the trailing `days` window. */
104	export async function topReferrers(days = 7, limit = 8): Promise<Counted[]> {
105	  const since = new Date(Date.now() - days * DAY);
106	  const rows = await db.visit.findMany({
107	    where: { createdAt: { gte: since }, referrer: { not: null }, ...(await ipEx()) },
108	    select: { referrer: true },
109	    take: 5000,
110	    orderBy: { createdAt: "desc" },
111	  });
112	  const tally = new Map<string, number>();
113	  for (const r of rows) {
