220	/** Columns selected for a RecentVisit, shared by the live + feed queries. */
221	const RECENT_VISIT_SELECT = {
222	  id: true,
223	  ip: true,
224	  path: true,
225	  referrer: true,
226	  kind: true,
227	  country: true,
