235	/**
236	 * Attach the owning account to each visit row. Visit has only a `userId` scalar
237	 * (no relation), so we batch-resolve the distinct ids in one query rather than
238	 * N+1. Rows with no userId (anonymous) get `account: null`.
239	 */
240	async function withAccounts(
241	  rows: (Omit<RecentVisit, "account"> & { userId: string | null })[],
242	): Promise<RecentVisit[]> {
243	  const ids = [...new Set(rows.map((r) => r.userId).filter(Boolean))] as string[];
244	  const [users, renewalPrices] = await Promise.all([
245	    ids.length > 0
246	      ? db.user.findMany({
247	          where: { id: { in: ids } },
248	          select: {
249	            id: true,
250	            name: true,
251	            email: true,
252	            servers: {
253	              where: { status: { notIn: ["DELETING"] } },
254	              select: {
255	                isFree: true,
256	                status: true,
257	                termMonths: true,
258	                extraDiskGB: true,
259	                backupTier: true,
260	                annualDiscountPct: true,
261	                plan: { select: { name: true, priceCents: true } },
262	                gamePlan: { select: { name: true, priceCents: true, termMonths: true } },
263	                // Needed by renewalCharge (via serverMonthlyCents) to price that add-on.
264	                dedicatedIp: { select: { id: true } },
265	                wantsDedicatedIp: true,
266	                grandfatheredRenewalCents: true,
267	              },
268	            },
269	          },
270	        })
271	      : Promise.resolve([]),
272	    currentRenewalPrices(),
273	  ]);
