277	      return [u.id, { ...rest, mrrCents: fleetMrrCents(servers, renewalPrices) }];
278	    }),
279	  );
280	  return rows.map(({ userId, ...r }) => ({ ...r, account: userId ? byId.get(userId) ?? null : null }));
281	}
