283	// ---- Date-range traffic feed ----
284	// The dashboard above uses fixed trailing windows; this feed lets the admin pick
285	// an explicit date range and sort direction, so they can answer "what happened
286	// on/between these days" rather than only "the last N days". It reuses the same
287	// IP-exclusion (`ipEx`) as everything else, so hidden IPs stay hidden here too.
288	
289	export type FeedKind = "all" | "marketing" | "portal";
290	export type FeedDir = "desc" | "asc";
291	
292	export type FeedFilter = {
293	  /** Inclusive start day, `yyyy-mm-dd` (local). */
294	  from?: string;
295	  /** Inclusive end day, `yyyy-mm-dd` (local). */
296	  to?: string;
297	  kind?: FeedKind;
298	  /** Sort by date: newest-first (`desc`, default) or oldest-first (`asc`). */
299	  dir?: FeedDir;
300	  /** Row offset for pagination (from `paginate()`). */
301	  skip?: number;
302	  /** Page size (from `paginate()`). Capped at 500 so the page stays cheap. */
303	  take?: number;
304	};
305	
306	const YMD = /^\d{4}-\d{2}-\d{2}$/;
307	
308	/** Start-of-day Date for a `yyyy-mm-dd` string, or undefined if absent/invalid. */
309	function dayStart(s?: string): Date | undefined {
310	  if (!s || !YMD.test(s)) return undefined;
311	  // Explicit +07:00 (ICT) rather than a bare local-time string — this used to
312	  // parse in whatever timezone the SERVER process happens to run in, which
313	  // made a filter for "2026-09-11" mean a different real-world window
314	  // depending on deploy host. Fixed offset, no tz database needed (ICT has no DST).
315	  const d = new Date(`${s}T00:00:00+07:00`);
316	  return Number.isNaN(d.getTime()) ? undefined : d;
317	}
318	
319	/** End-of-day (inclusive) Date for a `yyyy-mm-dd` string in ICT, or undefined. */
320	function dayEnd(s?: string): Date | undefined {
321	  if (!s || !YMD.test(s)) return undefined;
322	  const d = new Date(`${s}T23:59:59.999+07:00`);
323	  return Number.isNaN(d.getTime()) ? undefined : d;
324	}
