326	/** Build the shared `where` for the feed (date range + kind + IP exclusion). */
327	async function feedWhere(f: FeedFilter) {
328	  const gte = dayStart(f.from);
329	  const lte = dayEnd(f.to);
330	  const where: {
331	    ip?: { notIn: string[] };
332	    kind?: string;
333	    createdAt?: { gte?: Date; lte?: Date };
334	  } = { ...(await ipEx()) };
335	  if (gte || lte) where.createdAt = { ...(gte ? { gte } : {}), ...(lte ? { lte } : {}) };
336	  if (f.kind && f.kind !== "all") where.kind = f.kind;
337	  return where;
338	}
