340	/**
341	 * Visits within an explicit date range, sorted by date, one page at a time
342	 * (`skip`/`take` from `paginate()`). `take` is capped at 500 so a mistaken
343	 * page size can't turn this into an unbounded scan.
344	 */
345	export async function visitFeed(f: FeedFilter): Promise<RecentVisit[]> {
346	  const take = Math.min(Math.max(f.take ?? 25, 1), 500);
347	  const dir = f.dir === "asc" ? "asc" : "desc";
348	  const rows = await db.visit.findMany({
349	    where: await feedWhere(f),
350	    // `id` is a tiebreaker, not just `createdAt`: several visits can share the
351	    // exact same millisecond timestamp (bursts of near-simultaneous pageviews
352	    // are common), and Postgres makes no ordering guarantee among rows that
353	    // tie on the sort key. Without a unique secondary key, `skip`/`take`
354	    // offset pagination can silently reshuffle those tied rows between two
355	    // queries — a row seen on page 1 reappearing on page 2, or a row between
356	    // them never appearing at all. `id` (a cuid, so already unique) closes
357	    // that gap and makes every page's window fully deterministic.
358	    orderBy: [{ createdAt: dir }, { id: dir }],
359	    skip: Math.max(f.skip ?? 0, 0),
360	    take,
361	    select: RECENT_VISIT_SELECT,
362	  });
363	  return withAccounts(rows);
364	}
