425	export type NewVsRecurring = {
426	  /** Distinct identified visitors (by visitorId) active in the window. */
427	  identified: number;
428	  /** Of those, first seen ON/AFTER the window start (brand-new). */
429	  newVisitors: number;
430	  /** Of those, seen on some earlier day too (recurring). */
431	  returningVisitors: number;
432	};
