434	/**
435	 * New vs recurring visitors over the trailing `days` window. Uses the stable
436	 * `visitorId` cookie, so it recognises the same person across sessions/IPs —
437	 * the thing IP-based "unique visitors" cannot do. Opted-out visitors (null
438	 * visitorId) are simply absent here; they still count in the IP-based uniques.
439	 */
440	export async function newVsRecurring(days = 7): Promise<NewVsRecurring> {
441	  const since = new Date(Date.now() - days * DAY);
442	  const inWindow = await db.visit.findMany({
443	    where: { createdAt: { gte: since }, visitorId: { not: null }, ...(await ipEx()) },
444	    distinct: ["visitorId"],
445	    select: { visitorId: true },
446	    take: ID_CAP,
447	  });
448	  const ids = inWindow.map((r) => r.visitorId as string);
449	  if (ids.length === 0) return { identified: 0, newVisitors: 0, returningVisitors: 0 };
450	
451	  // Which of those visitors we had already seen BEFORE this window = recurring.
452	  const earlier = await db.visit.findMany({
453	    where: { visitorId: { in: ids }, createdAt: { lt: since } },
454	    distinct: ["visitorId"],
455	    select: { visitorId: true },
456	    take: ID_CAP,
457	  });
458	  const returningVisitors = earlier.length;
459	  return {
460	    identified: ids.length,
461	    newVisitors: ids.length - returningVisitors,
462	    returningVisitors,
463	  };
464	}
