466	export type TimeStats = {
467	  sessions: number;
468	  /** Average session dwell (ms) — the "avg time on site" headline. */
469	  avgSessionMs: number;
470	  /** Average pageviews per session. */
471	  avgPageviews: number;
472	  /** Share of sessions that were a single pageview (0..1). */
473	  bounceRate: number;
474	};
475	
476	/**
477	 * Session-level engagement over the window: avg time on site, pages/session and
478	 * bounce rate. Dwell comes from the per-pageview close beacons; a session's time
479	 * is the sum of its pages' dwell. Sessions with no measured dwell still count for
480	 * pages/session and bounce, they just contribute 0 to the time average.
481	 */
482	export async function visitorTimeStats(days = 7): Promise<TimeStats> {
483	  const since = new Date(Date.now() - days * DAY);
484	  const rows = await db.visit.findMany({
485	    where: { createdAt: { gte: since }, sessionId: { not: null }, ...(await ipEx()) },
486	    select: { sessionId: true, durationMs: true },
487	    take: 50_000,
488	    orderBy: { createdAt: "desc" },
489	  });
490	  if (rows.length === 0)
491	    return { sessions: 0, avgSessionMs: 0, avgPageviews: 0, bounceRate: 0 };
492	
493	  const perSession = new Map<string, { ms: number; views: number }>();
494	  for (const r of rows) {
495	    const key = r.sessionId as string;
496	    const cur = perSession.get(key) ?? { ms: 0, views: 0 };
497	    cur.views += 1;
498	    cur.ms += r.durationMs ?? 0;
499	    perSession.set(key, cur);
500	  }
501	  const sessions = perSession.size;
502	  let totalMs = 0;
503	  let totalViews = 0;
504	  let bounces = 0;
505	  for (const s of perSession.values()) {
506	    totalMs += s.ms;
507	    totalViews += s.views;
508	    if (s.views <= 1) bounces += 1;
509	  }
510	  return {
511	    sessions,
512	    avgSessionMs: Math.round(totalMs / sessions),
513	    avgPageviews: totalViews / sessions,
514	    bounceRate: bounces / sessions,
515	  };
516	}
