518	export type PerKindTime = {
519	  /** Average dwell (ms) over pageviews that HAVE a measured duration. */
520	  avgMs: number;
521	  /** How many pageviews contributed (non-null durationMs) — the sample size. */
522	  samples: number;
523	};
