531	/**
532	 * Average time-on-page split by visit kind (marketing vs portal). This is the
533	 * per-PAGEVIEW average (Σ durationMs / count of pages with a duration), distinct
534	 * from `visitorTimeStats.avgSessionMs` which is per-SESSION. Null durations are
535	 * ignored — a page nobody dwelled on shouldn't drag the average to zero. Uses
536	 * Prisma aggregate so Postgres does the sum/count.
537	 */
538	export async function avgTimePerPageByKind(days = 30): Promise<TimePerPageByKind> {
539	  const since = new Date(Date.now() - days * DAY);
540	  const base = { createdAt: { gte: since }, durationMs: { not: null }, ...(await ipEx()) };
541	  const [mk, pt] = await Promise.all([
542	    db.visit.aggregate({ where: { ...base, kind: "marketing" }, _avg: { durationMs: true }, _count: { durationMs: true } }),
543	    db.visit.aggregate({ where: { ...base, kind: "portal" }, _avg: { durationMs: true }, _count: { durationMs: true } }),
544	  ]);
545	  const marketing: PerKindTime = { avgMs: Math.round(mk._avg.durationMs ?? 0), samples: mk._count.durationMs };
546	  const portal: PerKindTime = { avgMs: Math.round(pt._avg.durationMs ?? 0), samples: pt._count.durationMs };
547	  const totalSamples = marketing.samples + portal.samples;
548	  const overallMs =
549	    totalSamples > 0
550	      ? Math.round((marketing.avgMs * marketing.samples + portal.avgMs * portal.samples) / totalSamples)
551	      : 0;
552	  return { marketing, portal, overall: { avgMs: overallMs, samples: totalSamples } };
553	}
