681	export type VisitorDayPoint = {
682	  /** UTC midnight of the day. */
683	  date: Date;
684	  pageviews: number;
685	  uniqueVisitors: number;
686	  newVisitors: number;
687	  returningVisitors: number;
688	  sessions: number;
689	  avgSessionMs: number;
690	  /** Sessions that were a single pageview (a "bounce"). Always <= sessions. */
691	  bounces: number;
692	};
693	
694	/**
695	 * Compute a single UTC day's visitor metrics directly from the Visit log. Shared
696	 * by the worker rollup (which persists it to VisitorDaily) and the audience page
697	 * (which calls it for TODAY, to overlay live freshness on the stored rollup).
698	 */
699	export async function computeVisitorDay(dayStart: Date, dayEnd: Date): Promise<VisitorDayPoint> {
700	  const ex = await ipEx();
701	  const where = { createdAt: { gte: dayStart, lte: dayEnd }, ...ex };
702	
703	  const [pageviews, sessionRows, visitorRows] = await Promise.all([
704	    db.visit.count({ where }),
705	    db.visit.findMany({
706	      where: { ...where, sessionId: { not: null } },
707	      select: { sessionId: true, durationMs: true },
708	      take: 50_000,
709	    }),
710	    db.visit.findMany({
711	      where: { ...where, visitorId: { not: null } },
712	      distinct: ["visitorId"],
713	      select: { visitorId: true },
714	      take: ID_CAP,
715	    }),
716	  ]);
717	
718	  // Sessions + dwell + bounces. A "bounce" is a session with exactly one
719	  // pageview, so track a per-session pageview count alongside dwell (same
720	  // aggregation style as visitorTimeStats). Built from the same ipEx-filtered
721	  // sessionRows as `sessions`, so `bounces` is always <= `sessions`.
722	  const perSession = new Map<string, { ms: number; views: number }>();
723	  for (const r of sessionRows) {
724	    const k = r.sessionId as string;
725	    const cur = perSession.get(k) ?? { ms: 0, views: 0 };
726	    cur.ms += r.durationMs ?? 0;
727	    cur.views += 1;
728	    perSession.set(k, cur);
729	  }
730	  const sessions = perSession.size;
731	  let totalMs = 0;
732	  let bounces = 0;
733	  for (const s of perSession.values()) {
734	    totalMs += s.ms;
735	    if (s.views <= 1) bounces += 1;
736	  }
737	
738	  // Unique visitors: identified by cookie, plus IP-only for opted-out traffic.
739	  const ipOnly = await db.visit.findMany({
740	    where: { ...where, visitorId: null },
741	    distinct: ["ip"],
742	    select: { ip: true },
743	    take: ID_CAP,
744	  });
745	  const uniqueVisitors = visitorRows.length + ipOnly.length;
746	
747	  // New vs returning among the identified visitors seen today.
748	  const ids = visitorRows.map((r) => r.visitorId as string);
749	  let returningVisitors = 0;
750	  if (ids.length > 0) {
751	    const earlier = await db.visit.findMany({
752	      where: { visitorId: { in: ids }, createdAt: { lt: dayStart } },
753	      distinct: ["visitorId"],
754	      select: { visitorId: true },
755	      take: ID_CAP,
756	    });
757	    returningVisitors = earlier.length;
758	  }
759	
760	  return {
761	    date: dayStart,
762	    pageviews,
763	    uniqueVisitors,
764	    newVisitors: ids.length - returningVisitors,
765	    returningVisitors,
766	    sessions,
767	    avgSessionMs: sessions > 0 ? Math.round(totalMs / sessions) : 0,
768	    bounces,
769	  };
770	}
