772	/**
773	 * The last `days` days of the VisitorDaily rollup, oldest-first, with any missing
774	 * days filled in as zero rows so the trend chart has a continuous x-axis. Powers
775	 * the audience dashboard's trend without scanning the raw Visit log.
776	 */
777	export async function readVisitorDailySeries(days = 30): Promise<VisitorDayPoint[]> {
778	  const today = new Date();
779	  const start = new Date(Date.UTC(today.getUTCFullYear(), today.getUTCMonth(), today.getUTCDate()));
780	  start.setUTCDate(start.getUTCDate() - (days - 1));
781	
782	  const rows = await db.visitorDaily.findMany({
783	    where: { date: { gte: start } },
784	    orderBy: { date: "asc" },
785	  });
786	  const byKey = new Map<string, (typeof rows)[number]>();
787	  for (const r of rows) byKey.set(r.date.toISOString().slice(0, 10), r);
788	
789	  const out: VisitorDayPoint[] = [];
790	  for (let i = 0; i < days; i++) {
791	    const d = new Date(start);
792	    d.setUTCDate(start.getUTCDate() + i);
793	    const hit = byKey.get(d.toISOString().slice(0, 10));
794	    out.push(
795	      hit
796	        ? {
797	            date: d,
798	            pageviews: hit.pageviews,
799	            uniqueVisitors: hit.uniqueVisitors,
800	            newVisitors: hit.newVisitors,
801	            returningVisitors: hit.returningVisitors,
802	            sessions: hit.sessions,
803	            avgSessionMs: hit.sessions > 0 ? Math.round(Number(hit.totalSessionMs) / hit.sessions) : 0,
804	            bounces: hit.bounces,
805	          }
806	        : {
807	            date: d,
808	            pageviews: 0,
809	            uniqueVisitors: 0,
810	            newVisitors: 0,
811	            returningVisitors: 0,
812	            sessions: 0,
813	            avgSessionMs: 0,
814	            bounces: 0,
815	          }
816	    );
817	  }
818	  return out;
819	}
