/**
 * Regenerates lib/bots/datacenter-ranges.json — the static, committed list of
 * cloud / hosting / datacenter IP ranges the bot classifier treats as a WEAK
 * "not a residential connection" signal (lib/bots/datacenter.ts).
 *
 * Sources (all public, no key needed):
 *   - AWS's official feed            https://ip-ranges.amazonaws.com/ip-ranges.json
 *   - Google Cloud's official feed   https://www.gstatic.com/ipranges/cloud.json
 *   - Oracle Cloud's official feed   https://docs.oracle.com/en-us/iaas/tools/public_ip_ranges.json
 *   - RIPEstat "announced-prefixes" per ASN for providers without a feed
 *     (Azure, DigitalOcean, Hetzner, OVH, Linode/Akamai, Vultr, Alibaba,
 *     Tencent, Contabo, Scaleway, Leaseweb, Hostinger, …)
 *
 * Deliberately NOT included: Cloudflare (AS13335 — WARP is real people on
 * phones), Apple iCloud Private Relay, mobile carriers. Datacenter IP is only a
 * weak signal in the classifier — VPN users are humans — so the list errs on
 * the side of big, unambiguous hosting ASNs.
 *
 * Run (needs outbound HTTPS; safe anywhere, writes ONE file):
 *   npx tsx scripts/refresh-datacenter-ranges.ts
 * then commit lib/bots/datacenter-ranges.json. Re-run quarterly.
 */
import { writeFileSync } from "node:fs";
import path from "node:path";
import { parseCidr, mergeRanges } from "../lib/bots/cidr";

const ASNS: { provider: string; asns: number[] }[] = [
  { provider: "azure", asns: [8075, 8068] },
  { provider: "digitalocean", asns: [14061] },
  { provider: "hetzner", asns: [24940, 213230] },
  { provider: "ovh", asns: [16276] },
  { provider: "linode", asns: [63949] },
  { provider: "vultr", asns: [20473] },
  { provider: "alibaba", asns: [45102, 37963] },
  { provider: "tencent", asns: [132203, 45090] },
  { provider: "contabo", asns: [51167] },
  { provider: "scaleway", asns: [12876] },
  { provider: "leaseweb", asns: [60781, 16265, 28753] },
  { provider: "hostinger", asns: [47583] },
  { provider: "m247", asns: [9009] },
  { provider: "datacamp", asns: [60068] },
  { provider: "choopa-psychz", asns: [40676] },
