let v6Index: Index | null = null;
const crawlerIndex = new Map<string, { v4: Index; v6: Index }>();

function build(entries: [bigint, bigint, number][]): Index {
  entries.sort((a, b) => (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0));
  // Cross-provider overlap is possible (e.g. aws + aws-other); keep the max end
  // seen so far in `ends` so a binary search on starts stays correct.
  const starts: bigint[] = [];
  const ends: bigint[] = [];
  const prov: number[] = [];
  for (const [s, e, p] of entries) {
    starts.push(s);
    ends.push(e);
    prov.push(p);
  }
  return { starts, ends, prov };
}

function lookup(idx: Index, n: bigint): number {
  // Rightmost start <= n, then walk back a few in case an earlier, wider range covers n.
  let lo = 0;
  let hi = idx.starts.length - 1;
  let found = -1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (idx.starts[mid] <= n) {
      found = mid;
      lo = mid + 1;
    } else hi = mid - 1;
  }
  for (let i = found, steps = 0; i >= 0 && steps < 64; i--, steps++) {
    if (idx.ends[i] >= n) return idx.prov[i];
  }
  return -1;
}

function ensure() {
  if (v4Index && v6Index) return;
  const v4: [bigint, bigint, number][] = [];
  const raw4 = (data as { v4: number[] }).v4;
  for (let i = 0; i < raw4.length; i += 3) v4.push([BigInt(raw4[i]), BigInt(raw4[i + 1]), raw4[i + 2]]);
  const v6: [bigint, bigint, number][] = [];
  const raw6 = (data as { v6: string[] }).v6;
  for (let i = 0; i < raw6.length; i += 3) v6.push([BigInt("0x" + raw6[i]), BigInt("0x" + raw6[i + 1]), Number(raw6[i + 2])]);
