export function inCrawlerIpList(listId: string, ip: string): boolean {
  const lists = (data as { crawlers?: Record<string, string[]> }).crawlers ?? {};
  const cidrs = lists[listId];
  if (!cidrs || cidrs.length === 0) return false;
  let idx = crawlerIndex.get(listId);
  if (!idx) {
    const v4: [bigint, bigint, number][] = [];
    const v6: [bigint, bigint, number][] = [];
    for (const c of cidrs) {
      const r = parseCidr(c);
      if (r) (r.v6 ? v6 : v4).push([r.start, r.end, 0]);
    }
    idx = { v4: build(v4), v6: build(v6) };
    crawlerIndex.set(listId, idx);
  }
