export const BOT_KINDS: BotKind[] = ["verified-crawler", "declared-crawler", "scraper", "suspected-bot", "human"];

export type BotVerdict = {
  isBot: boolean;
  botKind: BotKind;
  /** Comma-separated machine-readable reasons, <= 200 chars. */
  botReason: string | null;
  /** Catalogue id when a declared crawler matched (for crawler stats). */
  crawlerId?: string;
};

export type ClassifyInput = {
  ua: string | null | undefined;
  ip?: string | null;
  /** Signed-in account on this hit — a logged-in person is not "suspected" on weak signals alone. */
  userId?: string | null;
  /** navigator.webdriver from the client beacon. */
  webdriver?: boolean | null;
  /** An active BotIpFlag for this IP, if any. */
  ipFlag?: { kind: string; reason: string } | null;
  /**
   * Cached FCrDNS verdict for (ip, claimed crawler): true = verified, false =
   * spoof, undefined = not checked yet. Ignored when the official IP list
   * already confirms the IP.
   */
  rdnsVerified?: boolean;
  now?: Date;
};

/** Weak-signal threshold: a browser UA needs this many points to be "suspected". */
export const SUSPECT_THRESHOLD = 3;

// Release anchors for the "how current is this browser" estimate. Both Chrome
// and Firefox ship a new major roughly every 4 weeks; one major per ~30.4 days
// from these anchors matches what real traffic shows (Chrome 153/154 and
// Firefox 156 in Oct 2026).
const CHROME_ANCHOR = { major: 120, at: Date.UTC(2023, 11, 1) };
const FIREFOX_ANCHOR = { major: 121, at: Date.UTC(2023, 11, 19) };
const MONTH_MS = 30.44 * 86_400_000;
/** How many majors behind "current" before a build counts as stale (~2 years). */
export const STALE_MAJORS = 24;

export function estimatedCurrentMajor(engine: "chrome" | "firefox", now: Date = new Date()): number {
  const a = engine === "chrome" ? CHROME_ANCHOR : FIREFOX_ANCHOR;
  return a.major + Math.floor((now.getTime() - a.at) / MONTH_MS);
}

/**
 * Detect a browser build that is implausibly old for a real person. Evergreen
 * browsers auto-update; a scraper fleet rotating a fixed list of 2023 UAs
 * (Chrome 118-121 / Firefox 120-121 from hundreds of residential IPs, seen
 * live 2026-09-25) is the classic tell. Returns e.g. "chrome/119" or null.
 */
export function staleBrowser(ua: string, now: Date = new Date()): string | null {
  // Firefox ESR lines are legitimately older; only flag Firefox beyond the window too.
  const ff = /Firefox\/(\d{2,3})\./.exec(ua);
  if (ff && !/Seamonkey|Waterfox|Pale ?Moon|Basilisk/i.test(ua)) {
    const major = Number(ff[1]);
    if (major > 0 && estimatedCurrentMajor("firefox", now) - major >= STALE_MAJORS) return `firefox/${major}`;
    return null;
  }
  // Chromium family (Chrome, Edge, Opera, Brave, Samsung all carry Chrome/NNN).
  const ch = /(?:Chrome|CriOS)\/(\d{2,3})\./.exec(ua);
  if (ch) {
    const major = Number(ch[1]);
    // Embedded webviews (Android "wv", in-app browsers) can lag; don't flag them.
    if (/; wv\)|FBAN|FBAV|Instagram|Line\/|MicroMessenger/i.test(ua)) return null;
    if (major > 0 && estimatedCurrentMajor("chrome", now) - major >= STALE_MAJORS) return `chrome/${major}`;
  }
  return null;
}

/** Does the UA look like any real browser at all? (cheap structural check) */
function looksLikeBrowser(ua: string): boolean {
  return /^Mozilla\/5\.0 \(/.test(ua) && /(AppleWebKit|Gecko\/|Trident)/.test(ua);
}

function verdict(kind: BotKind, reasons: string[], crawlerId?: string): BotVerdict {
  const r = reasons.join(",").slice(0, 200) || null;
  return { isBot: kind !== "human", botKind: kind, botReason: r, ...(crawlerId ? { crawlerId } : {}) };
}

/** Resolve a declared crawler to verified / declared / spoofed-scraper. */
export function crawlerVerdict(def: CrawlerDef, ip: string | null | undefined, rdnsVerified?: boolean): BotVerdict {
  const canVerify = !!(def.ipList || def.rdns?.length);
  if (!canVerify) return verdict("declared-crawler", [`ua:${def.id}`], def.id);
  if (ip && def.ipList && inCrawlerIpList(def.ipList, ip)) {
    return verdict("verified-crawler", [`ua:${def.id}`, "ip-list"], def.id);
  }
  if (rdnsVerified === true) return verdict("verified-crawler", [`ua:${def.id}`, "fcrdns"], def.id);
  if (rdnsVerified === false) return verdict("scraper", [`spoofed:${def.id}`], def.id);
  return verdict("declared-crawler", [`ua:${def.id}`, "unverified"], def.id);
}

export function classifyHit(input: ClassifyInput): BotVerdict {
  const ua = (input.ua ?? "").trim();
  const now = input.now ?? new Date();
  if (!ua) return verdict("scraper", ["no-ua"]);

  // 1. Declared crawlers (named).
  const def = matchCrawler(ua);
  if (def) return crawlerVerdict(def, input.ip, input.rdnsVerified);

  // 2. Automation / HTTP libraries.
  const auto = matchAutomation(ua);
  if (auto) return verdict("scraper", [`ua:${auto}`]);

  // 3. Long-tail self-declared bots.
  if (GENERIC_BOT_RE.test(ua)) return verdict("declared-crawler", ["ua:other-bot"], "other-bot");

  // 4. Behaviour evidence already attached to this IP (honeypot / velocity).
  if (input.ipFlag) {
    const k: BotKind = input.ipFlag.kind === "scraper" ? "scraper" : "suspected-bot";
    return verdict(k, [`ip-flag:${input.ipFlag.reason}`]);
  }

  // 5. Automation-controlled browser.
  if (input.webdriver === true) return verdict("suspected-bot", ["webdriver"]);

  // 6. Weak signals — scored. A signed-in account is never flagged on these alone.
  const reasons: string[] = [];
  let score = 0;
  const stale = staleBrowser(ua, now);
  if (stale) {
    score += 3;
    reasons.push(`stale-browser:${stale}`);
  }
  if (!looksLikeBrowser(ua)) {
    score += 2;
    reasons.push("non-browser-ua");
  }
  const dc = datacenterProvider(input.ip);
  if (dc) {
    score += 2;
    reasons.push(`dc-ip:${dc}`);
  }
  if (score >= SUSPECT_THRESHOLD && !input.userId) return verdict("suspected-bot", reasons);
  return verdict("human", reasons.length ? [`weak:${reasons.join("+")}`] : []);
}

/** Rank so the async re-classifier never DOWNGRADES a stronger verdict. */
export function kindRank(kind: string | null | undefined): number {
  switch (kind) {
    case "scraper":
      return 4;
    case "verified-crawler":
      return 3;
    case "declared-crawler":
      return 3;
    case "suspected-bot":
      return 2;
    case "human":
      return 1;
    default:
      return 0;
  }
}

export const BOT_KIND_LABEL: Record<BotKind, string> = {
  "verified-crawler": "Verified crawler",
  "declared-crawler": "Declared crawler",
  scraper: "Scraper / automation",
  "suspected-bot": "Suspected bot",
  human: "Human",
};

