/**
 * Forward-confirmed reverse DNS (FCrDNS) crawler verification, cached in
 * `CrawlerIpVerdict`.
 *
 * The check Google, Bing, Apple, Yandex, Baidu, Amazon and the SEO tools all
 * document: PTR(ip) must end in one of the crawler's own domains AND that
 * hostname must resolve back to the same ip. A UA claiming "Googlebot" from an
 * IP that fails this is a scraper wearing a costume.
 *
 * Only called from the worker / scripts (never in the /api/track request path —
 * a DNS round-trip has no business delaying a page view). Verdicts are cached
 * for CACHE_DAYS; a lookup error (timeout, SERVFAIL) is NOT cached as a spoof —
 * it returns undefined so the hit stays "declared-crawler, unverified".
 */
import { promises as dns } from "node:dns";
import { db } from "../db";
import { crawlerById } from "./catalogue";
import { inCrawlerIpList } from "./datacenter";

export const CACHE_DAYS = 14;
const LOOKUP_TIMEOUT_MS = 3000;

function withTimeout<T>(p: Promise<T>, ms: number): Promise<T> {
  return new Promise((resolve, reject) => {
    const t = setTimeout(() => reject(new Error("dns-timeout")), ms);
    p.then(
      (v) => {
        clearTimeout(t);
        resolve(v);
      },
      (e) => {
        clearTimeout(t);
        reject(e);
      },
    );
  });
}

export function hostMatches(hostname: string, suffixes: string[]): boolean {
  const h = hostname.toLowerCase().replace(/\.$/, "");
  return suffixes.some((s) => h === s || h.endsWith(`.${s}`));
}

/**
 * Raw FCrDNS: true = confirmed, false = PTR missing/foreign or forward mismatch,
 * undefined = could not tell (DNS error/timeout). Exported for tests with an
 * injectable resolver.
 */
export async function fcrdns(
  ip: string,
  suffixes: string[],
  resolver: { reverse(ip: string): Promise<string[]>; lookupAll(host: string): Promise<string[]> } = {
    reverse: (i) => dns.reverse(i),
    lookupAll: async (h) => (await dns.lookup(h, { all: true })).map((a) => a.address),
  },
): Promise<{ ok: boolean | undefined; hostname: string | null }> {
  let ptrs: string[];
  try {
    ptrs = await withTimeout(resolver.reverse(ip), LOOKUP_TIMEOUT_MS);
  } catch (e) {
    const code = (e as { code?: string }).code;
    // NXDOMAIN / no PTR record is a definitive "not theirs"; anything else is unknown.
    if (code === "ENOTFOUND" || code === "ENODATA") return { ok: false, hostname: null };
    return { ok: undefined, hostname: null };
  }
  const candidate = ptrs.find((h) => hostMatches(h, suffixes));
  if (!candidate) return { ok: false, hostname: ptrs[0] ?? null };
  try {
    const addrs = await withTimeout(resolver.lookupAll(candidate), LOOKUP_TIMEOUT_MS);
    const norm = (a: string) => a.toLowerCase().replace(/^::ffff:/, "");
    return { ok: addrs.map(norm).includes(norm(ip)), hostname: candidate };
  } catch {
    return { ok: undefined, hostname: candidate };
  }
}

/**
 * Verified? for (ip, crawler id). Uses the official IP list first (free), then
 * the cache, then a live FCrDNS lookup when `allowLookup` (callers budget
 * these). Returns undefined when it cannot be determined right now.
 */
export async function verifyCrawlerIp(
  crawlerId: string,
  ip: string,
  opts: { allowLookup?: boolean } = {},
): Promise<boolean | undefined> {
  const def = crawlerById(crawlerId);
  if (!def) return undefined;
  if (def.ipList && inCrawlerIpList(def.ipList, ip)) return true;
  if (!def.rdns?.length) return undefined;

  const cached = await db.crawlerIpVerdict.findUnique({ where: { ip } }).catch(() => null);
  if (cached && cached.claimed === crawlerId && Date.now() - cached.checkedAt.getTime() < CACHE_DAYS * 86_400_000) {
    return cached.verified;
  }
  if (!opts.allowLookup) return undefined;

  const res = await fcrdns(ip, def.rdns);
  if (res.ok === undefined) return undefined;
  await db.crawlerIpVerdict
    .upsert({
      where: { ip },
      create: { ip, claimed: crawlerId, verified: res.ok, hostname: res.hostname },
      update: { claimed: crawlerId, verified: res.ok, hostname: res.hostname, checkedAt: new Date() },
    })
    .catch(() => {});
  return res.ok;
}

