/**
 * Behaviour-based IP flags (honeypot hit, velocity). Consulted by /api/track at
 * ingest; written by the honeypot route and the worker re-classifier.
 *
 * Flags EXPIRE: the scraper fleets seen on this site run through residential
 * proxy pools, so an IP that was a bot today can be a real customer next week.
 */
import { db } from "../db";

export const FLAG_TTL_DAYS: Record<string, number> = {
  honeypot: 7,
  velocity: 2,
  manual: 30,
};

/** Active flag for `ip`, or null. Never throws (ingest must not break). */
export async function activeIpFlag(ip: string | null | undefined): Promise<{ kind: string; reason: string } | null> {
  if (!ip || ip === "unknown") return null;
  try {
    const f = await db.botIpFlag.findUnique({ where: { ip }, select: { kind: true, reason: true, expiresAt: true } });
    if (!f || f.expiresAt.getTime() < Date.now()) return null;
    return { kind: f.kind, reason: f.reason };
  } catch {
    return null;
  }
}

/** Create or extend a flag. Idempotent: re-flagging bumps hits + expiry. */
export async function flagIp(ip: string, kind: "scraper" | "suspected-bot", reason: keyof typeof FLAG_TTL_DAYS | string): Promise<void> {
  if (!ip || ip === "unknown") return;
  const ttl = FLAG_TTL_DAYS[reason] ?? 2;
  const expiresAt = new Date(Date.now() + ttl * 86_400_000);
  await db.botIpFlag.upsert({
    where: { ip },
    create: { ip, kind, reason, expiresAt },
    update: { kind, reason, expiresAt, hits: { increment: 1 } },
  });
}

/** Drop long-expired flags (housekeeping, called from the worker sweep). */
export async function pruneIpFlags(): Promise<number> {
  const r = await db.botIpFlag.deleteMany({ where: { expiresAt: { lt: new Date(Date.now() - 7 * 86_400_000) } } });
  return r.count;
}

