      id: u.id,
      email: u.email,
      name: u.name,
      signup: u.createdAt,
      lastActivity: last,
      daysSinceSignup: Math.floor((now - u.createdAt.getTime()) / DAY_MS),
      returned1d: !!last && last > cutoff1d,
      returned7d: !!last && last > cutoff7d,
      returned30d: !!last && last > cutoff30d,
