import { NextResponse } from "next/server";
import { db } from "@/lib/db";
import { trustedClientIp } from "@/app/api/_lib/client-ip";
import { checkRateLimit } from "@/lib/rate-limit";
import { classifyHit } from "@/lib/bots/classify";
import { flagIp } from "@/lib/bots/ip-flags";

export const runtime = "nodejs";

/**
 * Honeypot target. components/VisitTracker.tsx renders an invisible, nofollow
 * link to this path on every page; /api is Disallowed in app/robots.ts. A real
 * person can't see or tab to it and a polite crawler won't fetch it, so a hit
 * here is a link-harvesting scraper. The IP is flagged (lib/bots/ip-flags.ts,
 * expires after 7 days — residential proxies get recycled) and its visits from
 * the last 24h are re-marked as `scraper`.
 *
 * Self-declared crawlers are NOT flagged (they are already excluded as bots,
 * and verified ones fetching it would only mean a robots.txt cache lag).
 * Always answers the same tiny noindex page, whatever happens.
 */
const PAGE = '<!doctype html><meta name="robots" content="noindex,nofollow"><title>.</title>';

function respond() {
