// Asynchronous bot RE-classification over recent Visit rows. Ingest
// (/api/track) can only judge one hit at a time; the evidence below only
// exists in aggregate, after the fact:
//
//   velocity      one IP firing > VELOCITY_MAX anonymous pageviews in 10 min
//   session-sweep one session with >= SWEEP_MIN_PAGES pages and ~no dwell
//   ua-cluster    one exact UA string from >= CLUSTER_MIN_IPS IPs in 24h where
//                 ~every hit is a referrer-less single-page landing (the
//                 residential-proxy scraper fleet signature — Lightpanda and
//                 the stale-Chrome fleet both look exactly like this; real
//                 human UAs sit around 14% on both ratios)
//   fcrdns        declared crawlers verified (or exposed as spoofs) by
//                 forward-confirmed reverse DNS, budgeted per sweep
//
// Only ever UPGRADES a verdict (human → suspected/scraper, declared →
// verified/spoof). Signed-in rows (userId set) are never touched by the
// heuristics. Never touches rows with botKind NULL older than the window —
// that is the one-off backfill's job (scripts/backfill-bot-classification.ts).
import { Prisma } from "@prisma/client";
import { db } from "../lib/db";
import { flagIp, pruneIpFlags } from "../lib/bots/ip-flags";
import { verifyCrawlerIp } from "../lib/bots/verify";

export const VELOCITY_WINDOW_MIN = 10;
export const VELOCITY_MAX = 100;
export const SWEEP_MIN_PAGES = 25;
export const SWEEP_MAX_AVG_MS = 2000;
export const CLUSTER_MIN_IPS = 25;
export const CLUSTER_MIN_RATIO = 0.9;
const VERIFY_BUDGET = 20;

type Result = { velocity: number; sweeps: number; clusters: number; verified: number; spoofed: number };

export async function botReclassifySweep(): Promise<Result> {
  const out: Result = { velocity: 0, sweeps: 0, clusters: 0, verified: 0, spoofed: 0 };
  const now = Date.now();

  // ---- velocity (per IP, anonymous rows) ----
  const since10 = new Date(now - VELOCITY_WINDOW_MIN * 60_000);
  const fast = await db.$queryRaw<{ ip: string; n: bigint }[]>`
    SELECT ip, count(*)::bigint AS n FROM "Visit"
    WHERE "createdAt" >= ${since10} AND "userId" IS NULL AND "isBot" = false
    GROUP BY ip HAVING count(*) > ${VELOCITY_MAX}`;
  for (const r of fast) {
    await flagIp(r.ip, "scraper", "velocity");
    const u = await db.visit.updateMany({
      where: { ip: r.ip, userId: null, createdAt: { gte: new Date(now - 86_400_000) }, isBot: false },
      data: { isBot: true, botKind: "scraper", botReason: "velocity", botCheckedAt: new Date() },
    });
    out.velocity += u.count;
  }

  // ---- session sweeps (last 2h) ----
  const since2h = new Date(now - 2 * 3_600_000);
  const sweeps = await db.$queryRaw<{ sid: string }[]>`
    SELECT "sessionId" AS sid FROM "Visit"
    WHERE "createdAt" >= ${since2h} AND "sessionId" IS NOT NULL AND "userId" IS NULL AND "isBot" = false
    GROUP BY "sessionId"
    HAVING count(*) >= ${SWEEP_MIN_PAGES}
       AND avg(coalesce("durationMs", 0)) < ${SWEEP_MAX_AVG_MS}
       AND bool_or(coalesce(interacted, false)) = false`;
  if (sweeps.length) {
    const u = await db.visit.updateMany({
      where: { sessionId: { in: sweeps.map((s) => s.sid) }, userId: null, isBot: false },
      data: { isBot: true, botKind: "scraper", botReason: "session-sweep", botCheckedAt: new Date() },
    });
    out.sweeps += u.count;
  }

  // ---- UA clusters (last 24h) ----
  const since24 = new Date(now - 86_400_000);
  const clusters = await db.$queryRaw<{ ua: string; ips: bigint }[]>`
    WITH s AS (
      SELECT "sessionId", count(*) AS n FROM "Visit"
      WHERE "createdAt" >= ${since24} AND "sessionId" IS NOT NULL GROUP BY "sessionId"
    )
    SELECT v.ua, count(DISTINCT v.ip)::bigint AS ips FROM "Visit" v
    LEFT JOIN s ON s."sessionId" = v."sessionId"
    WHERE v."createdAt" >= ${since24} AND v."userId" IS NULL AND v."isBot" = false AND v.ua IS NOT NULL
    GROUP BY v.ua
    HAVING count(DISTINCT v.ip) >= ${CLUSTER_MIN_IPS}
       AND avg(CASE WHEN v.referrer IS NULL AND v."isEntry" THEN 1.0 ELSE 0.0 END) >= ${CLUSTER_MIN_RATIO}
       AND avg(CASE WHEN coalesce(s.n, 1) = 1 THEN 1.0 ELSE 0.0 END) >= ${CLUSTER_MIN_RATIO}
       AND avg(CASE WHEN v.interacted IS TRUE THEN 1.0 ELSE 0.0 END) < 0.05`;
  for (const c of clusters) {
    const u = await db.visit.updateMany({
      where: { ua: c.ua, userId: null, isBot: false, createdAt: { gte: since24 } },
      data: { isBot: true, botKind: "suspected-bot", botReason: `ua-cluster:${Number(c.ips)}ips`, botCheckedAt: new Date() },
    });
    out.clusters += u.count;
  }

  // ---- FCrDNS verification of declared crawlers (last 7d, budgeted) ----
  const unverified = await db.$queryRaw<{ ip: string; reason: string }[]>`
    SELECT DISTINCT ON (ip) ip, "botReason" AS reason FROM "Visit"
    WHERE "createdAt" >= ${new Date(now - 7 * 86_400_000)}
      AND "botKind" = 'declared-crawler' AND "botReason" LIKE '%unverified%'
    ORDER BY ip, "createdAt" DESC
    LIMIT ${VERIFY_BUDGET}`;
  await Promise.all(
    unverified.map(async (r) => {
      const id = /ua:([a-z0-9-]+)/.exec(r.reason)?.[1];
      if (!id) return;
      const ok = await verifyCrawlerIp(id, r.ip, { allowLookup: true });
      if (ok === undefined) return;
      const u = await db.visit.updateMany({
        where: { ip: r.ip, botKind: "declared-crawler", botReason: { contains: "unverified" } },
        data: ok
          ? { botKind: "verified-crawler", botReason: `ua:${id},fcrdns`, botCheckedAt: new Date() }
          : { botKind: "scraper", botReason: `spoofed:${id}`, botCheckedAt: new Date() },
      });
      if (ok) out.verified += u.count;
      else out.spoofed += u.count;
    }),
  );

  // Stamp the recent human rows as looked-at (cheap; lets the admin see coverage).
  await db.$executeRaw(Prisma.sql`
    UPDATE "Visit" SET "botCheckedAt" = now()
    WHERE "createdAt" >= ${since2h} AND "botCheckedAt" IS NULL AND "botKind" IS NOT NULL`);

  await pruneIpFlags().catch(() => 0);
  return out;
}

