/**
 * Pure helpers for turning nginx "combined" access-log lines into crawler
 * activity rows. Shared by the incremental worker sweep (worker/crawler-log.ts)
 * and the one-off historical backfill (scripts/backfill-crawler-log.ts).
 */
import { matchCrawler, matchAutomation, GENERIC_BOT_RE, type CrawlerDef } from "./catalogue";

export type LogLine = {
  ip: string;
  ts: Date;
  method: string;
  path: string;
  status: number;
  bytes: number;
  referer: string;
  ua: string;
};

// $remote_addr - $remote_user [$time_local] "$request" $status $body_bytes_sent "$http_referer" "$http_user_agent"
const COMBINED = /^(\S+) \S+ \S+ \[([^\]]+)\] "([A-Z]+) (\S+)[^"]*" (\d{3}) (\d+|-) "((?:[^"\\]|\\.)*)" "((?:[^"\\]|\\.)*)"/;
const MONTHS: Record<string, number> = { Jan: 0, Feb: 1, Mar: 2, Apr: 3, May: 4, Jun: 5, Jul: 6, Aug: 7, Sep: 8, Oct: 9, Nov: 10, Dec: 11 };

/** `01/Oct/2026:05:38:58 +0000` → Date. */
export function parseNginxTime(s: string): Date | null {
  const m = /^(\d{2})\/(\w{3})\/(\d{4}):(\d{2}):(\d{2}):(\d{2}) ([+-])(\d{2})(\d{2})$/.exec(s);
  if (!m) return null;
  const mon = MONTHS[m[2]];
  if (mon === undefined) return null;
  const utc = Date.UTC(+m[3], mon, +m[1], +m[4], +m[5], +m[6]);
  const off = (+m[8] * 60 + +m[9]) * 60_000 * (m[7] === "+" ? 1 : -1);
  return new Date(utc - off);
}

export function parseLogLine(line: string): LogLine | null {
  const m = COMBINED.exec(line);
  if (!m) return null;
  const ts = parseNginxTime(m[2]);
  if (!ts) return null;
  return {
    ip: m[1],
    ts,
    method: m[3],
    path: m[4].slice(0, 400),
    status: Number(m[5]),
    bytes: m[6] === "-" ? 0 : Number(m[6]),
    referer: m[7],
    ua: m[8].slice(0, 400),
  };
}

/** Path without query string / fragment. */
export function cleanPath(p: string): string {
  const q = p.search(/[?#]/);
  return (q >= 0 ? p.slice(0, q) : p) || "/";
}

const ASSET_EXT = /\.(js|mjs|css|map|png|jpe?g|gif|svg|webp|avif|ico|woff2?|ttf|otf|eot|mp4|webm|mp3|wav|json|txt|pdf|zip|gz|wasm)$/i;

/** Bucket a path for the CrawlerDaily `section` column. */
export function sectionOf(path: string): string {
  const p = cleanPath(path).toLowerCase();
  if (p === "/robots.txt") return "robots";
  if (/^\/sitemap[^/]*\.xml$/.test(p) || /\/sitemap[^/]*\.xml$/.test(p)) return "sitemap";
  if (p.startsWith("/_next/") || ASSET_EXT.test(p)) return "asset";
  if (p.startsWith("/api/")) return "api";
  if (p === "/") return "home";
  const seg = p.split("/")[1] ?? "";
  if (!/^[a-z0-9-]{1,40}$/.test(seg)) return "other";
  return seg;
}

/** Page (not asset/api/robots) paths get per-URL tracking in CrawlerUrl. */
export function isPagePath(section: string): boolean {
  return section !== "asset" && section !== "api" && section !== "robots";
}

export function statusClass(status: number): string {
  if (status >= 500) return "5xx";
  if (status >= 400) return "4xx";
  if (status >= 300) return "3xx";
  return "2xx";
}

export type LogBot =
  | { type: "crawler"; def: CrawlerDef }
  | { type: "automation"; id: string }
  | { type: "generic" };

/** Which bot (if any) a log line's UA declares. Humans → null. */
export function logBotOf(ua: string): LogBot | null {
  if (!ua || ua === "-") return { type: "automation", id: "no-ua" };
  const def = matchCrawler(ua);
  if (def) return { type: "crawler", def };
  const auto = matchAutomation(ua);
  if (auto) return { type: "automation", id: auto };
  if (GENERIC_BOT_RE.test(ua)) return { type: "generic" };
  return null;
}

export function utcDay(d: Date): Date {
  return new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()));
}

