/**
 * Aggregate parsed access-log lines into CrawlerDaily + CrawlerUrl, verifying
 * declared crawlers on the way (official IP list → cached FCrDNS → a small
 * budget of live lookups). Shared by worker/crawler-log.ts and
 * scripts/backfill-crawler-log.ts. Writes are batched multi-row upserts that
 * INCREMENT counters, so callers must never feed the same bytes twice (the
 * cursor logic guarantees that).
 */
import { randomUUID } from "node:crypto";
import { Prisma } from "@prisma/client";
import { db } from "../db";
import { parseLogLine, logBotOf, sectionOf, statusClass, isPagePath, cleanPath, utcDay, type LogLine } from "./access-log";
import { verifyCrawlerIp } from "./verify";
import { inCrawlerIpList } from "./datacenter";

export type IngestStats = { lines: number; botHits: number; humanHits: number; lookups: number };

type DailyKey = string; // date|bot|kind|status|section
type UrlKey = string; // bot|path

export async function ingestLogText(text: string, opts: { lookupBudget?: number } = {}): Promise<IngestStats> {
  const lines: LogLine[] = [];
  for (const raw of text.split("\n")) {
    if (!raw) continue;
    const l = parseLogLine(raw);
    if (l) lines.push(l);
  }
  return ingestLines(lines, opts);
}

export async function ingestLines(lines: LogLine[], opts: { lookupBudget?: number } = {}): Promise<IngestStats> {
  const stats: IngestStats = { lines: lines.length, botHits: 0, humanHits: 0, lookups: 0 };
  const budget = opts.lookupBudget ?? 30;

  // 1. Resolve which bot each line is, collecting (crawler, ip) pairs needing verification.
  type Tagged = { l: LogLine; bot: string; needs?: { id: string; ip: string }; kind?: string };
  const tagged: Tagged[] = [];
  const toVerify = new Map<string, { id: string; ip: string }>();
  for (const l of lines) {
    const b = logBotOf(l.ua);
    if (!b) {
      stats.humanHits++;
      continue;
    }
    stats.botHits++;
    if (b.type === "automation") tagged.push({ l, bot: `auto:${b.id}`, kind: "scraper" });
    else if (b.type === "generic") tagged.push({ l, bot: "other-bot", kind: "declared-crawler" });
    else {
      const def = b.def;
      if (def.ipList && inCrawlerIpList(def.ipList, l.ip)) tagged.push({ l, bot: def.id, kind: "verified-crawler" });
      else if (!def.ipList && !def.rdns?.length) tagged.push({ l, bot: def.id, kind: "declared-crawler" });
      else {
        const key = `${def.id}|${l.ip}`;
        if (!toVerify.has(key)) toVerify.set(key, { id: def.id, ip: l.ip });
        tagged.push({ l, bot: def.id, needs: { id: def.id, ip: l.ip } });
      }
    }
  }

  // 2. Verify: cache for all, live lookups for up to `budget` (parallel, each <= ~6s).
  const verdicts = new Map<string, boolean | undefined>();
  const pending = [...toVerify.values()];
  const cachedOnly = await Promise.all(pending.map((p) => verifyCrawlerIp(p.id, p.ip, { allowLookup: false })));
  const needLookup: { id: string; ip: string }[] = [];
  pending.forEach((p, i) => {
    const v = cachedOnly[i];
    if (v === undefined) needLookup.push(p);
    else verdicts.set(`${p.id}|${p.ip}`, v);
  });
  const live = needLookup.slice(0, budget);
  stats.lookups = live.length;
  const liveRes = await Promise.all(live.map((p) => verifyCrawlerIp(p.id, p.ip, { allowLookup: true }).catch(() => undefined)));
  live.forEach((p, i) => verdicts.set(`${p.id}|${p.ip}`, liveRes[i]));

  // 3. Aggregate.
  const daily = new Map<DailyKey, { date: Date; bot: string; kind: string; sc: string; section: string; hits: number; bytes: number }>();
  const urls = new Map<UrlKey, { bot: string; path: string; hits: number; lastStatus: number; first: Date; last: Date }>();
  for (const t of tagged) {
    let kind = t.kind;
    if (!kind && t.needs) {
      const v = verdicts.get(`${t.needs.id}|${t.needs.ip}`);
      kind = v === true ? "verified-crawler" : v === false ? "scraper" : "declared-crawler";
    }
    const k = kind ?? "declared-crawler";
    const date = utcDay(t.l.ts);
    const section = sectionOf(t.l.path);
    const sc = statusClass(t.l.status);
    const dk = `${date.toISOString()}|${t.bot}|${k}|${sc}|${section}`;
    const d = daily.get(dk) ?? { date, bot: t.bot, kind: k, sc, section, hits: 0, bytes: 0 };
    d.hits++;
    d.bytes += t.l.bytes;
    daily.set(dk, d);
    // Per-URL state only for genuine crawlers (a spoofer's URL list is noise).
    if (isPagePath(section) && k !== "scraper") {
      const path = cleanPath(t.l.path).slice(0, 300);
      const uk = `${t.bot}|${path}`;
      const u = urls.get(uk) ?? { bot: t.bot, path, hits: 0, lastStatus: t.l.status, first: t.l.ts, last: t.l.ts };
      u.hits++;
      if (t.l.ts >= u.last) {
        u.last = t.l.ts;
        u.lastStatus = t.l.status;
      }
      if (t.l.ts < u.first) u.first = t.l.ts;
      urls.set(uk, u);
    }
  }

  // 4. Write (chunks of 500 rows per statement).
  const dRows = [...daily.values()];
  for (let i = 0; i < dRows.length; i += 500) {
    const chunk = dRows.slice(i, i + 500);
    await db.$executeRaw`
      INSERT INTO "CrawlerDaily" (id, date, bot, kind, "statusClass", section, hits, bytes, "updatedAt")
      VALUES ${Prisma.join(chunk.map((r) => Prisma.sql`(${randomUUID()}, ${r.date}, ${r.bot}, ${r.kind}, ${r.sc}, ${r.section}, ${r.hits}, ${BigInt(r.bytes)}, now())`))}
      ON CONFLICT (date, bot, kind, "statusClass", section)
      DO UPDATE SET hits = "CrawlerDaily".hits + EXCLUDED.hits, bytes = "CrawlerDaily".bytes + EXCLUDED.bytes, "updatedAt" = now()`;
  }
  const uRows = [...urls.values()];
  for (let i = 0; i < uRows.length; i += 500) {
    const chunk = uRows.slice(i, i + 500);
    await db.$executeRaw`
      INSERT INTO "CrawlerUrl" (id, bot, path, hits, "lastStatus", "firstSeen", "lastSeen")
      VALUES ${Prisma.join(chunk.map((r) => Prisma.sql`(${randomUUID()}, ${r.bot}, ${r.path}, ${r.hits}, ${r.lastStatus}, ${r.first}, ${r.last})`))}
      ON CONFLICT (bot, path) DO UPDATE SET
        hits = "CrawlerUrl".hits + EXCLUDED.hits,
        "lastStatus" = CASE WHEN EXCLUDED."lastSeen" >= "CrawlerUrl"."lastSeen" THEN EXCLUDED."lastStatus" ELSE "CrawlerUrl"."lastStatus" END,
        "lastSeen" = GREATEST("CrawlerUrl"."lastSeen", EXCLUDED."lastSeen"),
        "firstSeen" = LEAST("CrawlerUrl"."firstSeen", EXCLUDED."firstSeen")`;
  }
  return stats;
}

