// Incremental nginx access-log → crawler-activity sweep.
//
// Crawlers mostly don't run our JS beacon, so the access log is the only honest
// record of what Googlebot/Amazonbot/etc. actually fetch. Every tick reads at
// most MAX_BYTES new bytes from the live log (byte-offset cursor in
// CrawlLogCursor), aggregates bot hits via lib/bots/crawler-ingest.ts, and
// advances the cursor only past COMPLETE lines it has written.
//
// logrotate: the cursor stores the file's inode. When the live path's inode
// changes, the old file (now access.log.1, same inode — delaycompress) is
// drained from the saved offset first, then the new file is read from 0. If the
// old inode can't be found any more (rotated twice between ticks — not possible
// at the 2-minute cadence), its remaining tail is skipped, never double-counted.
//
// Inert when the log isn't readable (staging boxes, dev): logs once, returns.
import { promises as fs } from "node:fs";
import path from "node:path";
import { db } from "../lib/db";
import { ingestLogText } from "../lib/bots/crawler-ingest";

const LOG_PATH = process.env.NXEON_ACCESS_LOG ?? "/var/log/nginx/access.log";
const MAX_BYTES = 8 * 1024 * 1024;
let warned = false;

async function readChunk(file: string, offset: number): Promise<{ text: string; consumed: number } | null> {
  const fh = await fs.open(file, "r");
  try {
    const st = await fh.stat();
    if (offset >= st.size) return { text: "", consumed: 0 };
    const len = Math.min(MAX_BYTES, st.size - offset);
    const buf = Buffer.alloc(len);
