  const cur = await db.crawlLogCursor.findUnique({ where: { id: LOG_PATH } });
  let total = { lines: 0, botHits: 0 };

  // First run: start at the beginning of today's live file (it starts at the
  // last rotation, so this is "today so far"). Capped per tick, catches up.
  let offset = 0;
  if (cur && cur.inode !== inode) {
    // Rotated: drain the old file's tail (bounded per tick), then switch.
    const old = await findByInode(path.dirname(LOG_PATH), path.basename(LOG_PATH), cur.inode);
    if (old) {
      const chunk = await readChunk(old, Number(cur.offset));
      if (chunk && chunk.consumed > 0) {
        const s = await ingestLogText(chunk.text);
        await db.crawlLogCursor.update({ where: { id: LOG_PATH }, data: { offset: cur.offset + BigInt(chunk.consumed) } });
