/**
 * One-off (idempotent, re-runnable) bot classification backfill for `Visit`.
 *
 * Step 1  per-row: every row with botKind IS NULL (or every row with --force)
 *         is run through the same classifier /api/track uses at ingest
 *         (lib/bots/classify.ts) — UA catalogue, official crawler IP lists,
 *         stale-browser, datacenter IP, cached FCrDNS verdicts. No live DNS.
 * Step 2  per-day UA clusters: the residential-proxy fleet signature (one UA,
 *         >= 25 IPs in a day, ~all referrer-less single-page landings) is
 *         applied day by day over history, exactly like the worker's rolling
 *         24h pass (worker/bot-classify.ts).
 * Step 3  re-roll VisitorDaily for every day touched so the stored audience
 *         trend becomes bot-free too.
 *
 * Safe on prod-sized tables: keyset-paginated batches (default 2000 rows),
 * one UPDATE ... FROM (VALUES …) per batch, a short pause between batches, no
 * long transaction, no table lock beyond row locks. Ctrl-C at any point is
 * fine — re-running continues where it left off (botKind IS NULL).
 *
 * Usage:
 *   npx tsx scripts/backfill-bot-classification.ts --dry-run      # counts only, no writes
 *   npx tsx scripts/backfill-bot-classification.ts                # classify unclassified rows + clusters + re-roll
 *   npx tsx scripts/backfill-bot-classification.ts --force        # re-classify EVERY row (after a catalogue change)
 *   flags: --batch=2000 --sleep-ms=100 --no-clusters --no-reroll
 */
import { Prisma } from "@prisma/client";
import { db } from "../lib/db";
import { classifyHit, type BotKind } from "../lib/bots/classify";
import { computeVisitorDay } from "../lib/analytics";
import { CLUSTER_MIN_IPS, CLUSTER_MIN_RATIO } from "../worker/bot-classify";

const args = new Map(
  process.argv.slice(2).map((a) => {
    const [k, v] = a.replace(/^--/, "").split("=");
    return [k, v ?? "1"] as [string, string];
  }),
);
const DRY = args.has("dry-run");
const FORCE = args.has("force");
const BATCH = Math.max(100, Math.min(10_000, Number(args.get("batch") ?? 2000)));
const SLEEP = Math.max(0, Number(args.get("sleep-ms") ?? 100));

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

async function main() {
  const t0 = Date.now();
  const where = FORCE ? Prisma.sql`TRUE` : Prisma.sql`"botKind" IS NULL`;
  const [{ n }] = await db.$queryRaw<{ n: bigint }[]>`SELECT count(*)::bigint AS n FROM "Visit" WHERE ${where}`;
  console.log(`[backfill] ${n} rows to classify${FORCE ? " (--force: all rows)" : ""}${DRY ? " — DRY RUN" : ""}`);

  // Cached FCrDNS verdicts (written by the worker) — used, never looked up here.
  const verdictRows = await db.crawlerIpVerdict.findMany({ select: { ip: true, claimed: true, verified: true } });
  const verdicts = new Map(verdictRows.map((v) => [v.ip, v]));

  const tally = new Map<BotKind, number>();
  const touchedDays = new Set<string>();
  let lastCreated = new Date(0);
  let lastId = "";
  let done = 0;
  for (;;) {
    const rows = await db.$queryRaw<{ id: string; ua: string | null; ip: string; userId: string | null; webdriver: boolean | null; createdAt: Date }[]>`
      SELECT id, ua, ip, "userId", webdriver, "createdAt" FROM "Visit"
      WHERE ${where} AND ("createdAt", id) > (${lastCreated}, ${lastId})
      ORDER BY "createdAt", id
      LIMIT ${BATCH}`;
    if (rows.length === 0) break;
    const updates: Prisma.Sql[] = [];
    for (const r of rows) {
      const cached = verdicts.get(r.ip);
      const v = classifyHit({
        ua: r.ua,
        ip: r.ip,
        userId: r.userId,
        webdriver: r.webdriver,
        rdnsVerified: cached ? cached.verified : undefined,
        // Judge staleness against the visit's own date, not today's.
        now: r.createdAt,
      });
      tally.set(v.botKind, (tally.get(v.botKind) ?? 0) + 1);
      if (v.isBot) touchedDays.add(r.createdAt.toISOString().slice(0, 10));
      updates.push(Prisma.sql`(${r.id}, ${v.isBot}, ${v.botKind}, ${v.botReason})`);
    }
    if (!DRY) {
      await db.$executeRaw`
        UPDATE "Visit" AS v SET "isBot" = u.is_bot, "botKind" = u.kind, "botReason" = u.reason, "botCheckedAt" = now()
        FROM (VALUES ${Prisma.join(updates)}) AS u(id, is_bot, kind, reason)
        WHERE v.id = u.id`;
    }
    const last = rows[rows.length - 1];
    lastCreated = last.createdAt;
    lastId = last.id;
    done += rows.length;
    if (done % (BATCH * 5) === 0 || rows.length < BATCH) {
      console.log(`[backfill] ${done}/${n} …`, Object.fromEntries(tally));
    }
    if (SLEEP) await sleep(SLEEP);
  }
  console.log("[backfill] per-row verdicts:", Object.fromEntries(tally));

  // ---- Step 2: historical UA clusters, one UTC day at a time ----
  if (!args.has("no-clusters")) {
    const [{ first }] = await db.$queryRaw<{ first: Date | null }[]>`SELECT min("createdAt") AS first FROM "Visit"`;
    if (first) {
      let day = new Date(Date.UTC(first.getUTCFullYear(), first.getUTCMonth(), first.getUTCDate()));
      let clustered = 0;
      while (day.getTime() < Date.now()) {
        const next = new Date(day.getTime() + 86_400_000);
        const clusters = await db.$queryRaw<{ ua: string; ips: bigint }[]>`
          WITH s AS (
            SELECT "sessionId", count(*) AS n FROM "Visit"
            WHERE "createdAt" >= ${day} AND "createdAt" < ${next} AND "sessionId" IS NOT NULL GROUP BY "sessionId"
          )
          SELECT v.ua, count(DISTINCT v.ip)::bigint AS ips FROM "Visit" v
          LEFT JOIN s ON s."sessionId" = v."sessionId"
          WHERE v."createdAt" >= ${day} AND v."createdAt" < ${next} AND v."userId" IS NULL AND v."isBot" = false AND v.ua IS NOT NULL
          GROUP BY v.ua
          HAVING count(DISTINCT v.ip) >= ${CLUSTER_MIN_IPS}
             AND avg(CASE WHEN v.referrer IS NULL AND v."isEntry" THEN 1.0 ELSE 0.0 END) >= ${CLUSTER_MIN_RATIO}
             AND avg(CASE WHEN coalesce(s.n, 1) = 1 THEN 1.0 ELSE 0.0 END) >= ${CLUSTER_MIN_RATIO}
             AND avg(CASE WHEN v.interacted IS TRUE THEN 1.0 ELSE 0.0 END) < 0.05`;
        for (const c of clusters) {
          if (DRY) {
            const cnt = await db.visit.count({ where: { ua: c.ua, userId: null, isBot: false, createdAt: { gte: day, lt: next } } });
            clustered += cnt;
          } else {
            const u = await db.visit.updateMany({
              where: { ua: c.ua, userId: null, isBot: false, createdAt: { gte: day, lt: next } },
              data: { isBot: true, botKind: "suspected-bot", botReason: `ua-cluster:${Number(c.ips)}ips`, botCheckedAt: new Date() },
            });
            clustered += u.count;
          }
          touchedDays.add(day.toISOString().slice(0, 10));
        }
        day = next;
      }
      console.log(`[backfill] ua-cluster rows ${DRY ? "that would be " : ""}marked: ${clustered}`);
    }
  }

  // ---- Step 3: re-roll VisitorDaily for touched days ----
  if (!DRY && !args.has("no-reroll")) {
    const days = [...touchedDays].sort();
    for (const d of days) {
      const dayStart = new Date(`${d}T00:00:00.000Z`);
      const dayEnd = new Date(dayStart.getTime() + 86_400_000 - 1);
      const existing = await db.visitorDaily.findUnique({ where: { date: dayStart } });
      if (!existing) continue; // never rolled — nothing stale to fix
      const m = await computeVisitorDay(dayStart, dayEnd);
      await db.visitorDaily.update({
        where: { date: dayStart },
        data: {
          pageviews: m.pageviews,
          sessions: m.sessions,
          uniqueVisitors: m.uniqueVisitors,
          newVisitors: m.newVisitors,
          returningVisitors: m.returningVisitors,
          bounces: m.bounces,
          totalSessionMs: BigInt(m.avgSessionMs) * BigInt(m.sessions),
        },
      });
    }
    console.log(`[backfill] re-rolled VisitorDaily for ${days.length} day(s)`);
  }
  console.log(`[backfill] done in ${((Date.now() - t0) / 1000).toFixed(1)}s`);
}

main()
  .catch((e) => {
    console.error(e);
    process.exitCode = 1;
  })
  .finally(() => db.$disconnect());

