/**
 * One-off: load crawler activity from the ROTATED nginx logs (access.log.1 and
 * access.log.N.gz, ~14 days on this box) into CrawlerDaily / CrawlerUrl, so the
 * Crawler-activity view has history from day one. The live file is handled by
 * the worker (worker/crawler-log.ts) — this script never touches it.
 *
 * Idempotent: each processed file is recorded by INODE as a `done:<inode>`
 * CrawlLogCursor row (inodes survive logrotate's renames), and a file whose
 * inode is the worker's live cursor, or already done, is skipped. So it is
 * safe to re-run, and safe to run while the worker is running.
 *
 * Usage (as root — the logs are root/adm-readable):
 *   npx tsx scripts/backfill-crawler-log.ts --dry-run   # list what would be processed
 *   npx tsx scripts/backfill-crawler-log.ts             # process (FCrDNS lookups budgeted per chunk)
 *   flags: --dir=/var/log/nginx --lookups=20
 */
import { promises as fs, createReadStream } from "node:fs";
import { createGunzip } from "node:zlib";
import readline from "node:readline";
import path from "node:path";
import { db } from "../lib/db";
import { parseLogLine, type LogLine } from "../lib/bots/access-log";
import { ingestLines } from "../lib/bots/crawler-ingest";

const args = new Map(
  process.argv.slice(2).map((a) => {
    const [k, v] = a.replace(/^--/, "").split("=");
    return [k, v ?? "1"] as [string, string];
  }),
);
const DIR = args.get("dir") ?? "/var/log/nginx";
const LIVE = process.env.NXEON_ACCESS_LOG ?? path.join(DIR, "access.log");
const DRY = args.has("dry-run");
const LOOKUPS = Number(args.get("lookups") ?? 20);
const CHUNK = 20_000;

async function main() {
  const live = await db.crawlLogCursor.findUnique({ where: { id: LIVE } });
  const names = (await fs.readdir(DIR)).filter((n) => /^access\.log\.\d+(\.gz)?$/.test(n));
  names.sort((a, b) => Number(b.split(".")[2]) - Number(a.split(".")[2])); // oldest first
  for (const name of names) {
    const file = path.join(DIR, name);
    const st = await fs.stat(file);
    const inode = String(st.ino);
    if (live && live.inode === inode) {
      console.log(`skip ${name}: it is the worker's live cursor file`);
      continue;
    }
    const done = await db.crawlLogCursor.findUnique({ where: { id: `done:${inode}` } });
    if (done) {
      console.log(`skip ${name}: already processed`);
      continue;
    }
    if (DRY) {
      console.log(`would process ${name} (${(st.size / 1e6).toFixed(1)} MB)`);
      continue;
    }
    const input = name.endsWith(".gz") ? createReadStream(file).pipe(createGunzip()) : createReadStream(file);
    const rl = readline.createInterface({ input, crlfDelay: Infinity });
    let buf: LogLine[] = [];
    let lines = 0;
    let bots = 0;
    for await (const raw of rl) {
      const l = parseLogLine(raw);
      if (!l) continue;
      buf.push(l);
      if (buf.length >= CHUNK) {
        const s = await ingestLines(buf, { lookupBudget: LOOKUPS });
        lines += s.lines;
        bots += s.botHits;
        buf = [];
      }
    }
    if (buf.length) {
      const s = await ingestLines(buf, { lookupBudget: LOOKUPS });
      lines += s.lines;
      bots += s.botHits;
    }
    await db.crawlLogCursor.create({ data: { id: `done:${inode}`, inode, offset: BigInt(st.size) } });
    console.log(`${name}: ${lines} lines, ${bots} bot hits`);
  }
}

main()
  .catch((e) => {
    console.error(e);
    process.exitCode = 1;
  })
  .finally(() => db.$disconnect());

