/**
 * Pure maths + formatting helpers for /admin/insights. No DB, no React — unit
 * tested in test/insights-stats.test.ts.
 */

/** Linear-interpolated percentile (p in 0..100) of an unsorted array; null when empty. */
export function percentile(values: number[], p: number): number | null {
  const v = values.filter((x) => Number.isFinite(x)).sort((a, b) => a - b);
  if (v.length === 0) return null;
  if (v.length === 1) return v[0];
  const rank = (Math.min(Math.max(p, 0), 100) / 100) * (v.length - 1);
  const lo = Math.floor(rank);
  const hi = Math.ceil(rank);
  return v[lo] + (v[hi] - v[lo]) * (rank - lo);
}

export function mean(values: number[]): number | null {
  const v = values.filter((x) => Number.isFinite(x));
  return v.length ? v.reduce((a, b) => a + b, 0) / v.length : null;
}

export function stddev(values: number[]): number | null {
  const m = mean(values);
  if (m == null || values.length < 2) return null;
  const s = values.reduce((a, b) => a + (b - m) ** 2, 0) / (values.length - 1);
  return Math.sqrt(s);
}

/** Least-squares fit y = a + b·x. null with < 2 distinct x values. */
export function linearFit(points: { x: number; y: number }[]): { slope: number; intercept: number; r2: number } | null {
  const n = points.length;
  if (n < 2) return null;
  const mx = points.reduce((s, p) => s + p.x, 0) / n;
  const my = points.reduce((s, p) => s + p.y, 0) / n;
  let sxx = 0;
  let sxy = 0;
  let syy = 0;
  for (const p of points) {
    sxx += (p.x - mx) ** 2;
    sxy += (p.x - mx) * (p.y - my);
    syy += (p.y - my) ** 2;
  }
  if (sxx === 0) return null;
  const slope = sxy / sxx;
  const intercept = my - slope * mx;
  const r2 = syy === 0 ? 1 : (sxy * sxy) / (sxx * syy);
  return { slope, intercept, r2 };
}

/**
 * Days until `current` reaches `capacity` growing at `slopePerDay`. null when
 * not growing (slope <= 0) — "never at this rate", which the UI says honestly
 * instead of inventing a date. 0 when already at/over capacity.
 */
export function daysUntil(current: number, capacity: number, slopePerDay: number): number | null {
  if (capacity <= 0) return null;
  if (current >= capacity) return 0;
  if (!(slopePerDay > 0)) return null;
  return Math.ceil((capacity - current) / slopePerDay);
}

/** Relative change (cur vs prev) as a fraction, null when prev is 0/absent. */
export function relChange(cur: number, prev: number | null | undefined): number | null {
  if (prev == null || prev === 0) return null;
  return (cur - prev) / Math.abs(prev);
}

export function fmtPct(frac: number | null | undefined, digits = 0): string {
  if (frac == null || !Number.isFinite(frac)) return "—";
  return `${(frac * 100).toFixed(digits)}%`;
}

export function fmtDelta(frac: number | null): string | undefined {
  if (frac == null || !Number.isFinite(frac)) return undefined;
  const s = (frac * 100).toFixed(Math.abs(frac) < 0.1 ? 1 : 0);
  return `${frac >= 0 ? "+" : ""}${s}% vs previous period`;
}

export function fmtCents(cents: number | null | undefined): string {
  if (cents == null || !Number.isFinite(cents)) return "—";
  const neg = cents < 0;
  const v = Math.abs(cents) / 100;
  const s = v >= 10_000 ? v.toLocaleString("en-US", { maximumFractionDigits: 0 }) : v.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  return `${neg ? "-" : ""}$${s}`;
}

export function fmtDuration(ms: number | null | undefined): string {
  if (ms == null || !Number.isFinite(ms)) return "—";
  const s = ms / 1000;
  if (s < 60) return `${s.toFixed(s < 10 ? 1 : 0)}s`;
  const m = s / 60;
  if (m < 60) return `${m.toFixed(m < 10 ? 1 : 0)}m`;
  const h = m / 60;
  if (h < 48) return `${h.toFixed(h < 10 ? 1 : 0)}h`;
  return `${(h / 24).toFixed(1)}d`;
}

/** RFC-4180 CSV. Cells containing , " CR LF are quoted; formula-leading cells are defused. */
export function toCsv(rows: (string | number | boolean | null | undefined)[][]): string {
  return rows
    .map((r) =>
      r
        .map((c) => {
          if (c == null) return "";
          let s = String(c);
          // CSV-injection guard: a cell starting with = + - @ (that isn't a plain number) opens as a formula in Excel.
          if (/^[=+\-@\t\r]/.test(s) && !/^-?\d+(\.\d+)?$/.test(s)) s = `'${s}`;
          return /[",\r\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
        })
        .join(","),
    )
    .join("\r\n");
}

/** UTC month key "2026-09". */
export function monthKeyUTC(d: Date): string {
  return `${d.getUTCFullYear()}-${String(d.getUTCMonth() + 1).padStart(2, "0")}`;
}

/** Whole months between two month keys (b - a). */
export function monthDiff(a: string, b: string): number {
  const [ay, am] = a.split("-").map(Number);
  const [by, bm] = b.split("-").map(Number);
  return (by - ay) * 12 + (bm - am);
}

/** z-score of `x` against a baseline; null when the baseline has no spread. */
export function zScore(x: number, baseline: number[]): number | null {
  const m = mean(baseline);
  const s = stddev(baseline);
  if (m == null || s == null || s === 0) return null;
  return (x - m) / s;
}

