        from = new Date(Date.UTC(today.getUTCFullYear(), 0, 1));
        break;
      default: {
        const n = Number(preset.replace("d", ""));
        from = new Date(tomorrow.getTime() - n * DAY);
      }
    }
  }
  // Cap at 3 years so a typo can't ask for a 50-year scan.
  if (to.getTime() - from.getTime() > 3 * 366 * DAY) from = new Date(to.getTime() - 3 * 366 * DAY);
  const days = Math.max(1, Math.round((to.getTime() - from.getTime()) / DAY));
  const prevTo = from;
  const prevFrom = new Date(from.getTime() - days * DAY);
  const lastDay = new Date(to.getTime() - DAY);
  return {
    from,
    to,
    days,
    prevFrom,
    prevTo,
    preset,
    fromStr: ymd(from),
    toStr: ymd(lastDay),
    label: preset ? (PRESETS.find((p) => p.key === preset)?.label ?? preset) : `${ymd(from)} → ${ymd(lastDay)}`,
  };
}

/** Day buckets [from, to) as UTC midnights. */
export function dayBuckets(from: Date, to: Date): Date[] {
  const out: Date[] = [];
  for (let t = utcMidnight(from).getTime(); t < to.getTime(); t += DAY) out.push(new Date(t));
  return out;
}

/** Bucket granularity that keeps a chart readable: day ≤ 62d, week ≤ 1y, else month. */
export function granularity(days: number): "day" | "week" | "month" {
  return days <= 62 ? "day" : days <= 366 ? "week" : "month";
}

export function bucketKey(d: Date, g: "day" | "week" | "month"): string {
  if (g === "day") return ymd(d);
  if (g === "month") return ymd(d).slice(0, 7);
  // ISO-ish week start (Monday, UTC)
  const day = (d.getUTCDay() + 6) % 7;
  return ymd(new Date(utcMidnight(d).getTime() - day * DAY));
}

export function bucketKeys(from: Date, to: Date, g: "day" | "week" | "month"): string[] {
  const keys: string[] = [];
  for (const d of dayBuckets(from, to)) {
    const k = bucketKey(d, g);
    if (keys[keys.length - 1] !== k) keys.push(k);
  }
  return keys;
}

