/** Refuse deploys once the pool's REAL free space would sit below this (GB). */
export const DISK_MIN_FREE_GB = Number(process.env.NXEON_DISK_MIN_FREE_GB ?? 20);

/** Effective committable RAM ceiling in MB after reserve + oversell. */
export function ramCeilingMB(): number {
  return Math.max(0, (HOST_RAM_MB - HOST_RAM_RESERVE_MB) * RAM_OVERSELL_FACTOR);
}

export type CapacitySnapshot = {
  committedRamMB: number;
  committedDiskGB: number;
  ceilingRamMB: number;
  serverCount: number;
  /** 0..1 fraction of the RAM ceiling already committed. */
  ramUtilization: number;
  /** true once committed RAM is within 15% of the ceiling. */
  nearCapacity: boolean;
};

/** Sum committed RAM/disk across all servers that are not being torn down. */
export async function capacitySnapshot(): Promise<CapacitySnapshot> {
  const servers = await db.server.findMany({
    where: { status: { not: "DELETING" } },
    select: {
      extraDiskGB: true,
      plan: { select: { ramMB: true, diskGB: true } },
      gamePlan: { select: { ramMB: true, diskGB: true } },
    },
  });
  // A game server's real commitment is its game plan's, not the (larger)
  // base VPS plan it rides on — overstating this made the platform think it
  // had less real capacity than it did.
  const committedRamMB = servers.reduce((sum, s) => sum + (s.gamePlan?.ramMB ?? s.plan.ramMB), 0);
  const committedDiskGB = servers.reduce((sum, s) => sum + effectiveDiskGB(baseDiskGBFor(s), s.extraDiskGB), 0);
  const ceilingRamMB = ramCeilingMB();
  const ramUtilization = ceilingRamMB > 0 ? committedRamMB / ceilingRamMB : 1;
  return {
    committedRamMB,
    committedDiskGB,
    ceilingRamMB,
    serverCount: servers.length,
    ramUtilization,
    nearCapacity: ramUtilization >= 0.85,
  };
}

/**
 * Pure boundary check, split out of `capacityCheckRamMB` so it can be unit-tested
 * with no DB (see test/custom-plan-capacity.test.ts): would adding `addRamMB` to
 * what's already committed push past the ceiling?
 */
export function ramProjectionExceedsCeiling(committedRamMB: number, ceilingRamMB: number, addRamMB: number): boolean {
  return committedRamMB + addRamMB > ceilingRamMB;
}

export type DimUtil = {
  dimension: CapDimension;
  /** The value thresholded — the worse of allocation and real usage. */
  pct: number;
  /** DB-committed percent (null when the dimension has no allocation basis). */
  allocPct: number | null;
  /** Live-usage percent from Proxmox (null when unreachable / not applicable). */
  realPct: number | null;
  /** Short human breakdown, e.g. "48 / 56 GB committed · 61% used". */
  detail: string;
  /** `allocPct`'s own absolute breakdown alone, e.g. "48 / 56 GB" — for UIs that
   *  render committed and used as two separate rows instead of one combined
   *  line. Null exactly when `allocPct` is null. */
  allocDetail: string | null;
  /** `realPct`'s own absolute breakdown alone, e.g. "34 GB used" — same
   *  pairing as `allocDetail`, null exactly when `realPct` is null. */
  realDetail: string | null;
};

export type NodeUtil = {
  kind: NodeKind;
  id: string;
  name: string;
  enabled: boolean;
  /** For Proxmox: node status endpoint reachable. Hosting is DB-only → always true. */
  reachable: boolean;
  dims: DimUtil[];
  /** Worst dimension percent across `dims` (0 when there are none). */
  worstPct: number;
  severity: CapSeverity;
};

function pct(part: number, whole: number): number | null {
  if (!(whole > 0)) return null;
  return (part / whole) * 100;
}

/** Combine allocation + real into the thresholded value (worse of the two). */
function worse(allocPct: number | null, realPct: number | null): number {
  return Math.max(allocPct ?? 0, realPct ?? 0);
}

function rollup(dims: DimUtil[], t: NodeThresholds): { worstPct: number; severity: CapSeverity } {
  const worstPct = dims.reduce((m, d) => Math.max(m, d.pct), 0);
  return { worstPct, severity: severityFor(worstPct, t) };
}

