/**
 * Shared building blocks for lib/insights/*: which accounts count, which
 * servers are "live", the price-shape select the MRR formula needs, and the
 * paid-server lifetime model churn/cohorts are built on.
 */
import type { Prisma } from "@prisma/client";
import { db } from "@/lib/db";
import { REVENUE_USER_WHERE } from "@/lib/admin-metrics";

/** Server statuses that mean a real machine exists for the customer. */
export const LIVE_STATUSES = ["RUNNING", "STOPPED", "SUSPENDED", "REINSTALLING"] as const;
/** Same, plus DELETING (still counts as "was deployed" for funnels). */
export const DEPLOYED_STATUSES = [...LIVE_STATUSES, "DELETING"] as const;

/** Accounts that count toward business numbers: not staff, not flagged internal/test. */
export const CUSTOMER_WHERE: Prisma.UserWhereInput = { ...REVENUE_USER_WHERE, role: "CUSTOMER" };

/** The exact select `serverMonthlyCents` (lib/admin-metrics.ts) needs. */
export const MRR_SERVER_SELECT = {
  isFree: true,
  status: true,
  termMonths: true,
  extraDiskGB: true,
  backupTier: true,
  annualDiscountPct: true,
  plan: { select: { name: true, priceCents: true } },
  gamePlan: { select: { name: true, priceCents: true, termMonths: true } },
  dedicatedIp: { select: { id: true } },
  wantsDedicatedIp: true,
  grandfatheredRenewalCents: true,
} as const;

/** One paid-server lifetime: when it started, when it ended (null = still live). */
export type PaidLife = { userId: string; start: Date; end: Date | null };

/**
 * Every paid server lifetime we can reconstruct: live non-free servers (end
 * null) + archived (deleted) servers that ever took money. ServerArchive has
 * no isFree column, so "ever paid" = totalSpentCents > 0 — a free server that
 * was deleted never enters the model. Internal/test accounts excluded.
 */
export async function paidLifetimes(): Promise<PaidLife[]> {
  const [live, archived, excluded] = await Promise.all([
    db.server.findMany({
      where: { isFree: false, status: { in: [...LIVE_STATUSES] }, user: CUSTOMER_WHERE },
      select: { userId: true, createdAt: true },
    }),
    db.serverArchive.findMany({
      where: { totalSpentCents: { gt: 0 }, userId: { not: null } },
      select: { userId: true, provisionedAt: true, deletedAt: true },
    }),
    db.user.findMany({ where: { NOT: CUSTOMER_WHERE }, select: { id: true } }),
  ]);
  const skip = new Set(excluded.map((u) => u.id));
  const out: PaidLife[] = live.map((s) => ({ userId: s.userId, start: s.createdAt, end: null }));
  for (const a of archived) {
    if (!a.userId || skip.has(a.userId)) continue;
    out.push({ userId: a.userId, start: a.provisionedAt, end: a.deletedAt });
  }
  return out;
}

/** Users with at least one paid server alive at instant `t`. */
export function payingAt(lives: PaidLife[], t: Date): Set<string> {
  const s = new Set<string>();
  const ts = t.getTime();
  for (const l of lives) {
    if (l.start.getTime() <= ts && (l.end === null || l.end.getTime() > ts)) s.add(l.userId);
  }
  return s;
}

/** First paid-server start per user. */
export function firstPaidStart(lives: PaidLife[]): Map<string, Date> {
  const m = new Map<string, Date>();
  for (const l of lives) {
    const cur = m.get(l.userId);
    if (!cur || l.start < cur) m.set(l.userId, l.start);
  }
  return m;
}

/** A metric that may not have enough data to be honest about. */
export type Maybe<T> = { ok: true; value: T } | { ok: false; reason: string };

export function enough<T>(cond: boolean, value: () => T, reason: string): Maybe<T> {
  return cond ? { ok: true, value: value() } : { ok: false, reason };
}

