// ---------------------------------------------------------------------------
// Churn, LTV, cohorts
// ---------------------------------------------------------------------------

export type ChurnInsights = {
  startCustomers: number;
  churned: number;
  newPaying: number;
  endCustomers: number;
  churnRate: Maybe<number>;
  monthlyChurn: Maybe<number>;
  churnRatePrev: Maybe<number>;
  ltvRealized: Maybe<{ mean: number; median: number; customers: number }>;
  ltvPredicted: Maybe<number>;
  cohorts: Maybe<{ month: string; size: number; retained: (number | null)[] }[]>;
  churnedList: { userId: string; email: string; since: Date | null }[];
};

const MIN_START = 5;

function churnFor(lives: ReturnType<typeof payingAt> extends Set<string> ? Parameters<typeof payingAt>[0] : never, from: Date, to: Date) {
  const start = payingAt(lives, from);
  const end = payingAt(lives, new Date(Math.min(to.getTime(), Date.now())));
  let churned = 0;
  const churnedIds: string[] = [];
  for (const u of start) if (!end.has(u)) {
    churned++;
    churnedIds.push(u);
  }
  let newPaying = 0;
  for (const u of end) if (!start.has(u)) newPaying++;
  return { start, end, churned, churnedIds, newPaying };
}

export async function churnInsights(r: InsightsRange, mrr: { mrrCents: number; payingCustomers: number }): Promise<ChurnInsights> {
  const lives = await paidLifetimes();
  const cur = churnFor(lives, r.from, r.to);
  const prev = churnFor(lives, r.prevFrom, r.prevTo);
  const rate = cur.start.size > 0 ? cur.churned / cur.start.size : 0;
  const monthly = 1 - Math.pow(1 - rate, 30 / r.days);

  // Realized LTV: net real cash per customer who has EVER paid.
  const everPaid = [...new Set(lives.map((l) => l.userId))];
  const spend = await realLifetimeSpendCentsByUser(everPaid);
  const ltvValues = everPaid.map((u) => spend.get(u) ?? 0).filter((v) => v > 0);

  // Cohorts by first-paid month: share still paying at the end of each later month.
  const first = firstPaidStart(lives);
  const nowKey = monthKeyUTC(new Date());
  const byMonth = new Map<string, string[]>();
  for (const [u, d] of first) {
    const k = monthKeyUTC(d);
    if (monthDiff(k, nowKey) > 11) continue;
    const arr = byMonth.get(k) ?? [];
    arr.push(u);
    byMonth.set(k, arr);
  }
  const cohortRows = [...byMonth.entries()]
    .sort((a, b) => (a[0] < b[0] ? -1 : 1))
    .map(([month, users]) => {
      const span = monthDiff(month, nowKey);
      const retained: (number | null)[] = [];
      for (let k = 0; k <= 11; k++) {
        if (k > span) {
          retained.push(null);
          continue;
        }
        const [y, m] = month.split("-").map(Number);
        const endOfMonth = new Date(Date.UTC(y, m - 1 + k + 1, 1));
        const at = endOfMonth.getTime() > Date.now() ? new Date() : endOfMonth;
        const paying = payingAt(lives.filter((l) => users.includes(l.userId)), at);
        retained.push(users.length ? paying.size / users.length : null);
      }
      return { month, size: users.length, retained };
    });

  const churnedUsers = cur.churnedIds.length
    ? await db.user.findMany({ where: { id: { in: cur.churnedIds.slice(0, 50) } }, select: { id: true, email: true } })
    : [];
  const lastEnd = new Map<string, Date>();
  for (const l of lives) if (l.end && cur.churnedIds.includes(l.userId)) {
    const p = lastEnd.get(l.userId);
    if (!p || l.end > p) lastEnd.set(l.userId, l.end);
  }

  return {
    startCustomers: cur.start.size,
    churned: cur.churned,
    newPaying: cur.newPaying,
    endCustomers: cur.end.size,
    churnRate: enough(cur.start.size >= MIN_START, () => rate, `Only ${cur.start.size} paying customer(s) at the start of the period — need ${MIN_START}+ for a meaningful churn rate.`),
    monthlyChurn: enough(cur.start.size >= MIN_START, () => monthly, `Not enough paying customers at period start.`),
    churnRatePrev: enough(prev.start.size >= MIN_START, () => prev.churned / prev.start.size, `Not enough customers in the previous period.`),
    ltvRealized: enough(
      ltvValues.length >= 3,
      () => ({ mean: Math.round(mean(ltvValues) ?? 0), median: Math.round(percentile(ltvValues, 50) ?? 0), customers: ltvValues.length }),
      `Only ${ltvValues.length} customer(s) with real payments so far.`,
    ),
    ltvPredicted: enough(
      cur.start.size >= MIN_START && monthly > 0 && mrr.payingCustomers > 0,
      () => Math.round(mrr.mrrCents / mrr.payingCustomers / monthly),
      monthly === 0 && cur.start.size >= MIN_START
        ? "No churn in this period — ARPU ÷ churn is undefined (not infinite). Widen the date range."
        : "Needs a measurable churn rate first.",
    ),
    cohorts: enough(cohortRows.length > 0, () => cohortRows, "No paying customers in the last 12 months."),
    churnedList: churnedUsers.map((u) => ({ userId: u.id, email: u.email, since: lastEnd.get(u.id) ?? null })),
  };
}

