/**
 * Revenue / MRR / ARR / churn / LTV / cohorts for /admin/insights.
 *
 * Definitions (all reuse the console's audited ones — lib/admin-metrics.ts,
 * lib/revenue.ts — never a second formula):
 *   Earned revenue   Σ wallet DEBITS that are revenue (REVENUE_WHERE): money
 *                    the platform charged for service in the period.
 *   Cash in          Σ real card/PayPal/crypto payments (REAL_CASH_IN_WHERE).
 *   Refunds          Σ "Refund — …" + "Write-off …" ledger rows.
 *   MRR (now)        fleetMrrCents over every live server of a counting
 *                    account — the same number as /admin.
 *   MRR (history)    InsightsSnapshot rows written daily by the worker —
 *                    a point-in-time figure cannot be rebuilt after the fact,
 *                    so history starts when snapshots started.
 *   Customer churn   paying customers at period start with no live paid
 *                    server at period end (lib/insights/common.ts lifetimes).
 */
import { db } from "@/lib/db";
import { REVENUE_WHERE, REVENUE_USER_WHERE, currentRenewalPrices, serverMonthlyCents } from "@/lib/admin-metrics";
import { REAL_CASH_IN_WHERE, realLifetimeSpendCentsByUser } from "@/lib/revenue";
import { CUSTOMER_WHERE, LIVE_STATUSES, MRR_SERVER_SELECT, paidLifetimes, payingAt, firstPaidStart, type Maybe, enough } from "./common";
import type { InsightsRange } from "./range";
import { bucketKey, bucketKeys, granularity } from "./range";
import { mean, percentile, monthKeyUTC, monthDiff } from "./stats";

export type SeriesPoint = { key: string; value: number };

async function sumEarned(from: Date, to: Date): Promise<number> {
  const a = await db.walletTransaction.aggregate({ where: { ...REVENUE_WHERE, createdAt: { gte: from, lt: to } }, _sum: { amountCents: true } });
  return -(a._sum.amountCents ?? 0);
}

async function sumCashIn(from: Date, to: Date): Promise<number> {
  const a = await db.walletTransaction.aggregate({
    where: { ...REAL_CASH_IN_WHERE, user: REVENUE_USER_WHERE, createdAt: { gte: from, lt: to } },
    _sum: { amountCents: true },
  });
  return a._sum.amountCents ?? 0;
}

export async function sumRefunds(from: Date, to: Date): Promise<{ cents: number; count: number }> {
  const a = await db.walletTransaction.aggregate({
    where: {
      amountCents: { lt: 0 },
      createdAt: { gte: from, lt: to },
      OR: [{ description: { startsWith: "Refund" } }, { description: { startsWith: "Write-off" } }],
    },
    _sum: { amountCents: true },
    _count: { _all: true },
  });
  return { cents: -(a._sum.amountCents ?? 0), count: a._count._all };
}

/** Current MRR, paying customers, billable servers. */
export async function mrrNow(): Promise<{ mrrCents: number; payingCustomers: number; billableServers: number; byUser: Map<string, number> }> {
  const [servers, prices] = await Promise.all([
    db.server.findMany({
      where: { status: { in: [...LIVE_STATUSES] }, isFree: false, user: CUSTOMER_WHERE },
      select: { ...MRR_SERVER_SELECT, userId: true },
    }),
    currentRenewalPrices(),
  ]);
  const byUser = new Map<string, number>();
  let mrr = 0;
  let billable = 0;
  for (const s of servers) {
    const c = serverMonthlyCents(s, prices);
    if (c <= 0) continue;
    mrr += c;
    billable++;
    byUser.set(s.userId, (byUser.get(s.userId) ?? 0) + c);
  }
  return { mrrCents: mrr, payingCustomers: byUser.size, billableServers: billable, byUser };
}

export type RevenueInsights = {
  earned: number;
  earnedPrev: number;
  cashIn: number;
  cashInPrev: number;
  refunds: { cents: number; count: number };
  refundsPrev: { cents: number; count: number };
  series: { keys: string[]; earned: number[]; cashIn: number[] };
  mrrCents: number;
  arrCents: number;
  payingCustomers: number;
  billableServers: number;
  arpuCents: number | null;
  mrrHistory: Maybe<SeriesPoint[]>;
  topCustomers: { userId: string; email: string; mrrCents: number; share: number }[];
  concentrationTop5: number | null;
};

export async function revenueInsights(r: InsightsRange): Promise<RevenueInsights> {
  const g = granularity(r.days);
  const [earned, earnedPrev, cashIn, cashInPrev, refunds, refundsPrev, debits, credits, now, snaps] = await Promise.all([
    sumEarned(r.from, r.to),
    sumEarned(r.prevFrom, r.prevTo),
    sumCashIn(r.from, r.to),
    sumCashIn(r.prevFrom, r.prevTo),
    sumRefunds(r.from, r.to),
    sumRefunds(r.prevFrom, r.prevTo),
    db.walletTransaction.findMany({ where: { ...REVENUE_WHERE, createdAt: { gte: r.from, lt: r.to } }, select: { amountCents: true, createdAt: true }, take: 100_000 }),
    db.walletTransaction.findMany({
      where: { ...REAL_CASH_IN_WHERE, user: REVENUE_USER_WHERE, createdAt: { gte: r.from, lt: r.to } },
      select: { amountCents: true, createdAt: true },
      take: 100_000,
    }),
    mrrNow(),
    db.insightsSnapshot.findMany({ where: { metric: "mrr_cents", scopeId: "" }, orderBy: { date: "asc" }, take: 2000 }),
  ]);
  const keys = bucketKeys(r.from, r.to, g);
  const idx = new Map(keys.map((k, i) => [k, i]));
  const e = keys.map(() => 0);
  const c = keys.map(() => 0);
  for (const d of debits) {
    const i = idx.get(bucketKey(d.createdAt, g));
    if (i !== undefined) e[i] += -d.amountCents;
  }
  for (const d of credits) {
    const i = idx.get(bucketKey(d.createdAt, g));
    if (i !== undefined) c[i] += d.amountCents;
  }

  const ids = [...now.byUser.keys()];
  const users = ids.length ? await db.user.findMany({ where: { id: { in: ids } }, select: { id: true, email: true } }) : [];
  const email = new Map(users.map((u) => [u.id, u.email]));
  const sorted = [...now.byUser.entries()].sort((a, b) => b[1] - a[1]);
  const top5 = sorted.slice(0, 5).reduce((s, [, v]) => s + v, 0);

  return {
    earned,
    earnedPrev,
    cashIn,
    cashInPrev,
    refunds,
    refundsPrev,
    series: { keys, earned: e, cashIn: c },
    mrrCents: now.mrrCents,
    arrCents: now.mrrCents * 12,
    payingCustomers: now.payingCustomers,
    billableServers: now.billableServers,
    arpuCents: now.payingCustomers > 0 ? Math.round(now.mrrCents / now.payingCustomers) : null,
    mrrHistory: enough(
      snaps.length >= 2,
      () => snaps.map((s) => ({ key: s.date.toISOString().slice(0, 10), value: s.value })),
      snaps.length === 1
        ? `Only one daily MRR snapshot so far (${snaps[0].date.toISOString().slice(0, 10)}) — the trend appears from the second day.`
        : "No MRR snapshots yet — the worker writes one per day once this is deployed; MRR history cannot be rebuilt retroactively.",
    ),
    topCustomers: sorted.slice(0, 10).map(([userId, v]) => ({ userId, email: email.get(userId) ?? userId, mrrCents: v, share: now.mrrCents ? v / now.mrrCents : 0 })),
    concentrationTop5: now.mrrCents > 0 ? top5 / now.mrrCents : null,
  };
}

