import { db } from "@/lib/db";
import { heardLabel } from "@/lib/heard-about";

/**
 * Real, honest acquisition-source resolution for the admin Clients table.
 *
 * Two REAL signals exist in this codebase, in priority order:
 *
 *  1. Self-reported: `User.heardAboutUs`, the one-time "How did you hear about
 *     us?" first-login survey answer (see lib/heard-about.ts). Direct customer
 *     statement, so it wins when present and not "skipped".
 *
 *  2. Tracked: the Visit table (lib/analytics.ts / app/api/track) captures
 *     `utmSource`/`utmMedium`/`gclid` on ad-landing pageviews, and a stable
 *     `visitorId` cookie that survives login. There is NO direct FK from User
 *     to a signup-time UTM/gclid — registration (lib/actions.ts `register()`)
 *     never copies that onto the User row. But every authenticated pageview
 *     also stamps `Visit.userId`, and it carries the SAME `visitorId` cookie
 *     the person had before they signed up. So a real (not fabricated) join
 *     is possible: find the visitorId(s) a user's authenticated visits used,
 *     then find the EARLIEST visit under any of those visitorIds that carries
 *     a utm/gclid tag — that is their real first-touch ad attribution.
 *
 * Anyone with neither signal is genuinely unknown — this deliberately returns
 * `{ kind: "unknown" }` rather than a fabricated "Direct" fallback.
 */
export type AcquisitionSource =
  | { kind: "self-reported"; label: string }
  | { kind: "tracked"; label: string; detail: string }
  | { kind: "skipped" }
  | { kind: "unknown" };

export async function resolveAcquisitionSources(
  users: { id: string; heardAboutUs: string | null }[],
): Promise<Map<string, AcquisitionSource>> {
  const result = new Map<string, AcquisitionSource>();
  const needsTracking: string[] = [];

  for (const u of users) {
    if (u.heardAboutUs && u.heardAboutUs !== "skipped") {
      }

      for (const [userId, visitorIds] of visitorIdsByUser) {
        let best: (typeof utmVisits)[number] | undefined;
        for (const vid of visitorIds) {
          const hit = firstByVisitorId.get(vid);
          if (hit && (!best || hit.createdAt < best.createdAt)) best = hit;
        }
        if (best) {
          const label = best.utmSource
            ? best.utmMedium
              ? `${best.utmSource} / ${best.utmMedium}`
              : best.utmSource
            : "Google Ads (gclid)";
          result.set(userId, {
            kind: "tracked",
            label,
            detail: `From ad-click tracking · first tagged visit ${best.createdAt.toISOString().slice(0, 10)}${
              best.gclid ? " · gclid captured" : ""
            }`,
          });
        }
      }
    }
  }

  for (const u of users) {
    if (result.has(u.id)) continue;
    result.set(u.id, u.heardAboutUs === "skipped" ? { kind: "skipped" } : { kind: "unknown" });
  }

  return result;
}

