// Capacity
// ---------------------------------------------------------------------------

export type NodeCapacity = {
  id: string;
  name: string;
  region: string;
  enabled: boolean;
  acceptsProvisions: boolean;
  capacityRamMB: number;
  committedRamMB: number;
  committedVcpu: number;
  servers: number;
  usedRamMB: number | null;
  usedSampleServers: number;
  committedPct: number;
  usedPct: number | null;
  slopeMbPerDay: Maybe<number>;
  daysUntilFull: Maybe<number | null>;
  slopeSource: string;
};

const SAMPLE_WINDOW_MS = 2 * 3_600_000;

export async function capacityInsights(): Promise<NodeCapacity[]> {
  const [nodes, servers, snaps, archived] = await Promise.all([
    db.node.findMany({ orderBy: [{ isPrimary: "desc" }, { createdAt: "asc" }] }),
    db.server.findMany({
      where: { status: { notIn: ["DELETING", "ERROR", "PENDING"] } },
      select: { id: true, nodeId: true, createdAt: true, plan: { select: { ramMB: true, cpuCores: true } }, gamePlan: { select: { ramMB: true, cpuCores: true } } },
    }),
    db.insightsSnapshot.findMany({ where: { metric: "node_committed_ram_mb", date: { gte: new Date(Date.now() - 60 * 86_400_000) } }, orderBy: { date: "asc" } }),
    db.serverArchive.findMany({ where: { deletedAt: { gte: new Date(Date.now() - 60 * 86_400_000) } }, select: { nodeName: true, provisionedAt: true, deletedAt: true } }),
  ]);
  const primary = nodes.find((n) => n.isPrimary) ?? nodes[0];
  const nodeOf = (id: string | null) => id ?? primary?.id ?? "";

  // Latest real memory sample per server within the window.
  const ids = servers.map((s) => s.id);
  const samples = ids.length
    ? await db.serverMemSample.findMany({
        where: { serverId: { in: ids }, ts: { gte: new Date(Date.now() - SAMPLE_WINDOW_MS) } },
        orderBy: [{ serverId: "asc" }, { ts: "desc" }],
        distinct: ["serverId"],
        select: { serverId: true, usedBytes: true },
      })
    : [];
  const usedBy = new Map(samples.map((s) => [s.serverId, Number(s.usedBytes) / 1048576]));

  return nodes.map((n) => {
    const mine = servers.filter((s) => nodeOf(s.nodeId) === n.id);
    const committed = mine.reduce((a, s) => a + (s.gamePlan?.ramMB ?? s.plan.ramMB), 0);
    const vcpu = mine.reduce((a, s) => a + (s.gamePlan?.cpuCores ?? s.plan.cpuCores), 0);
    const sampled = mine.filter((s) => usedBy.has(s.id));
    const used = sampled.length ? sampled.reduce((a, s) => a + (usedBy.get(s.id) ?? 0), 0) : null;

    // Growth slope: real daily snapshots when we have >= 7 days of them,
    // otherwise reconstructed from live server creation dates + recent
    // deletions over the last 60 days (approximate — said so on the page).
    const mySnaps = snaps.filter((s) => s.scopeId === n.id);
    let fit: ReturnType<typeof linearFit> = null;
    let source = "";
    if (mySnaps.length >= 7) {
      fit = linearFit(mySnaps.map((s) => ({ x: s.date.getTime() / 86_400_000, y: s.value })));
      source = `${mySnaps.length} daily snapshots`;
    } else {
      const pts: { x: number; y: number }[] = [];
      const today = Math.floor(Date.now() / 86_400_000);
      for (let d = today - 59; d <= today; d++) {
        const t = (d + 1) * 86_400_000;
        let y = mine.filter((s) => s.createdAt.getTime() < t).reduce((a, s) => a + (s.gamePlan?.ramMB ?? s.plan.ramMB), 0);
        // Servers deleted after day d were still committed on day d — we don't
        // know their RAM (ServerArchive has none), so count them as unknown:
        // the slope is a LOWER bound when deletions happened. Flagged below.
        y += 0;
        pts.push({ x: d, y });
      }
      fit = linearFit(pts);
      const deletions = archived.filter((a) => a.nodeName === n.name).length;
      source = `reconstructed from server creation dates (60d)${deletions ? `; ${deletions} deletion(s) not reflected` : ""}`;
    }
    const slope = fit?.slope ?? 0;
    const enoughData = mine.length >= 1 && fit != null;
    return {
      id: n.id,
      name: n.name,
      region: n.region,
      enabled: n.enabled,
      acceptsProvisions: n.acceptsProvisions,
      capacityRamMB: n.capacityRamMB,
      committedRamMB: committed,
      committedVcpu: vcpu,
      servers: mine.length,
      usedRamMB: used == null ? null : Math.round(used),
      usedSampleServers: sampled.length,
      committedPct: n.capacityRamMB > 0 ? committed / n.capacityRamMB : 0,
      usedPct: used == null || n.capacityRamMB <= 0 ? null : used / n.capacityRamMB,
      slopeMbPerDay: enough(enoughData, () => slope, "No servers on this node yet."),
      daysUntilFull: enough(enoughData, () => daysUntil(committed, n.capacityRamMB, slope), "No growth data."),
      slopeSource: source,
    };
  });
}

