/**
 * Operational insights: job failure rate + latency per job type, and support
 * load + response times.
 *
 * Job timing: the Job table has createdAt/updatedAt and (once agent D1's
 * worker-metrics work lands) may gain startedAt/finishedAt columns. This
 * module checks information_schema at runtime and uses the precise columns
 * when present (queue wait = startedAt − createdAt, run = finishedAt −
 * startedAt); otherwise it reports END-TO-END latency (updatedAt − createdAt
 * for finished jobs) and says so — it never pretends to split the two.
 */
import { Prisma } from "@prisma/client";
import { db } from "@/lib/db";
import { CUSTOMER_WHERE, enough, type Maybe } from "./common";
import type { InsightsRange } from "./range";
import { percentile } from "./stats";

export type JobTypeRow = {
  type: string;
  total: number;
  done: number;
  failed: number;
  queuedNow: number;
  failRate: number | null;
  waitP50: number | null;
  waitP95: number | null;
  runP50: number | null;
  runP95: number | null;
  e2eP50: number | null;
  e2eP95: number | null;
  topError: string | null;
};

let jobCols: { started: boolean; finished: boolean } | null = null;
async function jobTimingColumns() {
  if (jobCols) return jobCols;
  try {
    const rows = await db.$queryRaw<{ column_name: string }[]>`
      SELECT column_name FROM information_schema.columns WHERE table_name = 'Job' AND column_name IN ('startedAt', 'finishedAt')`;
    const names = new Set(rows.map((r) => r.column_name));
    jobCols = { started: names.has("startedAt"), finished: names.has("finishedAt") };
  } catch {
    jobCols = { started: false, finished: false };
  }
  return jobCols;
}

export async function jobInsights(r: InsightsRange): Promise<{ rows: JobTypeRow[]; precise: boolean; totalFailRate: number | null; prevFailRate: number | null }> {
  const cols = await jobTimingColumns();
  const precise = cols.started && cols.finished;
  type Row = { type: string; status: string; createdAt: Date; updatedAt: Date; startedAt: Date | null; finishedAt: Date | null; error: string | null };
  const sel = precise
    ? Prisma.sql`"startedAt", "finishedAt"`
    : Prisma.sql`NULL::timestamp AS "startedAt", NULL::timestamp AS "finishedAt"`;
  const [jobs, prev, queued] = await Promise.all([
    db.$queryRaw<Row[]>`SELECT type::text AS type, status::text AS status, "createdAt", "updatedAt", ${sel}, left(error, 160) AS error
      FROM "Job" WHERE "createdAt" >= ${r.from} AND "createdAt" < ${r.to} LIMIT 200000`,
    db.job.groupBy({ by: ["status"], where: { createdAt: { gte: r.prevFrom, lt: r.prevTo } }, _count: { _all: true } }),
    db.job.groupBy({ by: ["type"], where: { status: "QUEUED" }, _count: { _all: true } }),
  ]);
  const queuedBy = new Map(queued.map((q) => [q.type as string, q._count._all]));
  const by = new Map<string, Row[]>();
  for (const j of jobs) {
    const a = by.get(j.type) ?? [];
    a.push(j);
    by.set(j.type, a);
  }
  const rows: JobTypeRow[] = [];
  let totDone = 0;
  let totFailed = 0;
  for (const [type, list] of by) {
    const finished = list.filter((j) => j.status === "DONE" || j.status === "FAILED");
    const done = list.filter((j) => j.status === "DONE").length;
    const failed = list.filter((j) => j.status === "FAILED").length;
    totDone += done;
    totFailed += failed;
    const e2e = finished.map((j) => j.updatedAt.getTime() - j.createdAt.getTime());
    const waits = precise ? list.filter((j) => j.startedAt).map((j) => j.startedAt!.getTime() - j.createdAt.getTime()) : [];
    const runs = precise ? finished.filter((j) => j.startedAt && j.finishedAt).map((j) => j.finishedAt!.getTime() - j.startedAt!.getTime()) : [];
    const errs = new Map<string, number>();
    for (const j of list) if (j.status === "FAILED" && j.error) {
      const k = j.error.replace(/\d+/g, "#").slice(0, 80);
      errs.set(k, (errs.get(k) ?? 0) + 1);
    }
    const topError = [...errs.entries()].sort((a, b) => b[1] - a[1])[0]?.[0] ?? null;
    rows.push({
      type,
      total: list.length,
      done,
      failed,
      queuedNow: queuedBy.get(type) ?? 0,
      failRate: done + failed > 0 ? failed / (done + failed) : null,
      waitP50: percentile(waits, 50),
      waitP95: percentile(waits, 95),
      runP50: percentile(runs, 50),
      runP95: percentile(runs, 95),
      e2eP50: percentile(e2e, 50),
      e2eP95: percentile(e2e, 95),
      topError,
    });
  }
  const pd = prev.find((p) => p.status === "DONE")?._count._all ?? 0;
  const pf = prev.find((p) => p.status === "FAILED")?._count._all ?? 0;
  return {
    rows: rows.sort((a, b) => b.total - a.total),
    precise,
    totalFailRate: totDone + totFailed > 0 ? totFailed / (totDone + totFailed) : null,
    prevFailRate: pd + pf > 0 ? pf / (pd + pf) : null,
  };
}

export type SupportInsights = {
  created: number;
  createdPrev: number;
  openNow: number;
  awaitingStaffNow: number;
  firstResponse: Maybe<{ p50: number; p90: number; n: number }>;
  firstResponsePrev: Maybe<{ p50: number }>;
  resolution: Maybe<{ p50: number; p90: number; n: number }>;
  unanswered: number;
  perHundredPaying: number | null;
