      clicksConverted: cvMap.get(p.code.toLowerCase()) ?? 0,
      attached: aMap.get(p.id) ?? 0,
      attachedAllTime: aaMap.get(p.id) ?? 0,
      revenueBaseCents: pos.reduce((s, c) => s + (c._sum.baseCents ?? 0), 0),
      commissionCents: pos.reduce((s, c) => s + (c._sum.amountCents ?? 0), 0),
      reversedCents: -neg.reduce((s, c) => s + (c._sum.amountCents ?? 0), 0),
    };
  });
  rows.sort((a, b) => b.revenueBaseCents - a.revenueBaseCents || b.clicks - a.clicks);
  return {
    rows,
    totals: {
      clicks: rows.reduce((s, x) => s + x.clicks, 0),
      attached: rows.reduce((s, x) => s + x.attached, 0),
      revenueBaseCents: rows.reduce((s, x) => s + x.revenueBaseCents, 0),
      commissionCents: rows.reduce((s, x) => s + x.commissionCents, 0),
    },
  };
}

export type EmailRow = { template: string; sent: number; failed: number; opened: number; clicked: number; openRate: number | null; clickRate: number | null };

export async function emailInsights(r: InsightsRange): Promise<{ rows: EmailRow[]; totals: EmailRow }> {
  const [all, failed, opened, clicked] = await Promise.all([
    db.emailLog.groupBy({ by: ["template"], where: { createdAt: { gte: r.from, lt: r.to } }, _count: { _all: true } }),
    db.emailLog.groupBy({ by: ["template"], where: { createdAt: { gte: r.from, lt: r.to }, status: "FAILED" }, _count: { _all: true } }),
    db.emailLog.groupBy({ by: ["template"], where: { createdAt: { gte: r.from, lt: r.to }, openedAt: { not: null } }, _count: { _all: true } }),
    db.emailLog.groupBy({ by: ["template"], where: { createdAt: { gte: r.from, lt: r.to }, clickedAt: { not: null } }, _count: { _all: true } }),
  ]);
  const m = (arr: { template: string | null; _count: { _all: number } }[]) => new Map(arr.map((a) => [a.template ?? "(none)", a._count._all]));
  const fM = m(failed);
  const oM = m(opened);
  const cM = m(clicked);
  const rows: EmailRow[] = all.map((a) => {
    const t = a.template ?? "(none)";
    const sent = a._count._all - (fM.get(t) ?? 0);
    const o = oM.get(t) ?? 0;
    const c = cM.get(t) ?? 0;
    return { template: t, sent, failed: fM.get(t) ?? 0, opened: o, clicked: c, openRate: sent > 0 ? o / sent : null, clickRate: sent > 0 ? c / sent : null };
  });
  rows.sort((a, b) => b.sent - a.sent);
  const tot = rows.reduce(
    (s, x) => ({ ...s, sent: s.sent + x.sent, failed: s.failed + x.failed, opened: s.opened + x.opened, clicked: s.clicked + x.clicked }),
    { template: "All", sent: 0, failed: 0, opened: 0, clicked: 0, openRate: null as number | null, clickRate: null as number | null },
  );
  tot.openRate = tot.sent > 0 ? tot.opened / tot.sent : null;
  tot.clickRate = tot.sent > 0 ? tot.clicked / tot.sent : null;
  return { rows, totals: tot };
}

const FAIL_TEMPLATES = ["payment_failed", "payment_retry_failed", "payment_final_notice", "paypal_payment_failed"];

export type PaymentInsights = {
  failureEmails: { template: string; count: number }[];
  failureEmailsPrev: number;
  usersWithFailures: number;
  dunningNow: { stage: number; count: number }[];
  overdueInvoices: { count: number; cents: number };
  refunds: { cents: number; count: number };
  refundsPrev: { cents: number; count: number };
  refundedInvoices: number;
  chargebacksRecorded: number;
  chargebacksPrev: number;
  recentRefunds: { when: Date; email: string; cents: number; description: string }[];
};

export async function paymentInsights(r: InsightsRange): Promise<PaymentInsights> {
  const [fails, failsPrev, failUsers, dunning, overdue, refunds, refundsPrev, refundedInv, cb, cbPrev, recent] = await Promise.all([
    db.emailLog.groupBy({ by: ["template"], where: { createdAt: { gte: r.from, lt: r.to }, template: { in: FAIL_TEMPLATES } }, _count: { _all: true } }),
    db.emailLog.count({ where: { createdAt: { gte: r.prevFrom, lt: r.prevTo }, template: { in: FAIL_TEMPLATES } } }),
    db.emailLog.findMany({ where: { createdAt: { gte: r.from, lt: r.to }, template: { in: FAIL_TEMPLATES }, userId: { not: null } }, distinct: ["userId"], select: { userId: true } }),
    db.server.groupBy({ by: ["dunningStage"], where: { dunningStage: { gt: 0 }, user: CUSTOMER_WHERE }, _count: { _all: true } }),
    db.invoice.aggregate({ where: { status: "OPEN", createdAt: { lt: new Date(Date.now() - 7 * 86_400_000) }, user: CUSTOMER_WHERE }, _count: { _all: true }, _sum: { amountCents: true } }),
    sumRefunds(r.from, r.to),
    sumRefunds(r.prevFrom, r.prevTo),
    db.invoice.count({ where: { refundedCents: { gt: 0 }, createdAt: { gte: r.from, lt: r.to } } }),
    db.auditLog.count({ where: { action: "partner.chargeback", createdAt: { gte: r.from, lt: r.to } } }),
    db.auditLog.count({ where: { action: "partner.chargeback", createdAt: { gte: r.prevFrom, lt: r.prevTo } } }),
    db.walletTransaction.findMany({
      where: { amountCents: { lt: 0 }, createdAt: { gte: r.from, lt: r.to }, OR: [{ description: { startsWith: "Refund" } }, { description: { startsWith: "Write-off" } }] },
      orderBy: { createdAt: "desc" },
      take: 15,
      select: { createdAt: true, amountCents: true, description: true, user: { select: { email: true } } },
    }),
  ]);
  return {
    failureEmails: fails.map((f) => ({ template: f.template ?? "", count: f._count._all })),
    failureEmailsPrev: failsPrev,
    usersWithFailures: failUsers.length,
    dunningNow: dunning.map((d) => ({ stage: d.dunningStage, count: d._count._all })).sort((a, b) => a.stage - b.stage),
    overdueInvoices: { count: overdue._count._all, cents: overdue._sum.amountCents ?? 0 },
    refunds,
    refundsPrev,
    refundedInvoices: refundedInv,
    chargebacksRecorded: cb,
    chargebacksPrev: cbPrev,
    recentRefunds: recent.map((x) => ({ when: x.createdAt, email: x.user.email, cents: -x.amountCents, description: x.description.slice(0, 120) })),
  };
}

