/**
 * Crawler activity (from the nginx access log, via CrawlerDaily/CrawlerUrl)
 * and bot-classification stats (from Visit) for /admin/insights → Crawlers.
 * Everything here is about bots ON PURPOSE — it is the one place they are
 * counted, so SEO can use them, and so the owner can see what was removed
 * from the human numbers.
 */
import { db } from "@/lib/db";
import { crawlerById, crawlerLabel } from "@/lib/bots/catalogue";
import type { InsightsRange } from "./range";
import { bucketKeys, bucketKey, granularity } from "./range";

export type BotRow = {
  bot: string;
  label: string;
  category: string;
  hits: number;
  pageHits: number;
  bytes: number;
  verifiedHits: number;
  spoofHits: number;
  s2xx: number;
  s3xx: number;
  s4xx: number;
  s5xx: number;
  distinctUrls: number;
};

export type CrawlerInsights = {
  hasData: boolean;
  cursor: { offset: string; updatedAt: Date } | null;
  rows: BotRow[];
  totals: { hits: number; bytes: number; humanEstimate: null };
  series: { keys: string[]; lines: { bot: string; label: string; data: number[] }[] };
  sections: { section: string; hits: number; googlebot: number; bingbot: number }[];
  errorUrls: { bot: string; path: string; status: number; hits: number; lastSeen: Date }[];
  googlebot: { distinctUrls30d: number; distinctUrlsAll: number; staleUrls: number; medianRecrawlDays: number | null } | null;
  insights: string[];
};

const SEARCH_BOTS = ["googlebot", "bingbot"];

export async function crawlerInsights(r: InsightsRange): Promise<CrawlerInsights> {
  const [daily, cursor] = await Promise.all([
    db.crawlerDaily.findMany({ where: { date: { gte: r.from, lt: r.to } }, take: 200_000 }),
    db.crawlLogCursor.findFirst({ where: { NOT: { id: { startsWith: "done:" } } }, orderBy: { updatedAt: "desc" } }),
  ]);
  const byBot = new Map<string, BotRow>();
  const g = granularity(r.days);
  const keys = bucketKeys(r.from, r.to, g);
  const kIdx = new Map(keys.map((k, i) => [k, i]));
  const seriesBy = new Map<string, number[]>();
  const sectionMap = new Map<string, { section: string; hits: number; googlebot: number; bingbot: number }>();
  for (const d of daily) {
    const row =
      byBot.get(d.bot) ??
      ({ bot: d.bot, label: crawlerLabel(d.bot), category: d.bot.startsWith("auto:") ? "automation" : (crawlerById(d.bot)?.category ?? "other"), hits: 0, pageHits: 0, bytes: 0, verifiedHits: 0, spoofHits: 0, s2xx: 0, s3xx: 0, s4xx: 0, s5xx: 0, distinctUrls: 0 } as BotRow);
    row.hits += d.hits;
    row.bytes += Number(d.bytes);
    if (d.section !== "asset" && d.section !== "api") row.pageHits += d.hits;
    if (d.kind === "verified-crawler") row.verifiedHits += d.hits;
    if (d.kind === "scraper" && !d.bot.startsWith("auto:")) row.spoofHits += d.hits;
    if (d.statusClass === "2xx") row.s2xx += d.hits;
    else if (d.statusClass === "3xx") row.s3xx += d.hits;
    else if (d.statusClass === "4xx") row.s4xx += d.hits;
    else row.s5xx += d.hits;
    byBot.set(d.bot, row);
    const i = kIdx.get(bucketKey(d.date, g));
    if (i !== undefined) {
      const arr = seriesBy.get(d.bot) ?? keys.map(() => 0);
      arr[i] += d.hits;
      seriesBy.set(d.bot, arr);
    }
    const sec = sectionMap.get(d.section) ?? { section: d.section, hits: 0, googlebot: 0, bingbot: 0 };
    sec.hits += d.hits;
    if (d.bot === "googlebot" && d.kind === "verified-crawler") sec.googlebot += d.hits;
    if (d.bot === "bingbot" && d.kind === "verified-crawler") sec.bingbot += d.hits;
    sectionMap.set(d.section, sec);
  }

  // Distinct URLs per bot seen in range.
  const urlCounts = await db.crawlerUrl.groupBy({ by: ["bot"], where: { lastSeen: { gte: r.from } }, _count: { _all: true } });
  for (const u of urlCounts) {
    const row = byBot.get(u.bot);
    if (row) row.distinctUrls = u._count._all;
  }
  const rows = [...byBot.values()].sort((a, b) => b.hits - a.hits);
  const top = rows.filter((x) => !x.bot.startsWith("auto:")).slice(0, 5);

  const errorUrls = await db.crawlerUrl.findMany({
    where: { lastStatus: { gte: 400 }, lastSeen: { gte: r.from }, bot: { in: [...SEARCH_BOTS, "applebot", "duckduckbot", "yandexbot"] } },
    orderBy: { hits: "desc" },
    take: 25,
    select: { bot: true, path: true, lastStatus: true, hits: true, lastSeen: true },
  });

  let googlebot: CrawlerInsights["googlebot"] = null;
  const gAll = await db.crawlerUrl.count({ where: { bot: "googlebot" } });
  if (gAll > 0) {
    const since30 = new Date(Date.now() - 30 * 86_400_000);
    const [g30, stale, sample] = await Promise.all([
      db.crawlerUrl.count({ where: { bot: "googlebot", lastSeen: { gte: since30 } } }),
      db.crawlerUrl.count({ where: { bot: "googlebot", lastSeen: { lt: since30 } } }),
      db.crawlerUrl.findMany({ where: { bot: "googlebot", hits: { gt: 1 } }, select: { firstSeen: true, lastSeen: true, hits: true }, take: 5000 }),
    ]);
    const gaps = sample.map((s) => (s.lastSeen.getTime() - s.firstSeen.getTime()) / 86_400_000 / (s.hits - 1)).sort((a, b) => a - b);
    googlebot = { distinctUrls30d: g30, distinctUrlsAll: gAll, staleUrls: stale, medianRecrawlDays: gaps.length ? gaps[Math.floor(gaps.length / 2)] : null };
  }

  // Data-derived insights — each one only emitted when its numbers exist.
  const insights: string[] = [];
  const totalHits = rows.reduce((s, x) => s + x.hits, 0);
  const totalBytes = rows.reduce((s, x) => s + x.bytes, 0);
  if (totalHits > 0) {
    const biggest = rows[0];
    insights.push(`${biggest.label} made ${Math.round((biggest.hits / totalHits) * 100)}% of all bot requests (${biggest.hits.toLocaleString()}) and used ${totalBytes ? Math.round((biggest.bytes / totalBytes) * 100) : 0}% of bot bandwidth.`);
    const gb = byBot.get("googlebot");
    if (gb && gb.hits > 0) {
      const non2xx = gb.s3xx + gb.s4xx + gb.s5xx;
      insights.push(`Googlebot: ${Math.round((non2xx / gb.hits) * 100)}% of its fetches got a non-200 response (${gb.s3xx} redirects, ${gb.s4xx} client errors, ${gb.s5xx} server errors) — crawl budget spent on those is wasted.`);
      if (gb.spoofHits > 0) insights.push(`${gb.spoofHits.toLocaleString()} requests claimed to be Googlebot but failed reverse-DNS verification — those are scrapers, not Google.`);
    } else {
      insights.push("No verified Googlebot traffic in this range.");
    }
    const ai = rows.filter((x) => x.category === "ai");
    const aiHits = ai.reduce((s, x) => s + x.hits, 0);
    if (aiHits > 0) insights.push(`AI crawlers (${ai.map((x) => x.label).slice(0, 4).join(", ")}) made ${Math.round((aiHits / totalHits) * 100)}% of bot requests. They can be throttled or blocked per-bot in robots.txt if they cost more than the AI-search visibility is worth.`);
    const mods = sectionMap.get("mods");
    if (mods && mods.hits > 0) insights.push(`/mods/* pages took ${Math.round((mods.hits / totalHits) * 100)}% of all bot requests (${mods.googlebot.toLocaleString()} from verified Googlebot).`);
  }

  return {
    hasData: daily.length > 0,
    cursor: cursor ? { offset: cursor.offset.toString(), updatedAt: cursor.updatedAt } : null,
    rows,
    totals: { hits: totalHits, bytes: totalBytes, humanEstimate: null },
    series: { keys, lines: top.map((t) => ({ bot: t.bot, label: t.label, data: seriesBy.get(t.bot) ?? keys.map(() => 0) })) },
    sections: [...sectionMap.values()].sort((a, b) => b.hits - a.hits).slice(0, 15),
    errorUrls: errorUrls.map((e) => ({ bot: e.bot, path: e.path, status: e.lastStatus, hits: e.hits, lastSeen: e.lastSeen })),
    googlebot,
    insights,
  };
}

export type VisitBotStats = {
  total: number;
  bots: number;
  unclassified: number;
  byKind: { kind: string; count: number }[];
  topReasons: { reason: string; count: number }[];
  flaggedIps: number;
};

export async function visitBotStats(r: InsightsRange): Promise<VisitBotStats> {
  const where = { createdAt: { gte: r.from, lt: r.to } };
  const [total, kinds, reasons, flagged] = await Promise.all([
    db.visit.count({ where }),
    db.visit.groupBy({ by: ["botKind"], where, _count: { _all: true } }),
    db.visit.groupBy({ by: ["botReason"], where: { ...where, isBot: true }, _count: { _all: true }, orderBy: { _count: { botReason: "desc" } }, take: 12 }),
    db.botIpFlag.count({ where: { expiresAt: { gt: new Date() } } }),
  ]);
  const bots = kinds.filter((k) => k.botKind && k.botKind !== "human").reduce((s, k) => s + k._count._all, 0);
  return {
    total,
    bots,
    unclassified: kinds.find((k) => k.botKind === null)?._count._all ?? 0,
    byKind: kinds.map((k) => ({ kind: k.botKind ?? "unclassified", count: k._count._all })).sort((a, b) => b.count - a.count),
    topReasons: reasons.map((x) => ({ reason: x.botReason ?? "", count: x._count._all })),
    flaggedIps: flagged,
  };
}

