    if (mods && mods.hits > 0) insights.push(`/mods/* pages took ${Math.round((mods.hits / totalHits) * 100)}% of all bot requests (${mods.googlebot.toLocaleString()} from verified Googlebot).`);
  }

  return {
    hasData: daily.length > 0,
    cursor: cursor ? { offset: cursor.offset.toString(), updatedAt: cursor.updatedAt } : null,
    rows,
    totals: { hits: totalHits, bytes: totalBytes, humanEstimate: null },
    series: { keys, lines: top.map((t) => ({ bot: t.bot, label: t.label, data: seriesBy.get(t.bot) ?? keys.map(() => 0) })) },
    sections: [...sectionMap.values()].sort((a, b) => b.hits - a.hits).slice(0, 15),
    errorUrls: errorUrls.map((e) => ({ bot: e.bot, path: e.path, status: e.lastStatus, hits: e.hits, lastSeen: e.lastSeen })),
    googlebot,
    insights,
  };
}

export type VisitBotStats = {
  total: number;
  bots: number;
  unclassified: number;
  byKind: { kind: string; count: number }[];
  topReasons: { reason: string; count: number }[];
  flaggedIps: number;
};

export async function visitBotStats(r: InsightsRange): Promise<VisitBotStats> {
  const where = { createdAt: { gte: r.from, lt: r.to } };
  const [total, kinds, reasons, flagged] = await Promise.all([
    db.visit.count({ where }),
    db.visit.groupBy({ by: ["botKind"], where, _count: { _all: true } }),
    db.visit.groupBy({ by: ["botReason"], where: { ...where, isBot: true }, _count: { _all: true }, orderBy: { _count: { botReason: "desc" } }, take: 12 }),
    db.botIpFlag.count({ where: { expiresAt: { gt: new Date() } } }),
  ]);
  const bots = kinds.filter((k) => k.botKind && k.botKind !== "human").reduce((s, k) => s + k._count._all, 0);
  return {
    total,
    bots,
    unclassified: kinds.find((k) => k.botKind === null)?._count._all ?? 0,
    byKind: kinds.map((k) => ({ kind: k.botKind ?? "unclassified", count: k._count._all })).sort((a, b) => b.count - a.count),
    topReasons: reasons.map((x) => ({ reason: x.botReason ?? "", count: x._count._all })),
    flaggedIps: flagged,
  };
}

