/**
 * The three "beyond scope" insights features implemented (see
 * docs/ADMIN-INSIGHTS-PROPOSALS.md for the ranking):
 *
 *  1. Low-capacity forecast alerts — per node, days until committed RAM hits
 *     capacity at the current growth rate (lib/insights/products.ts).
 *  2. Revenue / payment anomaly alerts — yesterday's earned revenue, cash-in,
 *     refunds and payment-failure emails vs a trailing 28-day baseline.
 *  3. Churn-risk list — paying customers showing concrete, explainable risk
 *     signals right now (auto-renew off near expiry, in dunning, gone quiet,
 *     unanswered ticket, stopped server). Computed live, never stored.
 *
 * (1) and (2) are evaluated by the worker (worker/insights.ts) and persisted as
 * de-duplicated InsightsAlert rows; nothing here sends email or Discord.
 */
import { db } from "@/lib/db";
import { REVENUE_WHERE, REVENUE_USER_WHERE } from "@/lib/admin-metrics";
import { REAL_CASH_IN_WHERE } from "@/lib/revenue";
import { CUSTOMER_WHERE, LIVE_STATUSES } from "./common";
import { capacityInsights } from "./products";
import { mrrNow } from "./revenue";
import { mean, zScore } from "./stats";

export type AlertCandidate = {
  kind: "capacity_forecast" | "revenue_anomaly";
  severity: "INFO" | "WARN" | "CRITICAL";
  dedupeKey: string;
  title: string;
  detail: string;
  metric: Record<string, unknown>;
};

export const CAPACITY_WARN_DAYS = 30;
export const CAPACITY_CRIT_DAYS = 14;

export async function capacityAlerts(): Promise<AlertCandidate[]> {
  const nodes = await capacityInsights();
  const out: AlertCandidate[] = [];
  for (const n of nodes) {
    if (!n.enabled || n.capacityRamMB <= 0) continue;
    const days = n.daysUntilFull.ok ? n.daysUntilFull.value : null;
    const pct = n.committedPct;
    let severity: AlertCandidate["severity"] | null = null;
    if (pct >= 0.95 || (days != null && days <= CAPACITY_CRIT_DAYS)) severity = "CRITICAL";
    else if (pct >= 0.85 || (days != null && days <= CAPACITY_WARN_DAYS)) severity = "WARN";
    if (!severity) continue;
    out.push({
      kind: "capacity_forecast",
      severity,
      dedupeKey: `capacity:${n.id}`,
      title: `${n.name}: ${days === 0 ? "RAM fully committed" : days != null ? `RAM full in ~${days} day(s)` : `${Math.round(pct * 100)}% RAM committed`}`,
      detail: `${(n.committedRamMB / 1024).toFixed(1)} / ${(n.capacityRamMB / 1024).toFixed(1)} GB committed (${Math.round(pct * 100)}%)${
        n.slopeMbPerDay.ok ? `, growing ${(n.slopeMbPerDay.value / 1024).toFixed(2)} GB/day (${n.slopeSource})` : ""
      }. Add capacity or stop provisioning to this node before it fills.`,
      metric: { nodeId: n.id, committedRamMB: n.committedRamMB, capacityRamMB: n.capacityRamMB, daysUntilFull: days },
    });
  }
  return out;
}

const DAY = 86_400_000;

async function dailySums(kind: "earned" | "cash" | "refund", from: Date, days: number): Promise<number[]> {
  const to = new Date(from.getTime() + days * DAY);
  const where =
    kind === "earned"
      ? { ...REVENUE_WHERE, createdAt: { gte: from, lt: to } }
      : kind === "cash"
        ? { ...REAL_CASH_IN_WHERE, user: REVENUE_USER_WHERE, createdAt: { gte: from, lt: to } }
        : { amountCents: { lt: 0 }, createdAt: { gte: from, lt: to }, OR: [{ description: { startsWith: "Refund" } }, { description: { startsWith: "Write-off" } }] };
  const rows = await db.walletTransaction.findMany({ where, select: { amountCents: true, createdAt: true }, take: 200_000 });
  const out = Array.from({ length: days }, () => 0);
  for (const r of rows) {
    const i = Math.floor((r.createdAt.getTime() - from.getTime()) / DAY);
    if (i >= 0 && i < days) out[i] += Math.abs(r.amountCents);
  }
  return out;
}

/** Evaluate YESTERDAY (a complete UTC day) against the 28 days before it. */
export async function revenueAlerts(now: Date = new Date()): Promise<AlertCandidate[]> {
  const today = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()));
  const yStart = new Date(today.getTime() - DAY);
  const bStart = new Date(yStart.getTime() - 28 * DAY);
  const day = yStart.toISOString().slice(0, 10);
  const out: AlertCandidate[] = [];

  const [earned, cash, refunds] = await Promise.all([dailySums("earned", bStart, 29), dailySums("cash", bStart, 29), dailySums("refund", bStart, 29)]);
  const check = (label: string, series: number[], key: string) => {
    const base = series.slice(0, 28);
    const y = series[28];
    const m = mean(base) ?? 0;
    // Only meaningful once there's a real baseline: >= $5/day average and >= 10 non-zero days.
    if (m < 500 || base.filter((v) => v > 0).length < 10) return;
    const z = zScore(y, base);
    if (z != null && z <= -2.5) {
      out.push({
        kind: "revenue_anomaly",
        severity: y === 0 ? "CRITICAL" : "WARN",
        dedupeKey: `${key}:${day}`,
        title: `${label} on ${day} was unusually low`,
        detail: `$${(y / 100).toFixed(2)} vs a 28-day average of $${(m / 100).toFixed(2)}/day (z = ${z.toFixed(1)}). Check the payment provider, the renewal sweep and checkout for errors.`,
        metric: { day, value: y, baselineMean: m, z },
      });
    }
  };
  check("Earned revenue", earned, "rev_drop");
  check("Cash collected", cash, "cash_drop");

  // Refund spike: > 3x baseline mean and > $50.
  const rBase = mean(refunds.slice(0, 28)) ?? 0;
  const rY = refunds[28];
  if (rY > 5000 && rY > 3 * rBase) {
    out.push({
      kind: "revenue_anomaly",
      severity: "WARN",
      dedupeKey: `refund_spike:${day}`,
      title: `Refunds spiked on ${day}`,
      detail: `$${(rY / 100).toFixed(2)} refunded vs a 28-day average of $${(rBase / 100).toFixed(2)}/day.`,
      metric: { day, value: rY, baselineMean: rBase },
    });
  }

  // Payment-failure emails spike: >= 5 and > 3x baseline.
  const fails = await db.emailLog.findMany({
    where: { createdAt: { gte: bStart, lt: today }, template: { in: ["payment_failed", "payment_retry_failed", "payment_final_notice", "paypal_payment_failed"] } },
    select: { createdAt: true },
  });
  const fSeries = Array.from({ length: 29 }, () => 0);
  for (const f of fails) {
    const i = Math.floor((f.createdAt.getTime() - bStart.getTime()) / DAY);
    if (i >= 0 && i < 29) fSeries[i]++;
  }
  const fBase = mean(fSeries.slice(0, 28)) ?? 0;
  if (fSeries[28] >= 5 && fSeries[28] > 3 * Math.max(fBase, 0.5)) {
    out.push({
      kind: "revenue_anomaly",
      severity: "WARN",
      dedupeKey: `payfail_spike:${day}`,
      title: `Payment failures spiked on ${day}`,
      detail: `${fSeries[28]} payment-failure emails vs a 28-day average of ${fBase.toFixed(1)}/day — check the card processor before more renewals fail.`,
      metric: { day, value: fSeries[28], baselineMean: fBase },
    });
  }
  return out;
}

// ---------------------------------------------------------------------------
// Churn-risk list
// ---------------------------------------------------------------------------

export type ChurnRisk = {
  userId: string;
  email: string;
  name: string;
  mrrCents: number;
  score: number;
  reasons: string[];
};

export async function churnRiskList(limit = 30): Promise<ChurnRisk[]> {
  const now = Date.now();
  const mrr = await mrrNow();
  const ids = [...mrr.byUser.keys()];
  if (!ids.length) return [];
  const [users, servers, lastVisit, tickets, failMail] = await Promise.all([
    db.user.findMany({ where: { id: { in: ids } }, select: { id: true, email: true, name: true, autoRechargeEnabled: true, balanceCents: true } }),
    db.server.findMany({
      where: { userId: { in: ids }, isFree: false, status: { in: [...LIVE_STATUSES] } },
      select: { userId: true, status: true, autoRenew: true, expiresAt: true, dunningStage: true, updatedAt: true, label: true, name: true },
    }),
    db.visit.groupBy({ by: ["userId"], where: { userId: { in: ids }, isBot: false }, _max: { createdAt: true } }),
    db.ticket.findMany({ where: { userId: { in: ids }, status: { in: ["OPEN", "CUSTOMER_REPLY"] } }, select: { userId: true, updatedAt: true } }),
    db.emailLog.groupBy({
      by: ["userId"],
      where: { userId: { in: ids }, createdAt: { gte: new Date(now - 30 * DAY) }, template: { in: ["payment_failed", "payment_retry_failed", "payment_final_notice", "paypal_payment_failed"] } },
      _count: { _all: true },
    }),
  ]);
  const seen = new Map(lastVisit.map((v) => [v.userId as string, v._max.createdAt]));
  const fails = new Map(failMail.map((f) => [f.userId as string, f._count._all]));
  const out: ChurnRisk[] = [];
  for (const u of users) {
    const mine = servers.filter((s) => s.userId === u.id);
    const reasons: string[] = [];
    let score = 0;
    const expiringNoRenew = mine.filter((s) => !s.autoRenew && s.expiresAt && s.expiresAt.getTime() - now < 14 * DAY);
    if (expiringNoRenew.length) {
      score += 40;
      reasons.push(`auto-renew OFF on ${expiringNoRenew.length} server(s) expiring within 14 days`);
    }
    const dunning = mine.filter((s) => s.dunningStage > 0);
    if (dunning.length) {
      score += 30;
      reasons.push(`in dunning (stage ${Math.max(...dunning.map((s) => s.dunningStage))})`);
    }
    const f = fails.get(u.id) ?? 0;
    if (f > 0) {
      score += 15;
      reasons.push(`${f} payment-failure email(s) in 30 days`);
    }
    const stopped = mine.filter((s) => s.status === "STOPPED" && now - s.updatedAt.getTime() > 14 * DAY);
    if (stopped.length && stopped.length === mine.length) {
      score += 20;
      reasons.push("every paid server stopped for 14+ days");
    }
    const last = seen.get(u.id);
    if (!last || now - last.getTime() > 30 * DAY) {
      score += 10;
      reasons.push(last ? `no portal visit in ${Math.floor((now - last.getTime()) / DAY)} days` : "never seen in the portal");
    }
    const waiting = tickets.filter((t) => t.userId === u.id && now - t.updatedAt.getTime() > DAY);
    if (waiting.length) {
      score += 15;
      reasons.push(`${waiting.length} ticket(s) awaiting staff reply > 24h`);
    }
    if (score >= 20) out.push({ userId: u.id, email: u.email, name: u.name, mrrCents: mrr.byUser.get(u.id) ?? 0, score, reasons });
  }
  return out.sort((a, b) => b.score * 1e6 + b.mrrCents - (a.score * 1e6 + a.mrrCents)).slice(0, limit);
}

/** Customers matching (for the risk list's own sanity — keeps CUSTOMER_WHERE in one import). */
export const CHURN_RISK_SCOPE = CUSTOMER_WHERE;

