import { db } from "../lib/db";
import { mrrNow } from "../lib/insights/revenue";
import { capacityInsights } from "../lib/insights/products";
import { capacityAlerts, revenueAlerts, type AlertCandidate } from "../lib/insights/alerts";

function utcToday(): Date {
  const n = new Date();
  return new Date(Date.UTC(n.getUTCFullYear(), n.getUTCMonth(), n.getUTCDate()));
}

async function put(date: Date, metric: string, scopeId: string, value: number) {
  await db.insightsSnapshot.upsert({
    where: { date_metric_scopeId: { date, metric, scopeId } },
    create: { date, metric, scopeId, value },
    update: { value },
  });
}

export async function insightsSnapshotSweep(): Promise<void> {
  const date = utcToday();
  const m = await mrrNow();
  await put(date, "mrr_cents", "", m.mrrCents);
  await put(date, "paying_customers", "", m.payingCustomers);
  await put(date, "billable_servers", "", m.billableServers);
  for (const n of await capacityInsights()) {
    await put(date, "node_committed_ram_mb", n.id, n.committedRamMB);
    if (n.usedRamMB != null) await put(date, "node_used_ram_mb", n.id, n.usedRamMB);
  }
}

async function upsertAlert(a: AlertCandidate) {
  const existing = await db.insightsAlert.findUnique({ where: { dedupeKey: a.dedupeKey } });
  if (existing && existing.status === "DISMISSED") return;
  await db.insightsAlert.upsert({
    where: { dedupeKey: a.dedupeKey },
    create: { kind: a.kind, severity: a.severity, title: a.title, detail: a.detail, metric: a.metric as object, dedupeKey: a.dedupeKey },
    update: { severity: a.severity, title: a.title, detail: a.detail, metric: a.metric as object, status: "OPEN", resolvedAt: null },
  });
}

export async function insightsAlertSweep(): Promise<{ open: number }> {
  const cap = await capacityAlerts();
  const rev = await revenueAlerts();
  for (const a of [...cap, ...rev]) await upsertAlert(a);
  // Auto-resolve capacity alerts whose node no longer qualifies.
  const live = new Set(cap.map((a) => a.dedupeKey));
  await db.insightsAlert.updateMany({
    where: { kind: "capacity_forecast", status: "OPEN", dedupeKey: { notIn: [...live] } },
    data: { status: "RESOLVED", resolvedAt: new Date() },
  });
  return { open: await db.insightsAlert.count({ where: { status: "OPEN" } }) };
}
