import { test } from "node:test";
import assert from "node:assert/strict";
import { isGenuineSeverityChange } from "../lib/capacity-severity.ts";

/**
 * Guards the fix for the live 2026-09-25 incident: "primary" RAM sat within
 * ~1% of critPct and flapped WARN/CRITICAL every 30-90 minutes all day, each
 * flip bypassing NODE_CAP_COOLDOWN_HOURS entirely because worker/monitor.ts
 * treated ANY severity change as "always notify" — sending 30-80
 * "Node capacity" emails/day to reports@nxeon.cloud.
 */

const CRIT_PCT = 90;
const MARGIN = 5; // NODE_CAP_RESOLVE_MARGIN default

test("escalating to CRITICAL is always a genuine change, regardless of pct", () => {
  assert.equal(isGenuineSeverityChange("WARN", "CRITICAL", 90, CRIT_PCT, MARGIN), true);
  assert.equal(isGenuineSeverityChange("WARN", "CRITICAL", 99, CRIT_PCT, MARGIN), true);
  // Even a pct that (oddly) reports CRITICAL right at the boundary — the
  // decision must never gate escalation on the margin.

