  assert.equal(classifyHit({ ua: HUMANS[0], ip: "54.157.84.74", now: NOW }).botKind, "human");
  // …but datacenter + a non-browser UA crosses the threshold.
  assert.equal(classifyHit({ ua: "SomethingWeird/1.0", ip: "54.157.84.74", now: NOW }).botKind, "suspected-bot");
});

test("cidr helpers", () => {
  const r = parseCidr("10.0.0.0/8")!;
  assert.equal(r.start, parseIp("10.0.0.0")!.n);
  assert.equal(r.end, parseIp("10.255.255.255")!.n);
  assert.ok(ipInCidrs("2001:db8::1", ["2001:db8::/32"]));
  assert.ok(!ipInCidrs("2001:db9::1", ["2001:db8::/32"]));
  assert.equal(parseIp("::ffff:1.2.3.4")!.v6, false);
  assert.deepEqual(mergeRanges([[5n, 9n], [1n, 3n], [4n, 4n], [20n, 30n]]), [[1n, 9n], [20n, 30n]]);
});

