  assert.equal(foreign.ok, false);
  const mismatch = await fcrdns("1.2.3.4", ["googlebot.com"], { reverse: async () => ["fake.googlebot.com"], lookupAll: async () => ["9.9.9.9"] });
  assert.equal(mismatch.ok, false);
