"use client";

import { useTransition } from "react";
import { useRouter } from "next/navigation";
import { setIncludeBots } from "@/lib/actions-insights";

/**
 * Date-range + compare controls and the "include bots" toggle for
 * /admin/insights. Range state lives in the URL (?preset= / ?from=&to=) so a
 * view is shareable and the server renders it directly — no client fetch.
 */
export function RangeControls({
  tab,
  preset,
  fromStr,
  toStr,
  presets,
}: {
  tab: string;
  preset: string | null;
  fromStr: string;
  toStr: string;
  presets: { key: string; label: string }[];
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      <div className="flex flex-wrap gap-1" role="group" aria-label="Date range presets">
        {presets.map((p) => (
          <a
            key={p.key}
            href={`/admin/insights?tab=${tab}&preset=${p.key}`}
            className={`rounded-lg border px-2.5 py-1 text-xs font-medium transition ${
              preset === p.key ? "border-brand-500/60 bg-brand-500/15 text-brand-200" : "border-white/10 text-slate-400 hover:border-white/20 hover:text-slate-200"
            }`}
          >
            {p.label}
          </a>
        ))}
      </div>
      <form action="/admin/insights" method="get" className="flex flex-wrap items-center gap-1.5 text-xs">
        <input type="hidden" name="tab" value={tab} />
        <label className="sr-only" htmlFor="ins-from">
          From
        </label>
        <input id="ins-from" type="date" name="from" defaultValue={fromStr} className="input !h-8 !w-auto !px-2 !py-1 text-xs" />
        <span className="text-slate-500">→</span>
        <label className="sr-only" htmlFor="ins-to">
          To
        </label>
        <input id="ins-to" type="date" name="to" defaultValue={toStr} className="input !h-8 !w-auto !px-2 !py-1 text-xs" />
        <button type="submit" className="btn-secondary !h-8 !px-3 !py-1 text-xs">
          Apply
        </button>
      </form>
    </div>
  );
}

export function BotToggle({ on }: { on: boolean }) {
  const router = useRouter();
  const [pending, start] = useTransition();
  return (
    <button
      type="button"
      disabled={pending}
      onClick={() =>
        start(async () => {
          await setIncludeBots(!on);
          router.refresh();
        })
      }
      aria-pressed={on}
      title="Bots are excluded from every visitor number by default. Turn this on to see raw traffic (expires after 12h)."
      className={`inline-flex items-center gap-2 rounded-lg border px-2.5 py-1 text-xs font-medium transition ${
        on ? "border-amber-500/50 bg-amber-500/10 text-amber-300" : "border-white/10 text-slate-400 hover:border-white/20 hover:text-slate-200"
      }`}
    >
      <span className={`h-2 w-2 rounded-full ${on ? "bg-amber-400" : "bg-slate-600"}`} />
      {pending ? "Updating…" : on ? "Including bots" : "Bots excluded"}
    </button>
  );
}

export function DismissAlert({ id, action }: { id: string; action: (id: string) => Promise<unknown> }) {
  const router = useRouter();
  const [pending, start] = useTransition();
  return (
    <button
      type="button"
      disabled={pending}
      onClick={() =>
        start(async () => {
          if (!confirm("Dismiss this alert? It won't re-open for the same condition.")) return;
          await action(id);
          router.refresh();
        })
      }
      className="text-xs text-slate-500 underline-offset-2 hover:text-slate-300 hover:underline"
    >
      {pending ? "…" : "Dismiss"}
    </button>
  );
}

