import { CapacityTab } from "./tabs/capacity";
import { OperationsTab } from "./tabs/operations";
import { GrowthTab } from "./tabs/growth";
import { PaymentsTab } from "./tabs/payments";
import { CrawlersTab } from "./tabs/crawlers";

export const dynamic = "force-dynamic";

export const TABS = [
  { key: "overview", label: "Overview" },
  { key: "revenue", label: "Revenue" },
  { key: "customers", label: "Churn & LTV" },
  { key: "funnel", label: "Funnel" },
  { key: "products", label: "Products & margin" },
  { key: "capacity", label: "Capacity" },
  { key: "operations", label: "Jobs & support" },
  { key: "growth", label: "Partners & email" },
  { key: "payments", label: "Payments & refunds" },
  { key: "crawlers", label: "Bots & crawlers" },
] as const;
type TabKey = (typeof TABS)[number]["key"];

/**
 * /admin/insights — the owner's business analytics, every number computed
 * from the database (lib/insights/*). Date range + compare-to-previous-period
 * via the URL; CSV export per tab (./export/route.ts). Visitor numbers are
 * bot-free unless the admin flips the include-bots toggle.
 */
export default async function InsightsPage({ searchParams }: { searchParams: Promise<{ tab?: string; from?: string; to?: string; preset?: string }> }) {
  await requireArea("analytics");
  const sp = await searchParams;
  const tab: TabKey = (TABS.some((t) => t.key === sp.tab) ? sp.tab : "overview") as TabKey;
  const range = parseRange(sp);
  const bots = await includeBots();
  const qs = range.preset ? `preset=${range.preset}` : `from=${range.fromStr}&to=${range.toStr}`;

  return (
    <div className="space-y-6">
      <PageHeader
        title="Insights"
        sub={`Business analytics from live data · ${range.label} (${range.fromStr} → ${range.toStr}, UTC) compared with the ${range.days} days before.`}
      >
        <BotToggle on={bots} />
        <a href={`/admin/insights/export?tab=${tab}&${qs}`} className="btn-secondary !h-8 !px-3 !py-1 text-xs" download>
          Export CSV
        </a>
      </PageHeader>

      <div className="flex flex-col gap-3">
        <RangeControls tab={tab} preset={range.preset} fromStr={range.fromStr} toStr={range.toStr} presets={PRESETS} />
