import Link from "next/link";
import { db } from "@/lib/db";
import { Badge } from "@/components/ui/primitives";
import { revenueInsights, churnInsights } from "@/lib/insights/revenue";
import { funnelInsights } from "@/lib/insights/funnel";
import { capacityInsights } from "@/lib/insights/products";
import { churnRiskList } from "@/lib/insights/alerts";
import { visitBotStats } from "@/lib/insights/crawlers";
import type { InsightsRange } from "@/lib/insights/range";
import { fmtCents, fmtPct } from "@/lib/insights/stats";
import { Grid, Kpi, Section, Table } from "../_ui";
import { DismissAlert } from "../Controls";

export async function OverviewTab({ range }: { range: InsightsRange }) {
  const [rev, funnel, nodes, risk, bots, alerts] = await Promise.all([
    revenueInsights(range),
    funnelInsights(range),
    capacityInsights(),
    churnRiskList(5),
    visitBotStats(range),
    db.insightsAlert.findMany({ where: { status: "OPEN" }, orderBy: [{ severity: "asc" }, { createdAt: "desc" }], take: 10 }),
  ]);
  const churn = await churnInsights(range, rev);
  const f = funnel.cur;
  const conv = f.signups > 0 ? f.paid / f.signups : null;
  const convPrev = funnel.prev.signups > 0 ? funnel.prev.paid / funnel.prev.signups : null;
  const tightest = nodes
    .filter((n) => n.enabled && n.daysUntilFull.ok && n.daysUntilFull.value != null)
    .sort((a, b) => (a.daysUntilFull.ok && b.daysUntilFull.ok ? (a.daysUntilFull.value ?? 1e9) - (b.daysUntilFull.value ?? 1e9) : 0))[0];

  return (
    <div className="space-y-6">
      {alerts.length > 0 && (
        <Section title="Open alerts" sub="Raised hourly by the worker from capacity forecasts and revenue/payment anomalies. Nothing is emailed.">
          <ul className="space-y-2">
            {alerts.map((a) => (
              <li key={a.id} className="flex flex-wrap items-start justify-between gap-2 rounded-lg border border-white/[0.06] bg-white/[0.02] px-3 py-2">
                <div className="min-w-0">
                  <div className="flex items-center gap-2">
                    <Badge tone={a.severity === "CRITICAL" ? "red" : a.severity === "WARN" ? "amber" : "slate"}>{a.severity.toLowerCase()}</Badge>
                    <span className="font-medium">{a.title}</span>
                  </div>
                  <p className="mt-1 text-xs text-slate-400">{a.detail}</p>
                </div>
                <DismissAlert id={a.id} />
              </li>
            ))}
          </ul>
        </Section>
      )}

      <Grid>
        <Kpi label="MRR (now)" value={fmtCents(rev.mrrCents)} note={`ARR ${fmtCents(rev.arrCents)}`} />
        <Kpi label="Paying customers" value={String(rev.payingCustomers)} note={rev.arpuCents != null ? `ARPU ${fmtCents(rev.arpuCents)}/mo` : "no paying customers"} />
        <Kpi label="Earned revenue" value={fmtCents(rev.earned)} cur={rev.earned} prev={rev.earnedPrev} />
        <Kpi label="Cash collected" value={fmtCents(rev.cashIn)} cur={rev.cashIn} prev={rev.cashInPrev} />
        <Kpi label="Signups" value={String(f.signups)} cur={f.signups} prev={funnel.prev.signups} />
        <Kpi label="Signup → paid" value={fmtPct(conv, 1)} cur={conv ?? undefined} prev={convPrev} note={`${f.paid} of ${f.signups} paid`} />
        <Kpi
          label="Monthly customer churn"
          value={churn.monthlyChurn.ok ? fmtPct(churn.monthlyChurn.value, 1) : "—"}
          note={churn.monthlyChurn.ok ? `${churn.churned} of ${churn.startCustomers} churned in range` : churn.monthlyChurn.reason}
