          value={tightest && tightest.daysUntilFull.ok ? (tightest.daysUntilFull.value === 0 ? "Full" : `${tightest.daysUntilFull.value}d`) : "No pressure"}
          note={tightest ? `${tightest.name} · ${fmtPct(tightest.committedPct)} RAM committed` : "no node is on a path to full RAM"}
        />
      </Grid>

      <div className="grid gap-6 lg:grid-cols-2">
