import Link from "next/link";
import { AreaChart } from "@/components/ui/charts";
import { revenueInsights } from "@/lib/insights/revenue";
import type { InsightsRange } from "@/lib/insights/range";
import { fmtCents, fmtPct } from "@/lib/insights/stats";
import { Grid, Kpi, MaybeValue, Section, Table, axisLabels } from "../_ui";

export async function RevenueTab({ range }: { range: InsightsRange }) {
  const r = await revenueInsights(range);
  const net = r.cashIn - r.refunds.cents;
  const netPrev = r.cashInPrev - r.refundsPrev.cents;
  return (
    <div className="space-y-6">
      <Grid>
        <Kpi label="MRR (now)" value={fmtCents(r.mrrCents)} note={`${r.billableServers} billable servers`} />
        <Kpi label="ARR run-rate" value={fmtCents(r.arrCents)} note="MRR × 12" />
        <Kpi label="ARPU" value={r.arpuCents != null ? fmtCents(r.arpuCents) : "—"} note={`${r.payingCustomers} paying customers`} />
        <Kpi label="Top-5 concentration" value={fmtPct(r.concentrationTop5)} note="share of MRR from the 5 biggest customers" />
        <Kpi label="Earned revenue" value={fmtCents(r.earned)} cur={r.earned} prev={r.earnedPrev} />
        <Kpi label="Cash collected" value={fmtCents(r.cashIn)} cur={r.cashIn} prev={r.cashInPrev} />
        <Kpi label="Refunds" value={fmtCents(r.refunds.cents)} cur={r.refunds.cents} prev={r.refundsPrev.cents} higherIsBetter={false} note={`${r.refunds.count} refund row(s)`} />
        <Kpi label="Net cash" value={fmtCents(net)} cur={net} prev={netPrev} />
      </Grid>

      <Section title="Earned revenue vs cash collected" sub="Earned = wallet debits for service (the console's REVENUE_WHERE). Cash = real card/PayPal/crypto payments. Customers pre-pay into the wallet, so the two lines lead/lag each other.">
        <AreaChart
          id="ins-rev"
          series={[
            { name: "Earned", data: r.series.earned.map((c) => c / 100), color: "#8a70fb" },
            { name: "Cash", data: r.series.cashIn.map((c) => c / 100), color: "#22d3ee" },
          ]}
          xLabels={axisLabels(r.series.keys)}
          yLabel={(v) => `$${v >= 1000 ? `${(v / 1000).toFixed(1)}k` : v.toFixed(0)}`}
        />
        <div className="mt-2 flex gap-4 text-xs text-slate-400">
          <span><span className="mr-1 inline-block h-2 w-2 rounded-full bg-[#8a70fb]" />Earned</span>
          <span><span className="mr-1 inline-block h-2 w-2 rounded-full bg-[#22d3ee]" />Cash</span>
        </div>
      </Section>

      <Section title="MRR history" sub="From the worker's daily snapshot. MRR is a point-in-time figure, so history only exists from the first snapshot onward.">
        <MaybeValue
          m={r.mrrHistory}
          render={(pts) => (
            <AreaChart id="ins-mrr" series={[{ name: "MRR", data: pts.map((p) => p.value / 100), color: "#3b6be8" }]} xLabels={axisLabels(pts.map((p) => p.key))} yLabel={(v) => `$${v.toFixed(0)}`} />
          )}
        />
      </Section>

      <Section title="Biggest customers by MRR" sub="Revenue concentration risk: losing one of these is a visible dent.">
        <Table
          head={["Customer", "MRR", "Share"]}
          rows={r.topCustomers.map((c) => [
            <Link key="e" href={`/admin/users/${c.userId}`} className="hover:underline">
              {c.email}
            </Link>,
            fmtCents(c.mrrCents),
            fmtPct(c.share, 1),
          ])}
          empty="No paying customers."
        />
      </Section>
    </div>
  );
}

