import Link from "next/link";
import { mrrNow, churnInsights } from "@/lib/insights/revenue";
import { churnRiskList } from "@/lib/insights/alerts";
import type { InsightsRange } from "@/lib/insights/range";
import { fmtCents, fmtPct } from "@/lib/insights/stats";
import { Grid, Kpi, MaybeValue, Section, Table } from "../_ui";

function cellColor(v: number | null): string {
  if (v == null) return "transparent";
  // violet ramp, opacity by retention
  return `rgba(123, 63, 239, ${(0.12 + v * 0.7).toFixed(2)})`;
}

export async function CustomersTab({ range }: { range: InsightsRange }) {
  const mrr = await mrrNow();
  const [c, risk] = await Promise.all([churnInsights(range, mrr), churnRiskList(30)]);
  return (
    <div className="space-y-6">
      <Grid>
        <Kpi
          label="Customer churn (period)"
          value={c.churnRate.ok ? fmtPct(c.churnRate.value, 1) : "—"}
          cur={c.churnRate.ok ? c.churnRate.value : undefined}
          prev={c.churnRatePrev.ok ? c.churnRatePrev.value : null}
          higherIsBetter={false}
          note={c.churnRate.ok ? undefined : c.churnRate.reason}
        />
        <Kpi label="Monthly churn (normalised)" value={c.monthlyChurn.ok ? fmtPct(c.monthlyChurn.value, 1) : "—"} note={`${c.churned} churned · ${c.newPaying} new paying`} />
        <Kpi
          label="Realised LTV (mean)"
          value={c.ltvRealized.ok ? fmtCents(c.ltvRealized.value.mean) : "—"}
          note={c.ltvRealized.ok ? `median ${fmtCents(c.ltvRealized.value.median)} · ${c.ltvRealized.value.customers} customers` : c.ltvRealized.reason}
        />
        <Kpi label="Predicted LTV" value={c.ltvPredicted.ok ? fmtCents(c.ltvPredicted.value) : "—"} note={c.ltvPredicted.ok ? "ARPU ÷ monthly churn (simple model)" : c.ltvPredicted.reason} />
      </Grid>

      <Section
        title="Churn-risk list"
        sub="Paying customers with concrete signals: auto-renew off near expiry, dunning, payment failures, every server stopped 14d+, no portal visit in 30d, ticket waiting on us > 24h. Scored; nothing automated happens."
      >
        <Table
          head={["Customer", "MRR", "Score", "Signals"]}
          rows={risk.map((r) => [
            <Link key="u" className="hover:underline" href={`/admin/users/${r.userId}`}>
              {r.email}
            </Link>,
            fmtCents(r.mrrCents),
            String(r.score),
            <span key="s" className="whitespace-normal text-xs text-slate-400">
              {r.reasons.join(" · ")}
            </span>,
          ])}
          empty="No paying customer shows a risk signal right now."
        />
      </Section>

      <Section title="Paying-customer cohorts" sub="Customers grouped by the month of their first paid server · share still paying at the end of each following month (deleted servers from ServerArchive included).">
        <MaybeValue
          m={c.cohorts}
          render={(rows) => (
            <div className="-mx-5 overflow-x-auto px-5">
              <table className="min-w-full text-xs tabular-nums">
                <thead>
                  <tr className="text-slate-500">
                    <th className="py-1 pr-3 text-left font-medium">Cohort</th>
                    <th className="py-1 pr-3 text-right font-medium">Size</th>
                    {Array.from({ length: 12 }, (_, k) => (
                      <th key={k} className="px-1 py-1 text-center font-medium">
                        M{k}
                      </th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {rows.map((r) => (
                    <tr key={r.month}>
                      <td className="py-1 pr-3 whitespace-nowrap">{r.month}</td>
                      <td className="py-1 pr-3 text-right">{r.size}</td>
                      {r.retained.map((v, k) => (
                        <td key={k} className="px-0.5 py-0.5">
                          <div className="rounded px-1 py-1 text-center" style={{ background: cellColor(v) }} title={v == null ? "not reached yet" : `${Math.round(v * 100)}%`}>
                            {v == null ? "" : `${Math.round(v * 100)}%`}
                          </div>
                        </td>
                      ))}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        />
      </Section>

      <Section title="Churned in this period" sub="Paid at the period start, no live paid server at the end.">
        <Table
          head={["Customer", "Last paid server ended"]}
          rows={c.churnedList.map((u) => [
            <Link key="u" className="hover:underline" href={`/admin/users/${u.userId}`}>
              {u.email}
            </Link>,
            u.since ? u.since.toISOString().slice(0, 10) : "—",
          ])}
          empty="Nobody churned in this period."
        />
      </Section>
    </div>
  );
}

