import { MeterBar } from "@/components/ui/charts";
import { funnelInsights, type Breakdown } from "@/lib/insights/funnel";
import type { InsightsRange } from "@/lib/insights/range";
import { fmtDuration, fmtPct } from "@/lib/insights/stats";
import { Grid, Kpi, MaybeValue, Section, Table } from "../_ui";

function rows(b: Breakdown[]) {
  return b.slice(0, 20).map((x) => [x.label, String(x.signups), `${x.deployed} (${fmtPct(x.signups ? x.deployed / x.signups : null)})`, `${x.paid} (${fmtPct(x.signups ? x.paid / x.signups : null)})`]);
}

export async function FunnelTab({ range }: { range: InsightsRange }) {
  const f = await funnelInsights(range);
  const steps = [
    { label: "Visitors (bot-free)", cur: f.cur.visitors, prev: f.prev.visitors },
    { label: "Signups", cur: f.cur.signups, prev: f.prev.signups },
    { label: "Deployed a server", cur: f.cur.deployed, prev: f.prev.deployed },
    { label: "Paid", cur: f.cur.paid, prev: f.prev.paid },
  ];
  const top = Math.max(f.cur.visitors, 1);
  return (
    <div className="space-y-6">
      <Section title="Visitor → signup → deploy → paid" sub={`Signups are counted for accounts created in the range; deploy/paid are what those accounts went on to do (by now). ${f.botVisitorsExcluded.toLocaleString()} bot visitors removed from the top of the funnel.`}>
        <div className="space-y-4">
          {steps.map((s, i) => {
            const prevStep = i > 0 ? steps[i - 1].cur : null;
            return (
              <div key={s.label}>
                <div className="mb-1 flex flex-wrap items-baseline justify-between gap-2 text-sm">
                  <span className="font-medium">{s.label}</span>
                  <span className="tabular-nums">
                    <span className="text-lg font-bold">{s.cur.toLocaleString()}</span>
                    {prevStep != null && <span className="ml-2 text-xs text-slate-400">{fmtPct(prevStep ? s.cur / prevStep : null, 1)} of previous step</span>}
                    <span className="ml-2 text-xs text-slate-500">prev period {s.prev.toLocaleString()}</span>
                  </span>
                </div>
                <MeterBar value={s.cur} max={i === 0 ? top : Math.max(steps[1].cur, 1)} color={i === 3 ? "#22d3ee" : "#8a70fb"} />
              </div>
            );
          })}
        </div>
      </Section>

      <Grid cols={3}>
        <Section title="Time to first deploy" sub="Signup → first server (or free MC server).">
          <MaybeValue m={f.ttfdMs} render={(v) => <p className="text-sm"><span className="text-2xl font-bold">{fmtDuration(v.p50)}</span> <span className="text-slate-400">median · p90 {fmtDuration(v.p90)} · n={v.n}</span></p>} />
        </Section>
        <Section title="Time to first payment" sub="Signup → first real payment or earned charge.">
          <MaybeValue m={f.ttfpMs} render={(v) => <p className="text-sm"><span className="text-2xl font-bold">{fmtDuration(v.p50)}</span> <span className="text-slate-400">median · p90 {fmtDuration(v.p90)} · n={v.n}</span></p>} />
        </Section>
        <Section title="Free Minecraft → paid" sub="Free MC servers created in range whose owner later paid for anything.">
          <p className="text-sm">
            <span className="text-2xl font-bold">{fmtPct(f.freeMc.created ? f.freeMc.upgraded / f.freeMc.created : null, 1)}</span>
            <span className="ml-2 text-slate-400">
              {f.freeMc.upgraded} of {f.freeMc.created}
              {f.freeMc.medianDaysToUpgrade != null && ` · median ${f.freeMc.medianDaysToUpgrade.toFixed(1)}d to upgrade`}
            </span>
          </p>
          <p className="mt-1 text-xs text-slate-500">All time: {f.freeMc.allTimeUpgraded} of {f.freeMc.allTimeCreated} free-MC owners have paid.</p>
        </Section>
      </Grid>

      <div className="grid gap-6 xl:grid-cols-2">
        <Section title="Conversion by acquisition source" sub="Survey answer first, then real utm/gclid first-touch (lib/user-attribution.ts). Unknown is genuinely unknown.">
          <Table head={["Source", "Signups", "Deployed", "Paid"]} rows={rows(f.bySource)} />
        </Section>
        <Section title="Conversion by partner" sub="Accounts attached to a creator/referral partner.">
          <Table head={["Partner", "Signups", "Deployed", "Paid"]} rows={rows(f.byPartner)} />
        </Section>
        <Section title="Conversion by country" sub="Billing country, else the account's latest geocoded (bot-free) visit.">
          <Table head={["Country", "Signups", "Deployed", "Paid"]} rows={rows(f.byCountry)} />
        </Section>
      </div>
    </div>
  );
}

