import { productInsights } from "@/lib/insights/products";
import type { InsightsRange } from "@/lib/insights/range";
import { fmtCents, fmtPct } from "@/lib/insights/stats";
import { Bars, Grid, Kpi, Section, Table } from "../_ui";

export async function ProductsTab({ range }: { range: InsightsRange }) {
  const p = await productInsights(range);
  const games = p.rows.filter((r) => r.kind === "game");
  const vps = p.rows.filter((r) => r.kind === "vps");
  const margin = p.totalMrrCents - p.totalCostCents;
  return (
    <div className="space-y-6">
      <Grid>
        <Kpi label="MRR across products" value={fmtCents(p.totalMrrCents)} />
        <Kpi label="Allocated node cost" value={fmtCents(p.totalCostCents)} note={p.nodesMissingCost.length ? `cost missing for ${p.nodesMissingCost.join(", ")}` : "every enabled node has a cost"} />
        <Kpi label="Gross margin" value={fmtCents(margin)} note={p.totalMrrCents ? fmtPct(margin / p.totalMrrCents) : undefined} />
        <Kpi label="New paid orders" value={String(p.rows.reduce((s, r) => s + r.newInRange, 0))} cur={p.rows.reduce((s, r) => s + r.newInRange, 0)} prev={p.rows.reduce((s, r) => s + r.newPrev, 0)} />
      </Grid>

      {p.nodesMissingCost.length > 0 && (
        <p className="rounded-lg border border-amber-500/30 bg-amber-500/[0.06] px-3 py-2 text-xs text-amber-200">
          No monthly cost recorded for {p.nodesMissingCost.join(", ")} (Admin → Nodes → monthly cost). Products on those nodes show "cost incomplete" instead of a margin — never a fake 100%.
        </p>
      )}

      <div className="grid gap-6 xl:grid-cols-2">
        <Section title="Game popularity — new paid orders" sub="Paid game servers created in the range.">
          <Bars rows={games.filter((g) => g.newInRange > 0).map((g) => ({ label: g.label, value: g.newInRange, hint: `prev ${g.newPrev}` }))} />
        </Section>
        <Section title="VPS plan popularity — new paid orders" sub="Paid VPS servers created in the range.">
          <Bars rows={vps.filter((g) => g.newInRange > 0).map((g) => ({ label: g.label, value: g.newInRange, hint: `prev ${g.newPrev}` }))} color="#22d3ee" />
        </Section>
      </div>

      <Section title="Margin by product" sub="Node cost allocated by committed RAM share (RAM is the binding resource). Live servers right now; MRR uses the billing engine's own renewal formula.">
        <Table
          head={["Product", "Active", "Paid / free", "MRR", "RAM", "Cost", "Margin", "Margin %"]}
          rows={p.rows.map((r) => [
            `${r.kind === "game" ? "Game · " : "VPS · "}${r.label}`,
            String(r.active),
            `${r.paid} / ${r.free}`,
            fmtCents(r.mrrCents),
            `${(r.ramMB / 1024).toFixed(1)} GB`,
            r.costComplete ? fmtCents(r.costCents) : "incomplete",
            r.costComplete ? fmtCents(r.marginCents) : "—",
            r.marginPct != null ? fmtPct(r.marginPct) : "—",
          ])}
          empty="No live servers."
        />
      </Section>
    </div>
  );
}

