import { MeterBar } from "@/components/ui/charts";
import { Badge } from "@/components/ui/primitives";
import { capacityInsights } from "@/lib/insights/products";
import { CAPACITY_CRIT_DAYS, CAPACITY_WARN_DAYS } from "@/lib/insights/alerts";
import { fmtPct } from "@/lib/insights/stats";
import { Section } from "../_ui";

const gb = (mb: number) => `${(mb / 1024).toFixed(1)} GB`;

export async function CapacityTab() {
  const nodes = await capacityInsights();
  return (
    <div className="space-y-6">
      <p className="text-xs text-slate-500">
        Committed = Σ plan RAM of every non-deleted server on the node (game plan RAM for game servers). Used = Σ of the latest in-guest memory sample
        (ServerMemSample, last 2h) — only servers with a recent sample count, so it is a floor. Forecast = linear fit of committed RAM per day. Alerts fire at
        ≤{CAPACITY_WARN_DAYS}d (warn) / ≤{CAPACITY_CRIT_DAYS}d (critical) or 85% / 95% committed.
      </p>
      <div className="grid gap-6 xl:grid-cols-2">
        {nodes.map((n) => {
          const days = n.daysUntilFull.ok ? n.daysUntilFull.value : null;
          const tone = days === 0 || n.committedPct >= 0.95 || (days != null && days <= CAPACITY_CRIT_DAYS) ? "red" : n.committedPct >= 0.85 || (days != null && days <= CAPACITY_WARN_DAYS) ? "amber" : "green";
          return (
            <Section
              key={n.id}
              title={n.name}
              sub={`${n.region} · ${n.servers} server(s) · ${n.committedVcpu} vCPU committed${n.enabled ? "" : " · DISABLED"}${n.acceptsProvisions ? "" : " · not accepting provisions"}`}
              right={<Badge tone={tone as "red" | "amber" | "green"}>{days === 0 ? "full" : days != null ? `full in ~${days}d` : "not filling"}</Badge>}
            >
              <div className="space-y-3 text-sm">
                <div>
                  <div className="mb-1 flex justify-between">
                    <span>RAM committed</span>
                    <span className="tabular-nums">
                      {gb(n.committedRamMB)} / {gb(n.capacityRamMB)} · {fmtPct(n.committedPct)}
                    </span>
                  </div>
                  <MeterBar value={n.committedRamMB} max={Math.max(n.capacityRamMB, 1)} color="#8a70fb" />
                </div>
                <div>
                  <div className="mb-1 flex justify-between">
                    <span>RAM really used</span>
                    <span className="tabular-nums">
                      {n.usedRamMB != null ? `${gb(n.usedRamMB)} · ${fmtPct(n.usedPct)} (${n.usedSampleServers}/${n.servers} sampled)` : "no recent samples"}
                    </span>
                  </div>
                  <MeterBar value={n.usedRamMB ?? 0} max={Math.max(n.capacityRamMB, 1)} color="#22d3ee" />
                </div>
                <p className="text-xs text-slate-500">
                  {n.slopeMbPerDay.ok ? `Growth ${(n.slopeMbPerDay.value / 1024).toFixed(2)} GB/day — ${n.slopeSource}.` : n.slopeMbPerDay.reason}
                  {n.usedPct != null && n.committedPct > 0 && ` Oversubscription headroom: guests use ${fmtPct(n.usedRamMB! / Math.max(n.committedRamMB, 1))} of what they're sold.`}
                </p>
              </div>
            </Section>
          );
        })}
      </div>
      {nodes.length === 0 && <p className="text-sm text-slate-500">No nodes registered.</p>}
    </div>
  );
}

