import Link from "next/link";
import { jobInsights, supportInsights } from "@/lib/insights/ops";
import { mrrNow } from "@/lib/insights/revenue";
import type { InsightsRange } from "@/lib/insights/range";
import { fmtDuration, fmtPct } from "@/lib/insights/stats";
import { Grid, Kpi, MaybeValue, Section, Table, Bars } from "../_ui";

export async function OperationsTab({ range }: { range: InsightsRange }) {
  const mrr = await mrrNow();
  const [j, s] = await Promise.all([jobInsights(range), supportInsights(range, mrr.payingCustomers)]);
