              : [r.type, String(r.total), String(r.failed), fmtPct(r.failRate, 1), String(r.queuedNow), fmtDuration(r.e2eP50), fmtDuration(r.e2eP95), <span key="e" className="text-xs text-slate-400">{r.topError ?? ""}</span>],
