import Link from "next/link";
import { partnerInsights, emailInsights } from "@/lib/insights/growth";
import type { InsightsRange } from "@/lib/insights/range";
import { fmtCents, fmtPct } from "@/lib/insights/stats";
import { Grid, Kpi, Section, Table } from "../_ui";

export async function GrowthTab({ range }: { range: InsightsRange }) {
  const [p, e] = await Promise.all([partnerInsights(range), emailInsights(range)]);
  return (
    <div className="space-y-6">
      <Grid>
        <Kpi label="Partner link clicks" value={p.totals.clicks.toLocaleString()} />
        <Kpi label="Customers attached" value={String(p.totals.attached)} />
        <Kpi label="Partner-attributed revenue" value={fmtCents(p.totals.revenueBaseCents)} note="commission base, voided rows excluded" />
        <Kpi label="Commission accrued" value={fmtCents(p.totals.commissionCents)} note={p.totals.revenueBaseCents ? `${fmtPct(p.totals.commissionCents / p.totals.revenueBaseCents)} of attributed revenue` : undefined} />
      </Grid>

      <Section title="Partner / creator performance" sub="Clicks from ReferralClick, attachments from PartnerCustomer, revenue + commission from PartnerCommission (refund/chargeback reversals shown separately).">
        <Table
          head={["Partner", "Type", "Status", "Clicks", "Click→signup", "Attached", "All-time attached", "Revenue", "Commission", "Reversed"]}
          rows={p.rows.map((r) => [
            <Link key="p" href={`/admin/partners/${r.id}`} className="hover:underline">
              {r.name} <span className="text-slate-500">({r.code})</span>
            </Link>,
            r.type ?? "—",
            r.status.toLowerCase(),
            String(r.clicks),
            r.clicks ? fmtPct(r.clicksConverted / r.clicks, 1) : "—",
            String(r.attached),
            String(r.attachedAllTime),
            fmtCents(r.revenueBaseCents),
            fmtCents(r.commissionCents),
            r.reversedCents ? fmtCents(r.reversedCents) : "—",
          ])}
          empty="No partners yet."
        />
      </Section>

      <Section title="Email performance by template" sub="EmailLog in range (transactional, onboarding, win-back, outreach). Opens are inflated by Apple Mail Privacy Protection and link scanners — treat clicks as the real signal.">
        <Table
          head={["Template", "Sent", "Failed", "Opened", "Open %", "Clicked", "Click %"]}
          rows={[...e.rows, e.totals].map((r) => [r.template, String(r.sent), String(r.failed), String(r.opened), fmtPct(r.openRate), String(r.clicked), fmtPct(r.clickRate, 1)])}
          empty="No email sent in this range."
        />
      </Section>
    </div>
  );
}

