import { paymentInsights } from "@/lib/insights/growth";
import type { InsightsRange } from "@/lib/insights/range";
import { fmtCents } from "@/lib/insights/stats";
import { Bars, Grid, Kpi, Section, Table } from "../_ui";

export async function PaymentsTab({ range }: { range: InsightsRange }) {
  const p = await paymentInsights(range);
  const fails = p.failureEmails.reduce((s, f) => s + f.count, 0);
  return (
    <div className="space-y-6">
      <Grid>
        <Kpi label="Payment-failure notices" value={String(fails)} cur={fails} prev={p.failureEmailsPrev} higherIsBetter={false} note={`${p.usersWithFailures} customer(s) affected`} />
        <Kpi label="Servers in dunning now" value={String(p.dunningNow.reduce((s, d) => s + d.count, 0))} />
        <Kpi label="Refunded" value={fmtCents(p.refunds.cents)} cur={p.refunds.cents} prev={p.refundsPrev.cents} higherIsBetter={false} note={`${p.refunds.count} refund row(s) · ${p.refundedInvoices} invoice(s) from this range refunded`} />
        <Kpi label="Chargebacks recorded" value={String(p.chargebacksRecorded)} cur={p.chargebacksRecorded} prev={p.chargebacksPrev} higherIsBetter={false} note="admin-recorded only (no dispute webhook yet)" />
      </Grid>

      <div className="grid gap-6 xl:grid-cols-2">
        <Section title="Failure notices by type" sub="Emails the billing engine sent because a charge failed.">
          <Bars rows={p.failureEmails.map((f) => ({ label: f.template, value: f.count }))} color="#f59e0b" empty="No payment failures in this range." />
        </Section>
        <Section title="Dunning pipeline (now)" sub="Live servers by dunning stage.">
          <Bars rows={p.dunningNow.map((d) => ({ label: `Stage ${d.stage}`, value: d.count }))} color="#f87171" empty="No server is in dunning." />
          <p className="mt-3 text-xs text-slate-500">
            {p.overdueInvoices.count} OPEN invoice(s) older than 7 days ({fmtCents(p.overdueInvoices.cents)}).
          </p>
        </Section>
      </div>

      <Section title="Recent refunds" sub="Ledger rows starting “Refund —” or “Write-off”. Chargebacks only appear when an admin records them against an invoice (Stripe disputes have no webhook in this codebase yet — see docs/ADMIN-INSIGHTS-PROPOSALS.md).">
        <Table head={["When", "Customer", "Amount", "Note"]} rows={p.recentRefunds.map((r) => [r.when.toISOString().slice(0, 16).replace("T", " "), r.email, fmtCents(r.cents), <span key="d" className="text-xs text-slate-400">{r.description}</span>])} empty="No refunds in this range." />
      </Section>
    </div>
  );
}

