import { AreaChart } from "@/components/ui/charts";
import { BOT_KIND_LABEL, type BotKind } from "@/lib/bots/classify";
import { datacenterRangesGeneratedAt } from "@/lib/bots/datacenter";
import { crawlerInsights, visitBotStats } from "@/lib/insights/crawlers";
import type { InsightsRange } from "@/lib/insights/range";
import { fmtPct } from "@/lib/insights/stats";
import { fmtBytes } from "@/components/ui/primitives";
import { Bars, Grid, Kpi, Section, Table, axisLabels } from "../_ui";

const COLORS = ["#8a70fb", "#22d3ee", "#3b6be8", "#f59e0b", "#34d399"];

export async function CrawlersTab({ range }: { range: InsightsRange }) {
  const [c, v] = await Promise.all([crawlerInsights(range), visitBotStats(range)]);
  const search = c.rows.filter((r) => r.category === "search");
  return (
    <div className="space-y-6">
      <Grid>
        <Kpi label="Bot requests (access log)" value={c.totals.hits.toLocaleString()} note={c.hasData ? fmtBytes(c.totals.bytes) + " served to bots" : "no crawler data in range yet"} />
        <Kpi label="Verified Googlebot fetches" value={(c.rows.find((r) => r.bot === "googlebot")?.verifiedHits ?? 0).toLocaleString()} note={c.googlebot ? `${c.googlebot.distinctUrls30d.toLocaleString()} distinct URLs in 30d` : undefined} />
        <Kpi label="Bot share of beacon pageviews" value={fmtPct(v.total ? v.bots / v.total : null)} note={`${v.bots.toLocaleString()} of ${v.total.toLocaleString()} Visit rows`} />
        <Kpi label="IPs flagged now" value={String(v.flaggedIps)} note="honeypot / velocity, auto-expiring" />
      </Grid>

      {c.insights.length > 0 && (
        <Section title="Crawl-budget notes" sub="Generated from the numbers below — no rule of thumb is shown unless the data supports it.">
          <ul className="list-disc space-y-1.5 pl-5 text-sm text-slate-300">
            {c.insights.map((s) => (
              <li key={s}>{s}</li>
            ))}
          </ul>
        </Section>
      )}

      <Section title="Requests per day — top crawlers" sub={c.cursor ? `Parsed from the nginx access log by the worker; cursor last advanced ${c.cursor.updatedAt.toISOString().slice(0, 16).replace("T", " ")} UTC.` : "The worker hasn't parsed the access log yet (inert where /var/log/nginx/access.log is unreadable). Run scripts/backfill-crawler-log.ts for history."}>
        {c.series.lines.length ? (
          <>
            <AreaChart id="ins-crawl" series={c.series.lines.map((l, i) => ({ name: l.label, data: l.data, color: COLORS[i % COLORS.length] }))} xLabels={axisLabels(c.series.keys)} />
            <div className="mt-2 flex flex-wrap gap-4 text-xs text-slate-400">
              {c.series.lines.map((l, i) => (
                <span key={l.bot}>
                  <span className="mr-1 inline-block h-2 w-2 rounded-full" style={{ background: COLORS[i % COLORS.length] }} />
                  {l.label}
                </span>
              ))}
            </div>
          </>
        ) : (
          <p className="py-6 text-center text-sm text-slate-500">No crawler traffic recorded in this range.</p>
        )}
      </Section>

      <Section title="Every bot seen" sub="Verified = official IP list or forward-confirmed reverse DNS. Spoofed = claimed a verifiable crawler's UA and failed verification.">
        <Table
          head={["Bot", "Category", "Requests", "Page hits", "Verified", "Spoofed", "2xx", "3xx", "4xx", "5xx", "Distinct URLs", "Bandwidth"]}
          rows={c.rows.map((r) => [r.label, r.category, r.hits.toLocaleString(), r.pageHits.toLocaleString(), r.verifiedHits.toLocaleString(), r.spoofHits ? r.spoofHits.toLocaleString() : "—", r.s2xx.toLocaleString(), r.s3xx.toLocaleString(), r.s4xx.toLocaleString(), r.s5xx.toLocaleString(), r.distinctUrls.toLocaleString(), fmtBytes(r.bytes)])}
          empty="No bot traffic recorded in this range."
        />
      </Section>

      <div className="grid gap-6 xl:grid-cols-2">
        <Section title="Where crawl budget goes" sub="Requests by site section (all bots / verified Googlebot / verified Bingbot).">
          <Table head={["Section", "All bots", "Googlebot", "Bingbot"]} rows={c.sections.map((s) => [`/${s.section}`, s.hits.toLocaleString(), s.googlebot.toLocaleString(), s.bingbot.toLocaleString()])} />
        </Section>
        <Section title="Googlebot coverage & freshness" sub="From per-URL crawl state (CrawlerUrl).">
          {c.googlebot ? (
            <div className="space-y-1 text-sm">
              <p>
                <span className="text-2xl font-bold tabular-nums">{c.googlebot.distinctUrls30d.toLocaleString()}</span>
                <span className="ml-2 text-slate-400">distinct URLs fetched in the last 30 days</span>
              </p>
              <p className="text-xs text-slate-500">
                {c.googlebot.distinctUrlsAll.toLocaleString()} URLs ever seen · {c.googlebot.staleUrls.toLocaleString()} not re-fetched in 30d
                {c.googlebot.medianRecrawlDays != null && ` · median re-crawl interval ${c.googlebot.medianRecrawlDays.toFixed(1)}d`}
              </p>
              {search.length > 1 && <p className="pt-2 text-xs text-slate-500">Other search engines: {search.filter((s) => s.bot !== "googlebot").map((s) => `${s.label} ${s.distinctUrls.toLocaleString()} URLs`).join(" · ")}</p>}
            </div>
          ) : (
            <p className="py-6 text-center text-sm text-slate-500">No verified Googlebot URL data yet.</p>
          )}
        </Section>
      </div>

      <Section title="Search-engine errors" sub="URLs whose LAST fetch by a search crawler returned 4xx/5xx — fix or redirect these first.">
        <Table head={["Path", "Bot", "Status", "Fetches", "Last seen"]} rows={c.errorUrls.map((e) => [e.path, e.bot, String(e.status), String(e.hits), e.lastSeen.toISOString().slice(0, 10)])} empty="No search-crawler errors in this range." />
      </Section>

      <div className="grid gap-6 xl:grid-cols-2">
        <Section title="Beacon traffic by classification" sub={`Visit rows in range. Datacenter ranges generated ${datacenterRangesGeneratedAt()}.`}>
          <Bars rows={v.byKind.map((k) => ({ label: BOT_KIND_LABEL[k.kind as BotKind] ?? k.kind, value: k.count }))} />
          {v.unclassified > 0 && (
            <p className="mt-3 text-xs text-amber-300">
              {v.unclassified.toLocaleString()} rows predate the classifier — run <code>npx tsx scripts/backfill-bot-classification.ts</code>.
            </p>
          )}
        </Section>
        <Section title="Top bot reasons" sub="Why rows were classified as bots (botReason).">
          <Bars rows={v.topReasons.map((r) => ({ label: r.reason, value: r.count }))} color="#f59e0b" empty="No bot rows in this range." />
        </Section>
      </div>
    </div>
  );
}

