import { createReadStream } from "node:fs";
import readline from "node:readline";
import { parseLogLine, sectionOf } from "./lib/bots/access-log";
import { classifyHit } from "./lib/bots/classify";
(async () => {
  const ua = new Map<string, { n: number; ips: Set<string>; pages: number }>();
  const rl = readline.createInterface({ input: createReadStream("/var/log/nginx/access.log.1") });
  for await (const raw of rl) {
    const l = parseLogLine(raw); if (!l) continue;
    const e = ua.get(l.ua) ?? { n: 0, ips: new Set(), pages: 0 }; e.n++; if (e.ips.size < 5000) e.ips.add(l.ip);
    const s = sectionOf(l.path); if (s !== "asset" && s !== "api") e.pages++;
    ua.set(l.ua, e);
  }
  const kinds: Record<string, number> = {}; const human: [string, number, number, number][] = [];
  for (const [u, e] of ua) {
    const v = classifyHit({ ua: u, ip: null });
    kinds[v.botKind] = (kinds[v.botKind] ?? 0) + e.n;
    if (!v.isBot) human.push([u, e.n, e.ips.size, e.pages]);
  }
  console.log(kinds);
  human.sort((a, b) => b[1] - a[1]);
  for (const [u, n, ips, pages] of human.slice(0, 25)) console.log(n, ips, pages, u.slice(0, 140));
})();
EOF
timeout 300 npx tsx .eval-log.ts 2>&1 | tail -30; rm -f .eval-log.ts

