/**
 * CSV export for /admin/insights — one CSV per tab, built from the SAME
 * functions the page renders, so an export can never disagree with the screen.
 * Multiple tables in one file are separated by a blank line + a "# title" row.
 */
import type { InsightsRange } from "./range";
import type { InsightsTabKey } from "./tabs";
import { toCsv } from "./stats";
import { revenueInsights, churnInsights, mrrNow } from "./revenue";
import { funnelInsights, type Breakdown } from "./funnel";
import { productInsights, capacityInsights } from "./products";
import { jobInsights, supportInsights } from "./ops";
import { partnerInsights, emailInsights, paymentInsights } from "./growth";
import { crawlerInsights, visitBotStats } from "./crawlers";
import { churnRiskList } from "./alerts";

type Cell = string | number | boolean | null | undefined;
type Block = { title: string; rows: Cell[][] };

const c2d = (c: number | null | undefined) => (c == null ? "" : (c / 100).toFixed(2));
const ms2h = (ms: number | null | undefined) => (ms == null ? "" : (ms / 3_600_000).toFixed(2));
const pct = (f: number | null | undefined) => (f == null ? "" : (f * 100).toFixed(2));

function bd(title: string, b: Breakdown[]): Block {
  return { title, rows: [["label", "signups", "deployed", "paid"], ...b.map((x) => [x.label, x.signups, x.deployed, x.paid])] };
}

export async function insightsCsv(tab: InsightsTabKey, r: InsightsRange): Promise<string> {
  const blocks: Block[] = [];
  const header: Block = { title: "range", rows: [["from", "to_inclusive", "days", "prev_from", "prev_to_exclusive"], [r.fromStr, r.toStr, r.days, r.prevFrom.toISOString().slice(0, 10), r.prevTo.toISOString().slice(0, 10)]] };
  blocks.push(header);

  switch (tab) {
    case "overview":
    case "revenue": {
      const v = await revenueInsights(r);
      blocks.push({
        title: "summary",
        rows: [
          ["metric", "current_usd", "previous_usd"],
          ["earned_revenue", c2d(v.earned), c2d(v.earnedPrev)],
          ["cash_collected", c2d(v.cashIn), c2d(v.cashInPrev)],
          ["refunds", c2d(v.refunds.cents), c2d(v.refundsPrev.cents)],
          ["mrr_now", c2d(v.mrrCents), ""],
          ["arr_now", c2d(v.arrCents), ""],
          ["arpu_now", c2d(v.arpuCents), ""],
          ["paying_customers_now", v.payingCustomers, ""],
        ],
      });
