const c2d = (c: number | null | undefined) => (c == null ? "" : (c / 100).toFixed(2));
const ms2h = (ms: number | null | undefined) => (ms == null ? "" : (ms / 3_600_000).toFixed(2));
const pct = (f: number | null | undefined) => (f == null ? "" : (f * 100).toFixed(2));

function bd(title: string, b: Breakdown[]): Block {
  return { title, rows: [["label", "signups", "deployed", "paid"], ...b.map((x) => [x.label, x.signups, x.deployed, x.paid])] };
}

