import { NextResponse } from "next/server";
import { requireArea } from "@/lib/rbac";
import { parseRange } from "@/lib/insights/range";
import { INSIGHTS_TABS, type InsightsTabKey } from "@/lib/insights/tabs";
import { insightsCsv } from "@/lib/insights/csv";
import { recordAudit } from "@/lib/audit";

export const dynamic = "force-dynamic";

/** CSV export of one /admin/insights tab for the requested range. Admin-only, audited (it contains customer emails). */
export async function GET(req: Request) {
  const admin = await requireArea("analytics");
  const url = new URL(req.url);
  const tabParam = url.searchParams.get("tab") ?? "overview";
  const tab = (INSIGHTS_TABS.some((t) => t.key === tabParam) ? tabParam : "overview") as InsightsTabKey;
  const range = parseRange({
    from: url.searchParams.get("from") ?? undefined,
    to: url.searchParams.get("to") ?? undefined,
    preset: url.searchParams.get("preset") ?? undefined,
  });
  const csv = await insightsCsv(tab, range);
  await recordAudit(admin.id, "insights.export", `${tab} ${range.fromStr}..${range.toStr}`);
  return new NextResponse(csv, {
    headers: {
      "content-type": "text/csv; charset=utf-8",
      "content-disposition": `attachment; filename="nxeon-insights-${tab}-${range.fromStr}_${range.toStr}.csv"`,
      "cache-control": "no-store",
    },
  });
}

