/**
 * Synthetic data for exercising /admin/insights + the bot classifier in a
 * THROWAWAY database. Refuses to run against anything that isn't obviously a
 * scratch DB (name must start with nxeon_agt_ / nxeon_sbx_ AND NXEON_SANDBOX=1).
 *
 * Writes ONLY to the database — no files, no credentials file, no email. The
 * generated admin password is printed once to stdout.
 *
 *   NXEON_SANDBOX=1 DATABASE_URL=postgresql://…/nxeon_agt_x npx tsx scripts/seed-insights-sandbox.ts
 */
import { randomBytes, randomUUID } from "node:crypto";
import bcrypt from "bcryptjs";
import { db } from "../lib/db";
import { ingestLogText } from "../lib/bots/crawler-ingest";
import { classifyHit } from "../lib/bots/classify";

const url = process.env.DATABASE_URL ?? "";
const dbName = url.split("/").pop()?.split("?")[0] ?? "";
if (process.env.NXEON_SANDBOX !== "1" || !/^nxeon_(agt|sbx)_/.test(dbName)) {
  console.error(`refusing: DATABASE_URL db "${dbName}" is not a scratch DB (need nxeon_agt_* + NXEON_SANDBOX=1)`);
  process.exit(1);
}

let seed = 42;
const rnd = () => ((seed = (seed * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff);
const pick = <T,>(a: T[]) => a[Math.floor(rnd() * a.length)];
const DAY = 86_400_000;
const now = Date.now();
const ago = (d: number) => new Date(now - d * DAY - Math.floor(rnd() * DAY));

async function main() {
  const existing = await db.user.count();
  if (existing > 0) {
    console.error("refusing: database already has users (seed is for an empty scratch DB)");
    process.exit(1);
  }
  const pw = randomBytes(9).toString("base64url");
  const admin = await db.user.create({ data: { email: "admin@sandbox.test", name: "Sandbox Admin", passwordHash: await bcrypt.hash(pw, 10), role: "ADMIN" } });

  const os = await db.osTemplate.create({ data: { slug: "ubuntu-24", name: "Ubuntu", vmid: 9000 } });
  const plans = await Promise.all(
    [
      ["vps-1", "VPS 1", 1, 2048, 40, 599],
      ["vps-2", "VPS 2", 2, 4096, 80, 1199],
      ["vps-4", "VPS 4", 4, 8192, 160, 2399],
    ].map(([slug, name, cpu, ram, disk, price]) => db.plan.create({ data: { slug: slug as string, name: name as string, cpuCores: cpu as number, ramMB: ram as number, diskGB: disk as number, priceCents: price as number } })),
  );
  const games = ["minecraft", "valheim", "rust", "palworld", "terraria", "cs2"];
  const gamePlans = await Promise.all(games.map((g, i) => db.gamePlan.create({ data: { gameFamily: g, name: `${g} 4 GB`, ramMB: 4096, diskGB: 40, priceCents: 899 + i * 100, basePlanId: plans[1].id } })));
  const nodes = await Promise.all([
    db.node.create({ data: { name: "primary", pveNode: "pve1", apiUrl: "https://127.0.0.1:8006", tokenId: "x", tokenSecret: "x", publicIp: "198.51.100.1", isPrimary: true, capacityRamMB: 56_000, monthlyCostCents: 9900, region: "sgp1" } }),
    db.node.create({ data: { name: "node-2", pveNode: "pve2", apiUrl: "https://127.0.0.2:8006", tokenId: "x", tokenSecret: "x", publicIp: "198.51.100.2", capacityRamMB: 120_000, monthlyCostCents: null, region: "fsn1", subnetPrefix: "10.20.2." } }),
  ]);

  // ---- customers, servers, money ----
  const partner = await db.referralPartner.create({ data: { name: "PixelPlays", code: "pixel", type: "CREATOR" } });
  const partner2 = await db.referralPartner.create({ data: { name: "HostTalk", code: "hosttalk", type: "AGENCY" } });
  const countries = ["United States", "Germany", "Vietnam", "Brazil", "India", "Thailand"];
  const heard = ["google", "youtube", "reddit", "friend", null, "skipped"];
  let host = 0;
  for (let i = 0; i < 70; i++) {
    const created = ago(Math.floor(rnd() * 200));
    const u = await db.user.create({
      data: {
        email: `cust${i}@sandbox.test`,
        name: `Customer ${i}`,
        passwordHash: "x",
        createdAt: created,
        billingCountry: rnd() < 0.6 ? pick(countries) : null,
        heardAboutUs: pick(heard),
      },
    });
    if (rnd() < 0.25) await db.partnerCustomer.create({ data: { partnerId: rnd() < 0.6 ? partner.id : partner2.id, customerId: u.id, attachedAt: created } });
    const pays = rnd() < 0.55;
    if (rnd() < 0.2) await db.freeMinecraftServer.create({ data: { userId: u.id, subdomain: `free${i}`, containerName: `mc-free-${i}`, status: "RUNNING", createdAt: new Date(created.getTime() + 3600_000) } });
    if (!pays) continue;
    const nServers = 1 + Math.floor(rnd() * 2);
    for (let s = 0; s < nServers; s++) {
      const isGame = rnd() < 0.6;
      const sCreated = new Date(created.getTime() + Math.floor(rnd() * 5 * DAY));
      if (sCreated.getTime() > now) continue;
      const gp = isGame ? pick(gamePlans) : null;
      const plan = gp ? plans[1] : pick(plans);
      const churned = rnd() < 0.18;
      if (churned) {
        await db.serverArchive.create({
          data: { originalId: randomUUID(), hostname: `srv-${host++}`, userId: u.id, userEmail: u.email, isGameServer: isGame, gameFamily: gp?.gameFamily, serviceName: gp?.name ?? plan.name, nodeName: "primary", totalSpentCents: 1500, provisionedAt: sCreated, deletedAt: new Date(Math.min(now - DAY, sCreated.getTime() + (10 + rnd() * 60) * DAY)), reason: "expired" },
        });
        continue;
      }
      const srv = await db.server.create({
        data: {
          name: `srv-${host}`,
          hostname: `srv-${host++}.sandbox.test`,
          status: rnd() < 0.85 ? "RUNNING" : "STOPPED",
          userId: u.id,
          planId: plan.id,
          gamePlanId: gp?.id,
          osTemplateId: os.id,
          nodeId: rnd() < 0.7 ? nodes[0].id : rnd() < 0.5 ? nodes[1].id : null,
          createdAt: sCreated,
          expiresAt: new Date(now + (rnd() * 30 - 3) * DAY),
          autoRenew: rnd() < 0.85,
          dunningStage: rnd() < 0.08 ? 1 + Math.floor(rnd() * 3) : 0,
        },
      });
      await db.serverMemSample.create({ data: { serverId: srv.id, usedBytes: BigInt(Math.floor((gp?.ramMB ?? plan.ramMB) * (0.25 + rnd() * 0.6) * 1048576)), totalBytes: BigInt((gp?.ramMB ?? plan.ramMB) * 1048576), ts: new Date(now - 20 * 60_000) } });
    }
    // Monthly top-ups + debits from first server onward.
    for (let m = 0; m < 7; m++) {
      const t = new Date(created.getTime() + m * 30 * DAY + DAY);
      if (t.getTime() > now) break;
      const amt = 600 + Math.floor(rnd() * 2000);
      await db.walletTransaction.create({ data: { userId: u.id, amountCents: amt, description: "Wallet top-up (card)", stripeSessionId: `cs_test_${randomUUID()}`, createdAt: t } });
      await db.walletTransaction.create({ data: { userId: u.id, amountCents: -amt, description: "Renewal — server", createdAt: new Date(t.getTime() + 3600_000) } });
      const inv = await db.invoice.create({ data: { userId: u.id, amountCents: amt, description: "Renewal", lineItems: [], status: "PAID", paidAt: t, createdAt: t } });
      const pc = await db.partnerCustomer.findUnique({ where: { customerId: u.id } });
      if (pc) await db.partnerCommission.create({ data: { partnerId: pc.partnerId, customerId: u.id, invoiceId: inv.id, baseCents: amt, ratePct: 10, amountCents: Math.round(amt * 0.1), kind: m === 0 ? "ORDER" : "RENEWAL", createdAt: t } });
    }
    if (rnd() < 0.08) await db.walletTransaction.create({ data: { userId: u.id, amountCents: -900, description: "Refund — wallet-only refund · goodwill", createdAt: ago(Math.floor(rnd() * 40)) } });
    if (rnd() < 0.15) await db.emailLog.create({ data: { toEmail: u.email, subject: "Payment failed", html: "", template: "payment_failed", userId: u.id, createdAt: ago(Math.floor(rnd() * 40)) } });
  }

  // Tickets with staff replies.
  const customers = await db.user.findMany({ where: { role: "CUSTOMER" }, select: { id: true } });
  for (let i = 0; i < 40; i++) {
    const u = pick(customers);
    const t0 = ago(Math.floor(rnd() * 60));
    const status = pick(["OPEN", "ANSWERED", "CLOSED", "CLOSED", "CUSTOMER_REPLY"] as const);
    const tk = await db.ticket.create({ data: { subject: pick(["Server won't start", "Billing question", "Mod install help", "Refund request", "Latency"]), userId: u.id, status, priority: pick(["LOW", "NORMAL", "NORMAL", "HIGH"] as const), createdAt: t0, updatedAt: new Date(t0.getTime() + rnd() * 3 * DAY) } });
    await db.ticketMessage.create({ data: { ticketId: tk.id, authorId: u.id, body: "help", createdAt: t0 } });
    if (status !== "OPEN") await db.ticketMessage.create({ data: { ticketId: tk.id, authorId: admin.id, body: "on it", isStaff: true, createdAt: new Date(t0.getTime() + (0.2 + rnd() * 20) * 3600_000) } });
  }

  // Jobs.
  const types = ["PROVISION", "START", "STOP", "REBOOT", "REINSTALL", "DELETE"] as const;
  for (let i = 0; i < 400; i++) {
    const t0 = ago(Math.floor(rnd() * 60));
    const failed = rnd() < 0.07;
    await db.job.create({ data: { type: pick([...types]), status: failed ? "FAILED" : "DONE", error: failed ? pick(["Proxmox API timeout after 120s", "guest agent not running", "clone failed: storage full"]) : null, createdAt: t0, updatedAt: new Date(t0.getTime() + (5 + rnd() * 240) * 1000) } });
  }

  // Partner clicks + email logs.
  for (let i = 0; i < 300; i++) await db.referralClick.create({ data: { code: rnd() < 0.7 ? "pixel" : "hosttalk", createdAt: ago(Math.floor(rnd() * 60)), convertedUserId: rnd() < 0.08 ? pick(customers).id : null } });
  for (let i = 0; i < 500; i++) {
    const tpl = pick(["deploy_winback", "onboarding_tips", "creator_outreach_followup", "ticket_reply", "server_deployed"]);
    await db.emailLog.create({ data: { toEmail: `x${i}@sandbox.test`, subject: tpl, html: "", template: tpl, createdAt: ago(Math.floor(rnd() * 60)), openedAt: rnd() < 0.45 ? new Date() : null, clickedAt: rnd() < 0.08 ? new Date() : null, status: rnd() < 0.02 ? "FAILED" : "SENT" } });
  }

  // ---- Visits: humans + the real bot shapes seen on prod ----
  const humanUAs = [
    "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/153.0.0.0 Safari/537.36",
    "Mozilla/5.0 (Linux; Android 10; K) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/153.0.0.0 Mobile Safari/537.36",
    "Mozilla/5.0 (iPhone; CPU iPhone OS 18_7 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/26.6.1 Mobile/15E148 Safari/604.1",
    "Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:156.0) Gecko/20100101 Firefox/156.0",
  ];
  const botUAs = ["Lightpanda/1.0", "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36", "Mozilla/5.0 (iPhone; CPU iPhone OS 13_2_3 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/13.0.3 Mobile/15E148 Safari/604.1"];
  const paths = ["/", "/vps", "/game-servers", "/game-servers/minecraft", "/mods/games/minecraft", "/pricing", "/blog/how-to-host-valheim"];
  const rows: Parameters<typeof db.visit.createMany>[0]["data"] = [];
  for (let i = 0; i < 6000; i++) {
    const bot = rnd() < 0.45;
    const ua = bot ? pick(botUAs) : pick(humanUAs);
    const ip = `203.0.${Math.floor(rnd() * 255)}.${Math.floor(rnd() * 255)}`;
    const createdAt = ago(Math.floor(rnd() * 45));
    const v = classifyHit({ ua, ip, now: createdAt });
    rows.push({
      ip,
      path: pick(paths),
      ua,
      kind: "marketing",
      createdAt,
      visitorId: randomUUID(),
      sessionId: randomUUID(),
      isEntry: true,
      referrer: bot ? null : rnd() < 0.5 ? "https://www.google.com/" : null,
      durationMs: bot ? null : Math.floor(rnd() * 90_000),
      country: pick(countries),
      geocoded: true,
      // ~1/3 of rows left unclassified so the backfill can be exercised.
      ...(i % 3 === 0 ? {} : { isBot: v.isBot, botKind: v.botKind, botReason: v.botReason }),
    });
  }
  await db.visit.createMany({ data: rows });

  // ---- Crawler log (synthetic lines in nginx combined format) ----
  const fmt = (d: Date) => {
    const m = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"][d.getUTCMonth()];
    const p = (n: number) => String(n).padStart(2, "0");
    return `${p(d.getUTCDate())}/${m}/${d.getUTCFullYear()}:${p(d.getUTCHours())}:${p(d.getUTCMinutes())}:${p(d.getUTCSeconds())} +0000`;
  };
  const crawlers: [string, string][] = [
    ["66.249.66.1", "Mozilla/5.0 (compatible; Googlebot/2.1; +http://www.google.com/bot.html)"],
    ["203.0.113.66", "Mozilla/5.0 (compatible; Googlebot/2.1; +http://www.google.com/bot.html)"], // spoof candidate (unverifiable from TEST-NET → stays declared)
    ["54.157.84.74", "Mozilla/5.0 AppleWebKit/537.36 (KHTML, like Gecko; compatible; Amazonbot/0.1; +https://developer.amazon.com/support/amazonbot) Chrome/119.0.6045.214 Safari/537.36"],
    ["40.77.167.1", "Mozilla/5.0 AppleWebKit/537.36 (KHTML, like Gecko; compatible; bingbot/2.0; +http://www.bing.com/bingbot.htm) Chrome/116.0.1938.76 Safari/537.36"],
    ["198.51.100.9", "Mozilla/5.0 AppleWebKit/537.36 (KHTML, like Gecko; compatible; ClaudeBot/1.0; +claudebot@anthropic.com)"],
    ["198.51.100.10", "Lightpanda/1.0"],
  ];
  const lines: string[] = [];
  for (let i = 0; i < 20_000; i++) {
    const [ip, ua] = pick(crawlers);
    const d = new Date(now - Math.floor(rnd() * 30) * DAY - Math.floor(rnd() * DAY));
    const path = rnd() < 0.6 ? `/mods/minecraft/mod-${Math.floor(rnd() * 3000)}` : rnd() < 0.5 ? pick(paths) : rnd() < 0.5 ? "/_next/static/chunks/main.js" : "/sitemap-mods-1.xml";
    const status = rnd() < 0.05 ? 404 : rnd() < 0.03 ? 301 : rnd() < 0.01 ? 502 : 200;
    lines.push(`${ip} - - [${fmt(d)}] "GET ${path} HTTP/1.1" ${status} ${Math.floor(rnd() * 50_000)} "-" "${ua}"`);
  }
  const st = await ingestLogText(lines.join("\n"), { lookupBudget: 0 });

  // A few MRR snapshots so the history chart has something.
  for (let d = 14; d >= 1; d--) {
    const date = new Date(Date.UTC(new Date(now - d * DAY).getUTCFullYear(), new Date(now - d * DAY).getUTCMonth(), new Date(now - d * DAY).getUTCDate()));
    await db.insightsSnapshot.create({ data: { date, metric: "mrr_cents", value: 40_000 + (14 - d) * 900 + Math.floor(rnd() * 1500) } });
    await db.insightsSnapshot.create({ data: { date, metric: "node_committed_ram_mb", scopeId: nodes[0].id, value: 30_000 + (14 - d) * 800 } });
  }

  console.log(`seeded: ${await db.user.count()} users, ${await db.server.count()} servers, ${await db.visit.count()} visits, crawler lines ${st.lines} (${st.botHits} bot)`);
  console.log(`admin login: admin@sandbox.test / ${pw}`);
}

main()
  .catch((e) => {
    console.error(e);
    process.exitCode = 1;
  })
  .finally(() => db.$disconnect());

