import { test } from "node:test";
import assert from "node:assert/strict";
import { percentile, linearFit, daysUntil, relChange, toCsv, zScore, monthDiff, fmtCents } from "../lib/insights/stats.ts";
import { parseRange, bucketKeys, granularity } from "../lib/insights/range.ts";
import { payingAt, firstPaidStart, type PaidLife } from "../lib/insights/common.ts";

test("percentile interpolates and handles empties", () => {
  assert.equal(percentile([], 50), null);
  assert.equal(percentile([5], 95), 5);
  assert.equal(percentile([1, 2, 3, 4], 50), 2.5);
  assert.equal(percentile([10, 1, 7], 0), 1);
  assert.equal(percentile([10, 1, 7], 100), 10);
});

test("linear fit + days until full", () => {
  const fit = linearFit([0, 1, 2, 3].map((x) => ({ x, y: 100 + 10 * x })))!;
  assert.ok(Math.abs(fit.slope - 10) < 1e-9);
  assert.ok(Math.abs(fit.r2 - 1) < 1e-9);
  assert.equal(linearFit([{ x: 1, y: 1 }]), null);
  assert.equal(daysUntil(100, 200, 10), 10);
  assert.equal(daysUntil(250, 200, 10), 0);
  assert.equal(daysUntil(100, 200, 0), null); // not growing → never, not a fake date
  assert.equal(daysUntil(100, 200, -5), null);
});

test("relChange / zScore", () => {
  assert.equal(relChange(150, 100), 0.5);
  assert.equal(relChange(5, 0), null);
  assert.equal(zScore(5, [5, 5, 5]), null);
  assert.ok((zScore(0, [10, 12, 8, 11, 9]) ?? 0) < -5);
});

test("CSV escaping and formula-injection guard", () => {
  const csv = toCsv([
    ["a,b", 'say "hi"', null, 3],
    ["=HYPERLINK(1)", "-5", "-x", "+cmd"],
  ]);
  assert.equal(csv.split("\r\n")[0], '"a,b","say ""hi""",,3');
  assert.equal(csv.split("\r\n")[1], "'=HYPERLINK(1),-5,'-x,'+cmd");
});

test("range parsing: presets, explicit, previous period, caps", () => {
  const now = new Date("2026-10-01T12:00:00Z");
  const r = parseRange({}, now);
  assert.equal(r.preset, "30d");
  assert.equal(r.days, 30);
  assert.equal(r.toStr, "2026-10-01");
  assert.equal(r.prevTo.getTime(), r.from.getTime());
  assert.equal(r.prevTo.getTime() - r.prevFrom.getTime(), r.to.getTime() - r.from.getTime());
  const e = parseRange({ from: "2026-09-01", to: "2026-09-10" }, now);
  assert.equal(e.days, 10);
  assert.equal(e.fromStr, "2026-09-01");
  assert.equal(e.toStr, "2026-09-10");
  const bad = parseRange({ from: "2026-13-99", preset: "nope" }, now);
  assert.equal(bad.preset, "30d");
  const future = parseRange({ from: "2026-09-25", to: "2027-01-01" }, now);
  assert.equal(future.toStr, "2026-10-01"); // never past today
  const mtd = parseRange({ preset: "mtd" }, now);
  assert.equal(mtd.fromStr, "2026-10-01");
  assert.equal(granularity(30), "day");
  assert.equal(granularity(90), "week");
  assert.equal(granularity(800), "month");
  assert.equal(bucketKeys(new Date("2026-09-01T00:00:00Z"), new Date("2026-09-04T00:00:00Z"), "day").length, 3);
});

test("paid lifetimes → paying-at + first paid start", () => {
  const d = (s: string) => new Date(`${s}T00:00:00Z`);
  const lives: PaidLife[] = [
    { userId: "a", start: d("2026-01-10"), end: d("2026-03-01") },
    { userId: "a", start: d("2026-05-01"), end: null },
    { userId: "b", start: d("2026-02-01"), end: d("2026-02-15") },
  ];
  assert.deepEqual([...payingAt(lives, d("2026-02-10"))].sort(), ["a", "b"]);
  assert.deepEqual([...payingAt(lives, d("2026-04-01"))], []);
  assert.deepEqual([...payingAt(lives, d("2026-06-01"))], ["a"]);
  assert.equal(firstPaidStart(lives).get("a")?.toISOString().slice(0, 10), "2026-01-10");
  assert.equal(monthDiff("2025-11", "2026-02"), 3);
  assert.equal(fmtCents(123456), "$1,234.56");
  assert.equal(fmtCents(-500), "-$5.00");
});

