// Temporary Playwright walk of /admin/insights (not committed). Screenshots go to $OUT (under /tmp).
import { chromium } from "playwright";
const BASE = process.env.BASE ?? "http://localhost:3108";
const OUT = process.env.OUT;
const PW = process.env.ADMIN_PW;
const tabs = ["overview", "revenue", "customers", "funnel", "products", "capacity", "operations", "growth", "payments", "crawlers"];
const browser = await chromium.launch();
const ctx = await browser.newContext({ viewport: { width: 1440, height: 1000 } });
const page = await ctx.newPage();
const errors = [];
page.on("pageerror", (e) => errors.push(`pageerror: ${e.message}`));
page.on("console", (m) => { if (m.type() === "error") errors.push(`console: ${m.text().slice(0, 200)}`); });
await page.goto(`${BASE}/admin/login`, { waitUntil: "domcontentloaded", timeout: 180000 });
await page.fill('input[name="email"]', "admin@sandbox.test");
await page.fill('input[name="password"]', PW);
await Promise.all([page.waitForURL(/\/admin(?!\/login)/, { timeout: 180000 }), page.click('button[type="submit"]')]);
const results = [];
for (const t of tabs) {
  const res = await page.goto(`${BASE}/admin/insights?tab=${t}&preset=90d`, { waitUntil: "networkidle", timeout: 240000 });
  const body = await page.locator("main, body").first().innerText();
  const bad = /Application error|Unhandled Runtime Error|NaN|undefined|Infinity/.exec(body);
  results.push(`${t}: HTTP ${res?.status()} ${bad ? "SUSPECT:" + bad[0] : "ok"} len=${body.length}`);
  await page.screenshot({ path: `${OUT}/desk-${t}.png`, fullPage: true });
}
// CSV export
const csv = await page.request.get(`${BASE}/admin/insights/export?tab=crawlers&preset=30d`);
results.push(`csv: ${csv.status()} ${csv.headers()["content-type"]} ${(await csv.text()).split("\n").slice(0, 3).join(" | ").slice(0, 200)}`);
// Bot toggle round-trip
await page.goto(`${BASE}/admin/insights?tab=overview&preset=30d`, { waitUntil: "networkidle" });
await page.getByRole("button", { name: /Bots excluded/ }).click();
await page.waitForSelector("text=Bot traffic is INCLUDED", { timeout: 60000 });
results.push("toggle on: banner shown");
await page.getByRole("button", { name: /Including bots/ }).click();
await page.waitForSelector("text=Bots excluded", { timeout: 60000 });
results.push("toggle off: ok");
// Mobile
await page.setViewportSize({ width: 390, height: 844 });
for (const t of ["overview", "customers", "crawlers"]) {
  await page.goto(`${BASE}/admin/insights?tab=${t}&preset=30d`, { waitUntil: "networkidle", timeout: 240000 });
  const overflow = await page.evaluate(() => document.documentElement.scrollWidth - window.innerWidth);
  results.push(`mobile ${t}: horizontal overflow ${overflow}px`);
  await page.screenshot({ path: `${OUT}/mob-${t}.png`, fullPage: true });
}
// honeypot + track ingest (public endpoints)
const hp = await page.request.get(`${BASE}/api/track/hp`, { headers: { "user-agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/153.0.0.0 Safari/537.36" } });
results.push(`honeypot: ${hp.status()} ${hp.headers()["x-robots-tag"]}`);
console.log(results.join("\n"));
console.log("ERRORS:\n" + [...new Set(errors)].slice(0, 20).join("\n"));
await browser.close();

